// =====================================================================
//  MarsL - a building and strategy game on the Red Planet
//  Needs: Node.js 22.13 or newer (uses the built-in SQLite database)
//  Only extra package: express   ->   npm install express
// =====================================================================

const express = require("express");
const crypto = require("crypto");
const path = require("path");
const { DatabaseSync } = require("node:sqlite");

const app = express();

// ---------- running online: settings come from "environment variables" ----------
// You don't need any of these at home. They are for special setups:
// PORT         the port to listen on (hosting services set this themselves)
// HOST         only listen on this address, e.g. 127.0.0.1 = only this computer
//              (+ a Cloudflare tunnel). Default: everybody who can reach the laptop.
// DATA_DIR     the folder for marsl.db (on a host: the persistent disk!)
// INVITE_CODE  your own invite code for new players. "off" = anybody may register.
//              If not set, MarsL makes up a code and shows it when it starts.
// TRUST_PROXY  set to 1 when running behind a hosting proxy (Render and alwaysdata are detected)
const PORT = Number(process.env.PORT) || 3000;
// alwaysdata tells the app where to listen with IP (and PORT)
const HOST = process.env.HOST || process.env.IP || undefined;
const DATA_DIR = process.env.DATA_DIR || __dirname;
const INVITE_SETTING = (process.env.INVITE_CODE || "").trim();
// A tunnel (cloudflared, Tailscale Funnel...) runs on this computer and tells us
// the player's real address and that the connection is https. We only believe
// such hints when they come from this computer itself ("loopback").
// Hosting services (Render, alwaysdata...) put their own proxy in front of the game
app.set("trust proxy", process.env.RENDER || process.env.TRUST_PROXY || process.env.IP ? 1 : "loopback");

app.disable("x-powered-by");
app.use((req, res, next) => {
  // standard safety headers for every answer
  res.setHeader("X-Content-Type-Options", "nosniff");
  res.setHeader("X-Frame-Options", "DENY");
  res.setHeader("Referrer-Policy", "same-origin");
  res.setHeader("Permissions-Policy", "camera=(), microphone=(), geolocation=()");
  // the page may only load its own scripts and fonts - nothing from other sites
  res.setHeader(
    "Content-Security-Policy",
    "default-src 'self'; script-src 'self' 'unsafe-inline'; style-src 'self' 'unsafe-inline'; " +
      "font-src 'self'; img-src 'self' data:; connect-src 'self'; frame-ancestors 'none'; base-uri 'none'; form-action 'self'" + (req.secure ? "; upgrade-insecure-requests" : "")
  );
  if (req.secure) res.setHeader("Strict-Transport-Security", "max-age=31536000");
  next();
});

// ---------- smaller downloads: big pages and answers are sent gzip-compressed ----------
// (the game page is about 1 MB of text and shrinks to about a quarter)
const GZ_CACHE = new Map();
app.use((req, res, next) => {
  if (!/\bgzip\b/.test(req.headers["accept-encoding"] || "")) return next();
  const send = res.send.bind(res);
  res.send = (body) => {
    if (typeof body !== "string" || body.length < 2048 || res.getHeader("Content-Encoding") || req.method === "HEAD") return send(body);
    let gz = GZ_CACHE.get(body);
    if (!gz) {
      gz = require("zlib").gzipSync(body, { level: 6 });
      if (body.length > 100000) { GZ_CACHE.set(body, gz); if (GZ_CACHE.size > 12) GZ_CACHE.delete(GZ_CACHE.keys().next().value); }
    }
    if (!res.getHeader("Content-Type")) res.setHeader("Content-Type", "text/html; charset=utf-8");
    res.setHeader("Content-Encoding", "gzip");
    res.setHeader("Vary", "Accept-Encoding");
    return send(gz);
  };
  next();
});

// ---------- fonts: served from this server, never from Google ----------
// (loading Google Fonts from Google's servers sends the player's IP address
// to Google, which is not allowed in the EU without consent). Put the font
// files from fonts.google.com (Barlow, Chakra Petch; free, SIL Open Font
// License) into a "fonts" folder next to server.js. Without them the game
// simply uses the device's own fonts.
const FONT_FILES = [
  ["Barlow", 400, "Barlow-Regular"], ["Barlow", 500, "Barlow-Medium"], ["Barlow", 600, "Barlow-SemiBold"], ["Barlow", 700, "Barlow-Bold"],
  ["Chakra Petch", 600, "ChakraPetch-SemiBold"], ["Chakra Petch", 700, "ChakraPetch-Bold"],
  // Toybox Deluxe (1.0.222): variable fonts, one file each
  ["Fredoka", "300 700", "Fredoka-Variable"], ["Figtree", "300 900", "Figtree-Variable"],
];
// The game finds its font files itself: any file in the "fonts" folder whose name starts with the
// font's name and contains the wanted style works (for example "Fredoka-VariableFont_wdth,wght.ttf"
// straight from fonts.google.com). Only fonts that are really there are announced.
const FONT_DIR = require("path").join(__dirname, "fonts");
function fontFileFor(f) {
  let list = [];
  try { list = require("fs").readdirSync(FONT_DIR); } catch (e) { return null; }
  const base = f[0].replace(/\s+/g, "").toLowerCase(), style = f[2].split("-").pop().toLowerCase();
  const ok = list.filter((n) => /\.(woff2|ttf)$/i.test(n) && n.replace(/[\s_-]/g, "").toLowerCase().startsWith(base) && !/italic/i.test(n));
  const pick = (re) => ok.filter((n) => re.test(n)).sort((x, y) => (/\.woff2$/i.test(y) ? 1 : 0) - (/\.woff2$/i.test(x) ? 1 : 0) || x.length - y.length)[0];
  return pick(new RegExp("^" + f[2].replace(/[-]/g, "[-_ ]?") + "\\.", "i")) || pick(new RegExp(style, "i")) || null;
}
const FONT_PICK = {};
const FONTS_CSS = FONT_FILES.map((f) => {
  const file = fontFileFor(f);
  if (!file) return "";
  FONT_PICK[file] = true;
  return '@font-face{font-family:"' + f[0] + '";font-style:normal;font-weight:' + f[1] + ";font-display:swap;src:url(/fonts/" + encodeURIComponent(file) + ') format("' + (/\.woff2$/i.test(file) ? "woff2" : "truetype") + '")}';
}).filter(Boolean).join("\n");
app.get("/fonts.css", (req, res) => {
  res.setHeader("Content-Type", "text/css; charset=utf-8");
  res.setHeader("Cache-Control", "public, max-age=86400");
  res.end(FONTS_CSS || "/* no font files on this server: the system fonts are used */");
});
app.get("/fonts/:file", (req, res) => {
  const file = req.params.file || "";
  if (!FONT_PICK[file] || /[\/\\]/.test(file)) return res.status(404).end();
  require("fs").readFile(require("path").join(FONT_DIR, file), (err, buf) => {
    if (err) return res.status(404).end();
    res.setHeader("Content-Type", /\.woff2$/i.test(file) ? "font/woff2" : "font/ttf");
    res.setHeader("Cache-Control", "public, max-age=2592000");
    res.end(buf);
  });
});

// ---------- every address may only send so many requests ----------
// The page asks about twice a second; 150 requests in 10 seconds is far more
// than a real player ever needs, but stops scripts that hammer the server.
const REQUEST_LIMIT = 150;
const requestCounts = new Map(); // ip -> { n, reset }
app.use((req, res, next) => {
  const now = Date.now();
  let c = requestCounts.get(req.ip);
  if (!c || c.reset < now) {
    c = { n: 0, reset: now + 10000 };
    requestCounts.set(req.ip, c);
  }
  c.n += 1;
  if (c.n > REQUEST_LIMIT) return res.status(429).json({ error: "Whoa, slow down! Too many requests." });
  next();
});
setInterval(() => {
  const now = Date.now();
  for (const [ip, c] of requestCounts) if (c.reset < now) requestCounts.delete(ip);
}, 60000);

// ---------- only our own page may change things ----------
// Every change is a POST with JSON from our page. A strange website that
// tries to send one in your name (with your login cookie) is turned away.
app.use((req, res, next) => {
  if (req.method !== "POST") return next();
  const origin = req.headers.origin;
  if (origin) {
    let host = null;
    try {
      host = new URL(origin).host;
    } catch (e) {}
    if (host !== req.headers.host) return res.status(403).json({ error: "Requests from other websites are not allowed" });
  }
  if (!req.is("application/json")) return res.status(415).json({ error: "Please send JSON" });
  next();
});
// no giant requests (farm lists may be a bit bigger: many targets)
const smallJson = express.json({ limit: "20kb" });
const farmJson = express.json({ limit: "400kb" });
app.use((req, res, next) => (req.path === "/api/farm" ? farmJson : smallJson)(req, res, next));

