const OUTPOST_CLAIM_CUT = 0.02; // each level shortens the claim time by 2%
const OUTPOST_GUARD_BONUS = 0.1; // level 5: your garrison at a landmark defends 10% better
const OUTPOST_RELIC_BONUS = 0.25; // level 10: the landmark bonus is 25% stronger
const OUTPOST_GUARDIAN_CUT = 0.25; // level 15: wild guardians fight 25% weaker against armies from this colony
// Level of the Expedition Base (0 = none) of a colony state
function outpostLevelOf(s) {
  return s && s.buildings ? s.buildings.reduce((m, b) => (b.type === "outpost" && b.level > m ? b.level : m), 0) : 0;
}
// The colony needs an Expedition Base to claim landmarks at all
function landmarkRangeOf(s) {
  const lv = outpostLevelOf(s);
  return lv ? LANDMARK_RANGE + LANDMARK_RANGE_PER_LEVEL * (lv - 1) : 0;
}
// Real milliseconds a claim takes for this colony
function claimMsOf(s) {
  const lv = outpostLevelOf(s);
  return Math.round(((LANDMARK_CLAIM_HOURS * 3600000) / MOVE_SPEED) * (1 - OUTPOST_CLAIM_CUT * lv));
}
const LANDMARK_DEF_BONUS = 0.15; // guards at a landmark defend 15% better
const LANDMARK_GUARD = { name: "Ancient Guardian", icon: "🗿", defG: 50, defA: 50 };
const LANDMARK_REGROW_HOURS = 1.5; // a half-beaten guard force is back to full strength within hours: win in one go

