function colonyQuests(colony) {
  const retention = retentionOf(colony.userId);
  if (!retention.questStarterColony) {
    const first = db.prepare("SELECT id FROM colonies WHERE user_id = ? ORDER BY id LIMIT 1").get(colony.userId);
    retention.questStarterColony = first ? first.id : colony.id;
    saveRetention(colony.userId, retention);
  }
  return colony.id === retention.questStarterColony ? QUESTS : EXPANSION_QUESTS;
}
function questInventoryReward(userId, resources) {
  const hero = heroOf(userId);
  if (!hero) return false;
  let crate = heroCrate(hero);
  if (!crate) {
    crate = { id: crypto.randomBytes(4).toString("hex"), kind: "crate", icon: "📦", name: "Bounty stash", res: {} };
    hero.bag.push(crate);
  }
  for (const resource of RESOURCES) crate.res[resource] = (crate.res[resource] || 0) + (resources[resource] || 0);
  heroSave(userId, hero);
  return true;
}

// Quests that were claimed in THIS colony
function claimedQuests(colony) {
  colony.state.quests = colony.state.quests || {};
  return colony.state.quests;
}

// Everything the quest checks need - only this one colony counts
function questContext(colony) {
  // a player with the most colonies allowed can't found more: those quests count as done
  const maxColonies = false; // no colony limit
  return { cols: [colony], s: colony.state, qs: colony.state.qstats || {}, maxColonies };
}

// Quests used to belong to the whole account. Those claims now belong to
// the player's first colony (once, when the server starts).
for (const u of db.prepare("SELECT id, quests FROM users WHERE quests != '{}'").all()) {
  const first = db.prepare("SELECT id FROM colonies WHERE user_id = ? ORDER BY id LIMIT 1").get(u.id);
  if (first) {
    const c = loadColony(first.id);
    try {
      c.state.quests = Object.assign(JSON.parse(u.quests), c.state.quests || {});
      saveColony(c.id, c.state);
    } catch (e) {}
  }
  db.prepare("UPDATE users SET quests = '{}' WHERE id = ?").run(u.id);
}

function questView(colony) {
  const claimed = claimedQuests(colony);
  const q = questContext(colony);
  const quests = colonyQuests(colony);
  const open = quests.filter((x) => !claimed[x.id]);
  return {
    done: quests.filter((x) => claimed[x.id]).length,
    total: quests.length,
    list: open.map((x) => {
      const [have, goal] = x.check(q);
      // building names in the player's own tribe language ("Royal Coop" instead of HQ)
      const names = tribeOf(colony.tribe).names;
      const text = x.text.replace(/\{(\w+)\}/g, (m, k) => (k === "goal" ? String(goal) : names[k] ? names[k][0] : k));
      return { id: x.id, icon: x.icon, title: x.title, text, have, goal, ready: have >= goal, reward: giftScale(x.reward), xp: questXp(x), go: x.go, train: x.train || 0, kind: questKind(x.id) };
    }),
  };
}

// ---------- 📋 the mission board ----------
// Every quest belongs to one of three cards on the board: build, army or world.
const QUEST_ARMY = /^(barracks|army|sim$|spy$|camp1$|waves$|hunt|lab$|upgrade$|wins|hangar$|hospital$)/;
const QUEST_WORLD = /^(hub|colony|crown$)/;
function questKind(id) {
  id = id.replace(/^exp-/, "");
  if (id.indexOf("camps") === 0) return "army";
  return QUEST_ARMY.test(id) ? "army" : QUEST_WORLD.test(id) ? "world" : "build";
}
// Badges the board hands out for finished missions (account-wide count)
const BOARD_BADGES = [
  { n: 60, key: "board60", icon: "🏅", title: "Board Legend: 60 missions done" },
];
const BOARD_ALLY_GIFT = 200; // joining or founding an alliance (once)
function boardDone(userId, n) {
  const r = retentionOf(userId);
  r.board = (r.board || 0) + (n || 1);
  saveRetention(userId, r);
  for (const b of BOARD_BADGES) if (r.board >= b.n) giveBadge(userId, b.key, b.icon, b.title);
  return r.board;
}
function boardView(userId) {
  const r = retentionOf(userId), n = r.board || 0;
  const next = BOARD_BADGES.find((b) => n < b.n);
  return { done: n, next: next ? { n: next.n, icon: next.icon, title: next.title } : null, ally: !!r.boardAlly };
}

// ---------- 🎓 graduation and 🧾 Mars Mutual Insurance ----------
// In the last 24 hours of beginner protection the game shows a graduation
// check. Graduating early ends protection and pays a reward. Afterwards the
// first two heavy losses are partly covered: 30% of what was stolen comes
// back the next morning, with a claim letter.
const GRAD_WINDOW_MS = 24 * 3600000;
const GRAD_GIFT = 500; // of each resource
const INS_SHARE = 0.3;
const INS_CLAIMS = 2;
const INS_HEAVY = 0.25; // a loss is heavy when a raid takes at least a quarter of what was there
const INS_MORNING_UTC = 6; // payouts at 06:00 UTC
function typicalRaidAttack() {
  return Math.round(1500 * speedScale());
}
function graduationView(userId, colony, now) {
  const p = protectionOf(userId, now);
  if (!p.active || p.vacation) return null;
  const inWindow = p.until - now <= GRAD_WINDOW_MS || p.points >= p.pointsNeeded * 0.75;
  if (!inWindow) return null;
  const s = colony.state, tribe = tribeOf(colony.tribe);
  const hide = bunkerOf(s);
  let atRisk = 0;
  for (const r of RESOURCES) atRisk += Math.max(0, Math.floor(s.res[r]) - hide);
  const d = defenseOf(s.troops, tribe, s.upgrades);
  addDefense(d, militiaOf(s));
  const wall = perkOf(colony.tribe, "wall") * levelOf(s, "wall");
  const def = Math.round(d.g * (1 + wall / 100) * specDef(s));
  const atk = typicalRaidAttack();
  return { until: p.until, atRisk, hide, def, atk, verdict: def >= atk ? "holds" : def >= atk * 0.6 ? "close" : "falls", gift: GRAD_GIFT };
}
app.post("/api/graduate", requireLogin, (req, res) => {
  if (req.sitterId) return res.status(403).json({ error: "Use your own account to graduate." });
  const now = Date.now();
  const colony = loadColony(req.colonyId);
  const g = colony && graduationView(req.user.id, colony, now);
  if (!g) return res.status(400).json({ error: "Graduation opens in the last 24 hours of your protection." });
  endProtection(req.user.id);
  const r = retentionOf(req.user.id);
  r.bank = r.bank || {};
  for (const k of RESOURCES) r.bank[k] = (r.bank[k] || 0) + g.gift;
  r.graduated = now;
  saveRetention(req.user.id, r);
  giveBadge(req.user.id, "grad", "🎓", "Graduated early from beginner protection");
  req.extra = { graduated: g.gift };
  withColony(req, res, null);
});
function insuranceView(userId) {
  const I = retentionOf(userId).ins || { used: 0, claims: [] };
  const hpk = heroPerks(userId);
  return { left: Math.max(0, INS_CLAIMS + (hpk && hpk.qm75 ? 1 : 0) - I.used), pending: I.claims.filter((c) => !c.paid).map((c) => ({ payAt: c.payAt, total: lootTotal(c.back) })) };
}
function nextMorning(now) {
  const d = new Date(now);
  let t = Date.UTC(d.getUTCFullYear(), d.getUTCMonth(), d.getUTCDate(), INS_MORNING_UTC);
  while (t < now + 4 * 3600000) t += 86400000;
  return t;
}
function insuranceClaim(userId, loot, before, byName, at) {
  if (!userId || BOT_IDS.has(userId)) return;
  const total = lootTotal(loot);
  if (!total || total < before * INS_HEAVY) return;
  const r = retentionOf(userId);
  const I = r.ins || (r.ins = { used: 0, claims: [] });
  const hpk = heroPerks(userId);
  if (I.used >= INS_CLAIMS + (hpk && hpk.qm75 ? 1 : 0)) return;
  I.used++;
  const back = {};
  for (const k of RESOURCES) back[k] = Math.floor((loot[k] || 0) * INS_SHARE);
  I.claims.push({ back, by: byName, at, payAt: nextMorning(at), n: I.used });
  r.insPending = 1;
  saveRetention(userId, r);
}
const INS_LETTERS = [
  "Dear valued colonist, our assessors inspected the scene and found one footprint, two empty crates and a strong smell of victory (theirs). Your claim is approved.",
  "Dear valued colonist, after a thorough investigation (we asked a passing rover) we confirm you were robbed. Please find enclosed your refund and a voucher for one (1) stronger door.",
];
function insuranceTick(now) {
  for (const u of db.prepare("SELECT id FROM users WHERE retention LIKE '%\"insPending\":1%'").all()) {
    const r = retentionOf(u.id);
    const I = r.ins;
    if (!I) { delete r.insPending; saveRetention(u.id, r); continue; }
    const due = I.claims.filter((c) => !c.paid && c.payAt <= now);
    if (!due.length) continue;
    r.bank = r.bank || {};
    for (const c of due) {
      for (const k of RESOURCES) r.bank[k] = (r.bank[k] || 0) + (c.back[k] || 0);
      c.paid = now;
      addReport(u.id, c.payAt, "🧾", "Insurance " + c.n + "/" + INS_CLAIMS, {
        mission: "insurance", back: c.back, by: c.by, at: c.at, n: c.n, of: Math.max(c.n, INS_CLAIMS),
        letter: INS_LETTERS[(c.n - 1) % INS_LETTERS.length],
      });
    }
    if (I.claims.every((c) => c.paid)) delete r.insPending;
    saveRetention(u.id, r);
  }
}
setInterval(() => { try { insuranceTick(Date.now()); } catch (e) { console.error("insurance", e); } }, 60000);

// ---------- 🏁 a won server ----------
// When an alliance lights the Aurora the round is over: every job and every
// troop movement is cancelled (troops on the road are back home at once) and
// no new actions are accepted. The game shows a window with the winner.
function serverWon() {
  const se = readSeason();
  if (!se || se.kind !== "aurora" || !se.winner) return null;
  const aid = parseInt(String(se.winner.key || "").slice(1), 10);
  let members = [];
  try { members = aid ? allianceMembers(aid).map((m) => m.username) : []; } catch (e) {}
  return { name: se.winner.name, at: se.winner.at, round: se.number || 0, members, next: plannedStarts().find((t) => t > Date.now()) || 0 };
}
function freezeWonWorld() {
  const w = serverWon();
  if (!w || settingOf("won_frozen", "") === String(w.at)) return;
  setSetting("won_frozen", String(w.at));
  const cols = {};
  const get = (id) => cols[id] || (cols[id] = loadColony(id));
  for (const m of db.prepare("SELECT * FROM movements").all()) {
    const c = get(m.attacker_id);
    if (!c) continue;
    let tr = {};
    try { tr = JSON.parse(m.troops) || {}; } catch (e) {}
    for (const k of Object.keys(tr)) {
      const n = Number(tr[k]) || 0;
      if (n <= 0) continue;
      c.state.troops[k] = (c.state.troops[k] || 0) + n;
      c.state.away[k] = Math.max(0, (c.state.away[k] || 0) - n);
    }
  }
  db.prepare("DELETE FROM movements").run();
  for (const r of db.prepare("SELECT id FROM colonies").all()) {
    const c = get(r.id);
    if (!c) continue;
    const st = c.state;
    st.queue = [];
    for (const b of Object.keys(st.training || {})) st.training[b] = [];
    if (st.healJob && st.healJob.troops) for (const k of Object.keys(st.healJob.troops)) st.wounded[k] = (st.wounded[k] || 0) + st.healJob.troops[k];
    st.labJob = null; st.smithJob = null; st.terraJob = null; st.healJob = null;
  }
  for (const id of Object.keys(cols)) if (cols[id]) saveColony(cols[id].id, cols[id].state);
}
const WON_BLOCKED = /^\/(field|building|demolish|construct|cancel|train|cancel-training|research|upgrade-unit|cancel-job|heal|trade|routes|swap|redistribute|terraform|send|waves|cancel-move|recall|redirect|farm|aurora|hero|adventure|boost|build-help|market|npc-trade|spot|traps|daily|tribe-power|quest|end-protection|graduate|plan|spec|firstday|alliance\/(bank|project|plan))(\/|$)/;
app.use("/api", (req, res, next) => {
  if (req.method !== "POST" || !WON_BLOCKED.test(req.path)) return next();
  const w = serverWon();
  if (!w) return next();
  freezeWonWorld();
  res.status(409).json({ error: "This server has been won by " + w.name + ". The round is over.", won: w });
});

// 🏷️ pick (or change) the specialisation of this colony (HQ 10)
const SPEC_CHANGE_COST = 2000; // of each resource to change it later
app.post("/api/spec", requireLogin, (req, res) => {
  withColony(req, res, (s, tribe) => {
    const key = String((req.body || {}).key || "");
    if (!COLONY_SPECS[key]) return "Unknown specialisation";
    if (levelOf(s, "hq") < SPEC_HQ) return "Specialisations open at " + tribe.names.hq[0] + " level " + SPEC_HQ;
    if (actNow() < 1) return "Specialisations open with Act 2 (Expansion) on server day " + actDays()[1];
    if (s.spec === key) return "This colony already is a " + COLONY_SPECS[key].name;
    if (s.spec) {
      const n = SPEC_CHANGE_COST;
      const cost = { wood: n, stone: n, metal: n, food: n };
      if (!canAfford(s, cost)) return "Changing costs " + n + " of each resource";
      const old = COLONY_SPECS[s.spec].building;
      if (jobsOf(s).some((q) => q.kind === "building" && (q.type === old || (s.buildings[q.slot] && s.buildings[q.slot].type === old)))) return "Finish or cancel the job on the " + tribe.names[old][0] + " first";
      pay(s, cost);
      // the old unique building is torn down
      s.buildings.forEach((b, i) => { if (b.type === old) s.buildings[i] = { type: null, level: 0 }; });
    }
    s.spec = key;
    return null;
  });
});

app.post("/api/quest", requireLogin, (req, res) => {
  withColony(req, res, (s, tribe, colony) => {
    const id = String((req.body || {}).id || "");
    const quest = colonyQuests(colony).find((x) => x.id === id);
    if (!quest) return "Unknown quest";
    const claimed = claimedQuests(colony);
    if (claimed[id]) return "Already claimed in this colony";
    const [have, goal] = quest.check(questContext(colony));
    if (have < goal) return "Not done yet!";
    if (!questInventoryReward(req.user.id, giftScale(quest.reward))) return "Commander inventory unavailable";

    claimed[id] = Date.now(); // saved together with the colony
    boardDone(req.user.id);
    // 🎖️ a little experience for the commander as well
    const h = heroOf(req.user.id);
    if (h) heroAfterFight(req.user.id, h, { xp: questXp(quest), at: Date.now() });
    return null;
  });
});

// Skip a quest without reward. A safety net: whatever happens, a quest
// can never block the list forever.
app.post("/api/quest/skip", requireLogin, (req, res) => {
  withColony(req, res, (s, tribe, colony) => {
    const id = String((req.body || {}).id || "");
    const claimed = claimedQuests(colony);
    if (!colonyQuests(colony).some((x) => x.id === id)) return "Unknown quest";
    if (claimed[id]) return "Already done in this colony";
    claimed[id] = -Date.now(); // negative = skipped, no reward
    return null;
  });
});

// =====================================================================
//  FIGHT SIMULATOR - the same battle math as the real thing,
//  but with numbers you type in. Nothing really happens.
// =====================================================================

// Everything the simulator page needs: all tribes and monsters, and good
// guesses for a target (from your latest spy report on it).
app.get("/api/sim-setup", requireLogin, (req, res) => {
  const me = loadColony(req.colonyId);
  const tribes = {};
  for (const key in TRIBES) {
    tribes[key] = {
      name: TRIBES[key].name,
      icon: TRIBES[key].icon,
      units: Object.keys(TRIBES[key].units)
        .filter((k) => !isSettler(TRIBES[key].units[k]))
        .map((k) => {
          const u = TRIBES[key].units[k];
          return { key: k, icon: u.icon, name: u.name, type: u.type, atk: u.atk, defG: u.defG, defA: u.defA, scout: isScout(u) };
        }),
    };
  }
  const monsters = Object.keys(MONSTERS).map((k) => ({ key: k, icon: MONSTERS[k].icon, name: MONSTERS[k].name }));

  // a guess for the defender
  const x = parseInt(req.query.x, 10);
  const y = parseInt(req.query.y, 10);
  let target = null;
  // the newest spy report with a garrison at x|y (Landing Zone, held landmark)
  const spiedGarrison = () => {
    const reps = db.prepare("SELECT created_at, data FROM reports WHERE user_id = ? AND data LIKE '%\"mission\":\"scout\"%' ORDER BY id DESC LIMIT 40").all(req.user.id);
    for (const r of reps) {
      const d = JSON.parse(r.data);
      if (!d.intel || !d.defender || d.defender.x !== x || d.defender.y !== y || !d.intel.garrison) continue;
      const troops = {};
      for (const u of d.intel.garrison) if (u.key) troops[u.key] = (troops[u.key] || 0) + u.count;
      return { troops, at: r.created_at };
    }
    return null;
  };
  if (!Number.isNaN(x) && !Number.isNaN(y)) {
    const col = db.prepare("SELECT id, name, tribe FROM colonies WHERE x = ? AND y = ?").get(x, y);
    if (col) {
      const owner = db.prepare("SELECT user_id FROM colonies WHERE id = ?").get(col.id);
      target = { kind: "colony", name: col.name, tribe: col.tribe, troops: {}, wall: 0, shield: allyLevel(allyIdOf(owner.user_id), "shield"), spiedAt: null };
      if (owner.user_id === req.user.id) {
        // your own colony: no spying needed, the simulator gets the real numbers
        const own = loadColony(col.id);
        Object.assign(target.troops, own.state.troops);
        target.wall = levelOf(own.state, "wall");
        target.hq = levelOf(own.state, "hq");
        target.mine = true;
      }
      // the newest successful spy report about this colony
      const reps = db
        .prepare("SELECT created_at, data FROM reports WHERE user_id = ? AND data LIKE '%\"mission\":\"scout\"%' ORDER BY id DESC LIMIT 40")
        .all(req.user.id);
      for (const r of target.mine ? [] : reps) {
        const d = JSON.parse(r.data);
        if (!d.intel || !d.intel.troops || !d.defender || d.defender.x !== x || d.defender.y !== y) continue;
        for (const u of d.intel.troops) if (u.key) target.troops[u.key] = u.count;
        for (const sp of d.intel.support || []) for (const u of sp.units || []) if (u.key) target.troops[u.key] = (target.troops[u.key] || 0) + u.count;
        target.wall = d.intel.wall || 0;
        target.spiedAt = r.created_at;
        break;
      }
    } else if (x === 0 && y === 0) {
      const z = zoneRow();
      target = { kind: "zone", name: "Landing Zone", robots: z.holder_id ? 0 : z.robots, held: !!z.holder_id };
      if (z.holder_id) {
        const hc = loadColony(z.holder_id);
        const sp = spiedGarrison();
        Object.assign(target, { tribe: hc ? hc.tribe : "human", troops: sp ? sp.troops : {}, spiedAt: sp ? sp.at : null, shield: hc ? allyLevel(allyIdOf(hc.userId), "shield") : 0 });
      }
    } else if (landmarkAtXY(x, y)) {
      // 🗿 a landmark: its guardians (public, the map shows them) or the holder's garrison (needs a spy report)
      const l = landmarkAtXY(x, y);
      const r = landmarkRow(l);
      target = { kind: "landmark", name: l.icon + " " + l.name, held: !!r.holder_id, guards: r.holder_id ? landmarkGuardsFull(l) : r.guards, weak: outpostLevelOf(me.state) >= 15 };
      if (r.holder_id) {
        const hc = loadColony(r.holder_id);
        const sp = spiedGarrison();
        Object.assign(target, { tribe: hc ? hc.tribe : "human", troops: sp ? sp.troops : {}, spiedAt: sp ? sp.at : null, shield: hc ? allyLevel(allyIdOf(hc.userId), "shield") : 0, outpost5: hc ? outpostLevelOf(hc.state) >= 5 : false });
      }
    } else if (terrainAt(x, y) === "n") {
      const camp = campAt(x, y, Date.now());
      target = { kind: "camp", name: campKind(x, y).name, monsters: Object.assign({}, camp.troops) };
    }
  }
  let up = 0;
  for (const k in me.state.upgrades) up = Math.max(up, me.state.upgrades[k]);
  // 🎖️ my commander and its gear, to drop into the simulator
  let myHero = null;
  const hh = heroOf(req.user.id, Date.now());
  if (hh) {
    const G = heroGearStats(hh);
    myHero = { name: hh.name, level: hh.level, str: hh.pts.str, gAtk: G.atk, gDef: G.def, gAtkPct: heroBonus(hh).atk, gDefPct: heroBonus(hh).def, mend: heroBonus(hh).mend };
  }
  res.json({
    hero: myHero,
    heroMax: { level: HERO_MAX_LEVEL, str: HERO_SKILLS.str.max },
    tribes,
    monsters,
    me: { tribe: me.tribe, upgrade: up, ups: Object.assign({}, me.state.upgrades), hospital: levelOf(me.state, "hospital"), drums: allyLevel(allyIdOf(req.user.id), "drums"), shield: allyLevel(allyIdOf(req.user.id), "shield") },
    target,
    limits: { ally: ALLY_MAX_LEVEL, wall: MAX_LEVEL, upgrade: UPGRADE_MAX, hq: maxLevelOf("hq"), hospital: MAX_LEVEL, luck: Math.round(LUCK * 100) },
  });
});

// Run a simulated fight. Body:
// { mission, atk: { tribe, troops, upgrade, hospital },
//   def: { kind: colony|camp|zone, tribe, troops, upgrade, wall, hq, hospital, monsters, robots, held }, luck }
app.post("/api/simulate", requireLogin, (req, res) => {
  const b = req.body || {};
  const num = (v, max) => Math.max(0, Math.min(max, Math.floor(Number(v) || 0)));
  const mission = b.mission === "raid" ? "raid" : "attack";
  const A = b.atk || {};
  const D = b.def || {};
  const atkTribe = TRIBES[A.tribe] ? TRIBES[A.tribe] : TRIBES.human;
  const clean = (troops, tribe) => {
    const t = {};
    for (const k in troops || {}) if (tribe.units[k] && !isSettler(tribe.units[k])) {
      const n = num(troops[k], 1e6);
      if (n) t[k] = n;
    }
    return t;
  };
  // upgrade level per unit (ups = { key: level }); "lv" is the old "same for all"
  const allUp = (tribe, lv, ups) => {
    const u = {};
    for (const k in tribe.units) u[k] = num(ups && ups[k] !== undefined && ups[k] !== "" ? ups[k] : lv, UPGRADE_MAX);
    return u;
  };
  const saved = (lost, level, tk) => {
    const out = {};
    let free = hospitalBeds(level);
    for (const k in lost) {
      const n = Math.min(free, Math.floor((lost[k] * perkOf(tk, "hospital") * level) / 100));
      if (n > 0) {
        out[k] = n;
        free -= n;
      }
    }
    return out;
  };

  // 🎖️ a commander on a side: level, skill points and the stats of its gear
  const heroOn = (H) => {
    if (!H || !H.on) return null;
    return {
      level: Math.max(1, num(H.level, HERO_MAX_LEVEL)),
      str: num(H.str, HERO_SKILLS.str.max),
      gAtk: num(H.gAtk, 99999),
      gDef: num(H.gDef, 99999),
      gAtkPct: Math.max(0, Math.min(30, Number(H.gAtkPct) || 0)),
      gDefPct: Math.max(0, Math.min(30, Number(H.gDefPct) || 0)),
      mend: Math.max(0, Math.min(15, Number(H.mend) || 0)),
    };
  };
  const heroAtk = heroOn(A.hero);
  const atkTroops = clean(A.troops, atkTribe);
  if (countUnits(atkTroops) === 0 && !heroAtk) return res.json({ empty: true });
  try { // 🎓 combat training: the first simulation counts
    const me = loadColony(req.colonyId);
    if (me && !(me.state.qstats && me.state.qstats.simulated)) { colonyStat(me, "simulated", 1); saveColony(me.id, me.state); }
  } catch (e) {}
  // 🥁 War Drums level of the attacker's alliance
  let attack = allyAttackLevel(attackOf(atkTroops, atkTribe, allUp(atkTribe, A.upgrade, A.ups)), num(A.drums, ALLY_MAX_LEVEL));
  let heroAtkPts = 0;
  if (heroAtk) {
    heroAtkPts = Math.round((HERO_ATK_BASE + HERO_ATK_LVL * (heroAtk.level - 1) + heroAtk.str * HERO_SKILLS.str.per + heroAtk.gAtk) * speedScale());
    const k = 1 + heroAtk.gAtkPct / 100;
    attack = { g: attack.g * k + heroAtkPts, a: attack.a * k };
  }
  let heroDefPts = 0;

  let defense = { g: 0, a: 0 };
  let multiplier = 1;
  let defTroops = {};
  let defTribe = null;
  const kind = ["colony", "camp", "zone", "landmark"].includes(D.kind) ? D.kind : "colony";
  if (kind === "camp") {
    for (const k in D.monsters || {}) if (MONSTERS[k]) {
      const n = num(D.monsters[k], 1e6);
      if (n) defTroops[k] = n;
    }
    defense = campDefense(defTroops);
  } else if (kind === "zone" && !D.held) {
    const robots = num(D.robots, 1e6);
    defTroops = robots ? { robot: robots } : {};
    defense = { g: robots * ZONE_ROBOT.defG, a: robots * ZONE_ROBOT.defA };
  } else if (kind === "landmark" && !D.held) {
    // the ancient guardians (weaker against an Expedition Base level 15)
    const guards = num(D.guards, 1e6);
    const weak = D.weak ? 1 - OUTPOST_GUARDIAN_CUT : 1;
    defTroops = guards ? { guard: guards } : {};
    defense = { g: guards * LANDMARK_GUARD.defG * weak, a: guards * LANDMARK_GUARD.defA * weak };
  } else {
    defTribe = TRIBES[D.tribe] ? TRIBES[D.tribe] : TRIBES.human;
    defTroops = clean(D.troops, defTribe);
    defense = defenseOf(defTroops, defTribe, allUp(defTribe, D.upgrade, D.ups));
    const shield = num(D.shield, ALLY_MAX_LEVEL) * ALLY_PROJECTS.shield.per; // 🛡️ Shield Wall level
    if (kind === "zone") {
      multiplier = 1 + ZONE_DEF_BONUS + shield;
    } else if (kind === "landmark") {
      multiplier = 1 + LANDMARK_DEF_BONUS + shield + (D.outpost5 ? OUTPOST_GUARD_BONUS : 0);
    } else {
      const militia = MILITIA_BASE + MILITIA_PER_HQ * softLevel(num(D.hq, MAX_LEVEL));
      addDefense(defense, { g: militia, a: militia * 0.5 });
      multiplier = 1 + (perkOf(D.tribe, "wall") * num(D.wall, MAX_LEVEL)) / 100 + shield;
    }
    const heroDef = heroOn(D.hero);
    if (heroDef) {
      heroDefPts = Math.round((HERO_DEF_BASE + HERO_DEF_LVL * (heroDef.level - 1) + heroDef.str * HERO_SKILLS.str.per + heroDef.gDef) * speedScale());
      const k = 1 + heroDef.gDefPct / 100;
      defense.g = defense.g * k + heroDefPts;
      defense.a = defense.a * k + heroDefPts;
    }
  }

  // 🙅 morale (the simulator takes it as a number) and ✈️ the phases against colonies
  const moraleCut = Math.max(0, Math.min(MORALE_MAX * 100, Number(b.morale) || 0)) / 100;
  attack = { g: attack.g * (1 - moraleCut), a: attack.a * (1 - moraleCut) };
  const phases = kind === "colony" && defTribe ? combatPhases(atkTroops, atkTribe, allUp(atkTribe, A.upgrade, A.ups), attack, defTroops, defTribe, allUp(defTribe, D.upgrade, D.ups), defense, num(D.wall, MAX_LEVEL)) : null;
  const luck = Math.max(-LUCK, Math.min(LUCK, (Number(b.luck) || 0) / 100));
  const f = fight(mission, attack, defense, multiplier, luck);
  // Attribute the same attack-strength calculation used by fight(), not individual kills.
  const attackFactor = (1 + luck) * (f.combo ? 1 + COMBINED_ARMS_BONUS : 1);
  const upgrades = allUp(atkTribe, A.upgrade, A.ups);
  const contributions = Object.keys(atkTroops).map((key) => {
    const u = atkTribe.units[key];
    const base = allyAttackLevel(attackOf({ [key]: atkTroops[key] }, atkTribe, upgrades), num(A.drums, ALLY_MAX_LEVEL));
    const strength = (base.g + base.a) * (heroAtk ? 1 + heroAtk.gAtkPct / 100 : 1) * attackFactor;
    return { key, name: u.name, icon: u.icon, count: atkTroops[key], strength };
  });
  if (heroAtk) contributions.push({ key: "commander", name: "Commander", icon: "🎖️", count: 1, strength: heroAtkPts * attackFactor });
  const contributionTotal = contributions.reduce((sum, u) => sum + u.strength, 0);
  contributions.forEach((u) => { u.share = contributionTotal > 0 ? u.strength / contributionTotal * 100 : 0; });

  const simLoss = f.atkFrac >= 1 ? 1 : f.atkFrac * (1 - (heroAtk && A.tribe === "alien" ? heroAtk.mend : 0) / 100);
  const atkLost = applyLosses(atkTroops, simLoss);
  const defLost = applyLosses(defTroops, f.defFrac);
  // what would happen with the worst and the best luck?
  const worst = fight(mission, attack, defense, multiplier, -LUCK);
  const best = fight(mission, attack, defense, multiplier, LUCK);

  let defList;
  if (kind === "camp") defList = monsterList(defTroops, defLost);
  else if (kind === "zone" && !D.held) defList = robotList(defTroops.robot || 0, defLost.robot || 0);
  else if (kind === "landmark" && !D.held) defList = guardianList(defTroops.guard || 0, Math.min(defTroops.guard || 0, f.defFrac >= 1 ? defTroops.guard || 0 : Math.round((defTroops.guard || 0) * f.defFrac)));
  else defList = unitList(defTroops, defTribe, defLost);

  // rams: what would be left of the wall?
  let wallHit = null;
  if (kind === "colony" && mission === "attack" && f.attackerWins) {
    const left = Object.assign({}, atkTroops);
    subtractTroops(left, atkLost);
    const power = siegePower(left, atkTribe, allUp(atkTribe, A.upgrade, A.ups));
    const from = num(D.wall, MAX_LEVEL);
    if (power > 0 && from > 0) wallHit = { from, to: wallAfterRams(from, power, perkOf(D.tribe, "rams")) };
  } else if (kind === "colony" && mission === "attack" && f.A >= f.D * SIEGE_CLOSE) {
    const power = siegePower(atkTroops, atkTribe, allUp(atkTribe, A.upgrade, A.ups)) * 0.5;
    const from = num(D.wall, MAX_LEVEL);
    if (power > 0 && from > 0) wallHit = { from, to: wallAfterRams(from, power, perkOf(D.tribe, "rams")), close: true };
  }

  res.json({
    mission,
    wallHit,
    phases,
    attackerWins: f.attackerWins,
    facts: fightFacts(f),
    contributions,
    atkFrac: simLoss,
    defFrac: f.defFrac,
    attacker: unitList(atkTroops, atkTribe, atkLost),
    defender: defList,
    atkSaved: countUnits(saved(atkLost, num(A.hospital, MAX_LEVEL), A.tribe)),
    defSaved: defTribe ? countUnits(saved(defLost, num(D.hospital, MAX_LEVEL), D.tribe)) : 0,
    carry: f.attackerWins ? carryOf(Object.assign({}, atkTroops, Object.fromEntries(Object.keys(atkLost).map((k) => [k, atkTroops[k] - atkLost[k]]))), atkTribe) : 0,
    worstWins: worst.attackerWins,
    bestWins: best.attackerWins,
    multiplier: Math.round((multiplier - 1) * 100),
    heroAtk: heroAtkPts,
    heroDef: heroDefPts,
  });
});

// 🧮 the simulator's verdict for the send window: the real army against what
// is known about the target (a camp is public; a colony needs a spy report)
app.post("/api/verdict", requireLogin, (req, res) => {
  const b = req.body || {};
  const now = Date.now();
  const me = loadColony(req.colonyId);
  if (!me) return res.json({ none: true });
  const tribe = tribeOf(me.tribe);
  const mission = b.mission === "raid" ? "raid" : "attack";
  const x = parseInt(b.x, 10), y = parseInt(b.y, 10);
  const troops = {};
  for (const k in b.troops || {}) {
    const u = tribe.units[k], n = Math.floor(Number(b.troops[k]) || 0);
    if (u && n > 0 && !isScout(u) && !isSettler(u)) troops[k] = Math.min(n, me.state.troops[k] || 0);
  }
  let power = allyAttack(attackOf(troops, tribe, me.state.upgrades), req.user.id, now);
  const h = b.hero ? heroOf(req.user.id, now) : null;
  const hero = h && heroHome(h, me.id, now) ? h : null;
  if (hero) power = heroLead(power, hero);
  if (!countUnits(troops) && !hero) return res.json({ none: true });
  const bm = battleMods(hero ? String(b.orders || "") : "", hero, null);
  power = { g: power.g * bm.atk, a: power.a * bm.atk };
  let defense, mult = 1, out = { mission };
  let avail = null, moraleV = 1;
  if (terrainAt(x, y) === "n" && !db.prepare("SELECT 1 FROM colonies WHERE x = ? AND y = ?").get(x, y)) {
    const camp = campAt(x, y, now);
    defense = campDefense(camp.troops);
    avail = lootTotal(camp.treasure || {});
    out.kind = "camp";
  } else {
    const col = db.prepare("SELECT id, user_id, tribe FROM colonies WHERE x = ? AND y = ?").get(x, y);
    if (!col || col.user_id === req.user.id) return res.json({ none: true });
    const reps = db.prepare("SELECT created_at, data FROM reports WHERE user_id = ? AND data LIKE '%\"mission\":\"scout\"%' ORDER BY id DESC LIMIT 40").all(req.user.id);
    let intel = null, at = 0;
    for (const r of reps) {
      const d = JSON.parse(r.data);
      if (!d.intel || !d.intel.troops || !d.defender || d.defender.x !== x || d.defender.y !== y) continue;
      intel = d.intel; at = r.created_at; break;
    }
    if (!intel) return res.json({ unknown: true });
    const defTribe = tribeOf(col.tribe), defTroops = {};
    for (const u of intel.troops) if (u.key) defTroops[u.key] = (defTroops[u.key] || 0) + u.count;
    for (const sp of intel.support || []) for (const u of sp.units || []) if (u.key && defTribe.units[u.key]) defTroops[u.key] = (defTroops[u.key] || 0) + u.count;
    defense = defenseOf(defTroops, defTribe, {});
    const hqLv = ((intel.buildings || []).find((x2) => x2.type === "hq") || {}).level || 1;
    addDefense(defense, { g: MILITIA_BASE + MILITIA_PER_HQ * softLevel(hqLv), a: (MILITIA_BASE + MILITIA_PER_HQ * softLevel(hqLv)) * 0.5 });
    mult = 1 + (perkOf(col.tribe, "wall") * (intel.wall || 0)) / 100;
    const morale = moraleOf(req.user.id, col.user_id);
    moraleV = morale;
    if (intel.res) avail = RESOURCES.reduce((n, r) => n + Math.max(0, (intel.res[r] || 0) - (intel.bunker || 0)), 0);
    power = { g: power.g * morale, a: power.a * morale };
    const ph = combatPhases(troops, tribe, me.state.upgrades, power, defTroops, defTribe, {}, defense, intel.wall || 0);
    Object.assign(out, { kind: "colony", spiedAt: at, air: ph.air, morale: morale < 1 ? Math.round((1 - morale) * 100) : 0 });
  }
  const f = fight(mission, power, defense, mult, 0);
  const worst = fight(mission, power, defense, mult, -LUCK), best = fight(mission, power, defense, mult, LUCK);
  out.verdict = f.attackerWins ? (worst.attackerWins ? "sure" : "likely") : best.attackerWins ? "risky" : "lose";
  out.loss = Math.round(Math.min(1, lossWith(heroLossFraction(f.atkFrac, hero), bm.loss)) * 100);
  // 🎲 the real win chance: luck is even between −10% and +10%
  let w = 0;
  for (let i = 0; i <= 40; i++) if (fight(mission, power, defense, mult, -LUCK + (2 * LUCK * i) / 40).attackerWins) w++;
  out.win = Math.round((w / 41) * 100);
  out.A = f.A; out.D = f.D;
  // 💰 what comes home if it goes as expected
  if (avail !== null) {
    const carry = (carryOf(troops, tribe) + (mission === "raid" ? raiderCarryBonus(troops, tribe) : 0)) * (1 - out.loss / 100) * (hero ? 1 + heroBonus(hero).carry / 100 : 1) * bm.carry * moraleV;
    out.loot = f.attackerWins ? Math.round(Math.min(carry, avail)) : 0;
    out.avail = avail;
  }
  res.json(out);
});

// =====================================================================
//  The newest reports about one map tile (a colony, a camp, the zone)
// =====================================================================
function reportSummary(d) {
  const parts = [];
  if (d.loot) {
    const n = RESOURCES.reduce((sum, r) => sum + (d.loot[r] || 0), 0);
    if (n) parts.push("💰 " + n);
  }
  let mine = d.side === "attacker" ? d.attacker && d.attacker.units : d.side === "defender" ? d.defender && d.defender.units : null;
  if (!mine && d.mission === "scout" && d.attacker && d.attacker.units) mine = d.attacker.units;
  if (d.mission === "trade" && d.goods) parts.push("📦 " + RESOURCES.reduce((n, r) => n + (d.goods[r] || 0), 0) + " delivered");
  if (mine) {
    const lost = mine.reduce((n, u) => n + (u.lost || 0), 0);
    parts.push(lost ? "💀 " + lost + " lost" : "😎 no losses");
  }
  if (d.mission === "scout" && d.intel) {
    if (d.intel.troops) parts.push("👀 " + d.intel.troops.reduce((n, u) => n + u.count, 0) + " troops seen");
    else if (d.intel.monsters) parts.push("👀 " + d.intel.monsters.reduce((n, u) => n + u.count, 0) + " monsters seen");
  }
  if (d.wounded) parts.push("🏥 " + d.wounded + " saved");
  return parts.join(" · ");
}

app.get("/api/tile-reports", requireLogin, (req, res) => {
  const x = parseInt(req.query.x, 10);
  const y = parseInt(req.query.y, 10);
  if (Number.isNaN(x) || Number.isNaN(y)) return res.json({ reports: [] });
  // on my own colonies only reports where somebody came TO it are interesting
  const mineHere = !!db.prepare("SELECT 1 FROM colonies WHERE x = ? AND y = ? AND user_id = ?").get(x, y, req.user.id);
  const rows = db.prepare("SELECT id, created_at, title, icon, data FROM reports WHERE user_id = ? ORDER BY id DESC").all(req.user.id);
  const list = [];
  for (const r of rows) {
    const d = JSON.parse(r.data);
    const at = (p) => p && p.x === x && p.y === y;
    if (!(at(d.defender) || (!mineHere && at(d.attacker)))) continue;
    list.push({ id: r.id, at: r.created_at, icon: r.icon, title: r.title, summary: reportSummary(d) });
    if (list.length >= 5) break;
  }
  res.json({ reports: list, now: Date.now() });
});

