// =====================================================================
//  SEASONS - the owner starts a season goal on the admin page.
//  Relic Hunt: the first team (an alliance, or a player without one)
//  that holds RELIC_HUNT_COUNT landmarks at the same time, without a
//  break, for RELIC_HUNT_HOURS real hours wins the season.
// =====================================================================
function readSeason() {
  const row = db.prepare("SELECT value FROM settings WHERE key = 'season'").get();
  try {
    return row ? JSON.parse(row.value) : null;
  } catch (e) {
    return null;
  }
}
function writeSeason(se) {
  db.prepare("INSERT INTO settings (key, value) VALUES ('season', ?) ON CONFLICT (key) DO UPDATE SET value = excluded.value").run(JSON.stringify(se));
  seasonCache = null;
}

// Who holds how many landmarks, per team
function relicStandings() {
  const teams = {};
  for (const l of LANDMARKS) {
    const r = landmarkRow(l);
    const uid = landmarkHolderUser(r);
    if (!uid || BOT_IDS.has(uid)) continue;
    if (r.ready_at && r.ready_at > Date.now()) continue; // still claiming: does not count yet
    const a = allianceOf(uid);
    const key = a ? "a" + a.id : "u" + uid;
    if (!teams[key]) teams[key] = { key, name: a ? "[" + a.tag + "] " + a.name : usernameOf(uid), held: 0, landmarks: [], users: [] };
    teams[key].held += 1;
    teams[key].landmarks.push(l.icon);
  }
  return Object.values(teams).sort((a, b) => b.held - a.held || a.name.localeCompare(b.name));
}

function teamMembers(key) {
  if (key[0] === "a") return allianceMembers(Number(key.slice(1))).map((m) => m.id);
  return [Number(key.slice(1))];
}

function seasonTick() {
  const se = readSeason();
  if (!se || !se.active || se.kind !== "relic") return;
  const now = Date.now();
  const top = relicStandings()[0];
  const enough = top && top.held >= se.count;
  if (enough && se.streak && se.streak.key === top.key) {
    if (now - se.streak.since >= se.hours * 3600000) {
      // we have a winner!
      se.active = false;
      se.endedAt = now;
      se.winner = { key: top.key, name: top.name, at: now };
      rememberRoundWinner("relic", top.key, top.name, now);
      for (const uid of teamMembers(top.key)) giveBadge(uid, "season" + se.number, "🏆", "Relic Hunt winner · Server " + se.number, now);
      addNews("🏆 " + top.name + " won the Relic Hunt!", now, "season", 72);
      writeSeason(se);
    }
    return;
  }
  if (enough) {
    se.streak = { key: top.key, name: top.name, since: now };
    addNews("🗿 " + top.name + " holds " + top.held + " landmarks! " + se.hours + "h until they win the Relic Hunt.", now, "season", 12);
    writeSeason(se);
  } else if (se.streak) {
    addNews("💥 " + se.streak.name + " lost its grip on the landmarks. The Relic Hunt is open again!", now, "season", 12);
    se.streak = null;
    writeSeason(se);
  }
}
setInterval(() => {
  try {
    seasonTick();
  } catch (e) {
    console.error("season:", e.message);
  }
}, 30000);

// What the game shows about the season (the same for everybody, cached a bit)
let seasonCache = null;
function seasonInfo(userId) {
  const now = Date.now();
  const au = typeof auroraSeason === "function" ? auroraSeason() : null;
  if (au) return { open: landmarksOpen(), season: auroraInfo(au, userId, now) };
  if (!seasonCache || now - seasonCache.at > 5000) {
    const se = readSeason();
    seasonCache = {
      at: now,
      data: se
        ? {
            kind: se.kind,
            number: se.number,
            active: !!se.active,
            count: se.count,
            hours: se.hours,
            startedAt: se.startedAt,
            streak: se.streak ? { key: se.streak.key, name: se.streak.name, since: se.streak.since, winsAt: se.streak.since + se.hours * 3600000 } : null,
            winner: se.winner || null,
            standings: se.active ? relicStandings().slice(0, 5).map((t) => ({ key: t.key, name: t.name, held: t.held, landmarks: t.landmarks })) : [],
          }
        : null,
      open: landmarksOpen(),
    };
  }
  const d = seasonCache.data;
  if (!d) return { open: seasonCache.open, season: null };
  // which team am I?
  const a = allianceOf(userId);
  const myKey = a ? "a" + a.id : "u" + userId;
  return { open: seasonCache.open, season: Object.assign({}, d, { myKey }) };
}

// ---------- the owner's controls ----------
app.get("/api/admin/landmarks", requireOwner, (req, res) => {
  res.json({
    open: landmarksOpen(),
    season: readSeason(),
    clock: serverClock(),
    clockDays: clockDays(),
    defaults: { count: RELIC_HUNT_COUNT, hours: RELIC_HUNT_HOURS, auroraCharge: AURORA_CHARGE_HOURS, auroraHours: auroraDefaultHours() },
    landmarks: LANDMARKS.map((l) => {
      const r = landmarkRow(l);
      const uid = landmarkHolderUser(r);
      return { icon: l.icon, name: l.name, bonus: l.bonus.text, holder: uid ? usernameOf(uid) : null, guards: r.holder_id ? null : r.guards };
    }),
    standings: relicStandings().map((t) => ({ name: t.name, held: t.held })),
  });
});

app.post("/api/admin/landmarks/open", requireOwner, (req, res) => {
  const open = !!(req.body || {}).open;
  setLandmarksOpen(open);
  seasonCache = null;
  addNews(open ? "🗿 The landmarks of Mars are open! Claim them for big bonuses." : "🔒 The landmarks were sealed by the server owner.", Date.now(), "server", 24);
  res.json({ ok: true });
});

// Free every landmark again (the guards walk home, the guardians return)
app.post("/api/admin/landmarks/reset", requireOwner, (req, res) => {
  const now = Date.now();
  for (const l of LANDMARKS) {
    const r = landmarkRow(l);
    for (const g of landmarkGarrison(l)) {
      db.prepare("UPDATE movements SET phase = 'back', arrive_at = ?, return_at = ?, next_at = ? WHERE id = ?").run(now, now + 60000, now + 60000, g.id);
    }
    const holder = r.holder_id ? loadColony(r.holder_id) : null;
    if (holder) {
      update(holder.state, tribeOf(holder.tribe), now);
      loseLandmark(l, holder);
      saveColony(holder.id, holder.state);
    } else loseLandmark(l, null);
  }
  seasonCache = null;
  res.json({ ok: true });
});

function startRelicHunt(b) {
  const old = readSeason();
  if (old && old.active) return "A server goal is already running";
  const count = Math.max(2, Math.min(LANDMARKS.length, parseInt(b.count, 10) || RELIC_HUNT_COUNT));
  const hours = Math.max(1, Math.min(240, parseInt(b.hours, 10) || RELIC_HUNT_HOURS));
  const now = Date.now();
  const se = { kind: "relic", number: (old ? old.number || 0 : 0) + 1, active: true, count, hours, startedAt: now, streak: null, winner: null };
  writeSeason(se);
  setLandmarksOpen(true);
  addNews("🏆 The Relic Hunt begins! Hold " + count + " landmarks for " + hours + "h in a row to win the server.", now, "season", 48);
  return null;
}
app.post("/api/admin/season/start", requireOwner, (req, res) => {
  const err = startRelicHunt(req.body || {});
  if (err) return res.status(400).json({ error: err });
  res.json({ ok: true });
});

app.post("/api/admin/season/stop", requireOwner, (req, res) => {
  const se = readSeason();
  if (!se || !se.active) return res.status(400).json({ error: "No server goal is running" });
  se.active = false;
  se.endedAt = Date.now();
  se.streak = null;
  writeSeason(se);
  addNews("⏹️ " + (se.kind === "aurora" ? "Project Aurora" : "The Relic Hunt") + " was stopped early.", Date.now(), "server", 24);
  res.json({ ok: true });
});

// =====================================================================
//  PLAYER ACTIVITY (for the owner): who plays, how long, where they stop
// =====================================================================
// One row per player and day. A new session starts after 15 minutes
// without any request. Requests only come while the game is on screen.
db.exec(`
  CREATE TABLE IF NOT EXISTS activity (
    user_id   INTEGER NOT NULL,
    day       TEXT NOT NULL,
    first_at  INTEGER NOT NULL,
    last_at   INTEGER NOT NULL,
    sessions  INTEGER NOT NULL DEFAULT 1,
    active_ms INTEGER NOT NULL DEFAULT 0,
    PRIMARY KEY (user_id, day)
  )
`);
const SESSION_GAP_MS = 15 * 60000;
// players who signed up before tracking existed have no history: they don't count for "came back"
db.prepare("INSERT OR IGNORE INTO settings (key, value) VALUES ('activity_since', ?)").run(String(Date.now()));
const ACTIVITY_SINCE = Number(db.prepare("SELECT value FROM settings WHERE key = 'activity_since'").get().value);
const activityTouched = new Map(); // user id -> time of the last saved request
function activityDay(ms) {
  const d = new Date(ms);
  return d.getFullYear() + "-" + String(d.getMonth() + 1).padStart(2, "0") + "-" + String(d.getDate()).padStart(2, "0");
}
function trackActivity(userId) {
  const now = Date.now();
  const prev = activityTouched.get(userId) || 0;
  if (now - prev < 30000) return; // at most one write every 30 seconds per player
  activityTouched.set(userId, now);
  const day = activityDay(now);
  const row = db.prepare("SELECT last_at FROM activity WHERE user_id = ? AND day = ?").get(userId, day);
  if (!row) {
    db.prepare("INSERT INTO activity (user_id, day, first_at, last_at) VALUES (?, ?, ?, ?)").run(userId, day, now, now);
  } else if (now - row.last_at > SESSION_GAP_MS) {
    db.prepare("UPDATE activity SET last_at = ?, sessions = sessions + 1 WHERE user_id = ? AND day = ?").run(now, userId, day);
  } else {
    db.prepare("UPDATE activity SET last_at = ?, active_ms = active_ms + ? WHERE user_id = ? AND day = ?").run(now, now - row.last_at, userId, day);
  }
}

// The first steps of a new player, in the order the game leads them
const FUNNEL_QUESTS = ["field1", "allfields1", "warehouse", "hq3", "barracks", "army10", "hq5", "lab", "hunt", "allfields3", "hub", "hub5"];

app.get("/api/admin/activity", requireOwner, (req, res) => {
  const now = Date.now();
  const today = activityDay(now);
  const users = db.prepare("SELECT id, username, created_at, last_seen, tutorial FROM users WHERE bot = 0").all();
  const rows = db.prepare("SELECT user_id, day, sessions, active_ms FROM activity").all();
  const daysOf = new Map();
  for (const r of rows) {
    if (!daysOf.has(r.user_id)) daysOf.set(r.user_id, new Set());
    daysOf.get(r.user_id).add(r.day);
  }
  // main colony (the first one) of every player, and how many colonies
  const main = new Map();
  const colonyCount = new Map();
  for (const c of db.prepare("SELECT id, user_id, state FROM colonies ORDER BY id").all()) {
    colonyCount.set(c.user_id, (colonyCount.get(c.user_id) || 0) + 1);
    if (!main.has(c.user_id)) {
      let st = {};
      try { st = JSON.parse(c.state); } catch (e) {}
      main.set(c.user_id, st.quests || {});
    }
  }
  const real = users.filter((u) => main.has(u.id)); // robots have no account row, but be safe
  const dayPlus = (ms, n) => activityDay(ms + n * 86400000);

  // funnel
  const funnel = [["Signed up", real.length], ["Finished the tour", real.filter((u) => u.tutorial).length]];
  for (const id of FUNNEL_QUESTS) {
    const q = QUESTS.find((x) => x.id === id);
    if (!q) continue;
    funnel.push([q.icon + " " + q.title, real.filter((u) => (main.get(u.id) || {})[id]).length]);
  }
  funnel.push(["🏳️ Second colony", real.filter((u) => (colonyCount.get(u.id) || 0) >= 2).length]);

  // came back? (only players old enough to have had the chance)
  const back = (n) => {
    const eligible = real.filter((u) => u.created_at >= ACTIVITY_SINCE && dayPlus(u.created_at, n) <= today);
    const came = eligible.filter((u) => { const s = daysOf.get(u.id); if (!s) return false; for (const d of s) if (d >= dayPlus(u.created_at, n)) return true; return false; });
    return { eligible: eligible.length, came: came.length };
  };

  // the last 14 days
  const days = [];
  for (let i = 13; i >= 0; i--) {
    const day = activityDay(now - i * 86400000);
    const list = rows.filter((r) => r.day === day);
    const ms = list.reduce((s, r) => s + r.active_ms, 0);
    const sessions = list.reduce((s, r) => s + r.sessions, 0);
    days.push({ day, players: list.length, newPlayers: real.filter((u) => activityDay(u.created_at) === day).length, minutes: Math.round(ms / 60000), sessions });
  }
  const week = rows.filter((r) => r.day >= activityDay(now - 6 * 86400000));
  const weekSessions = week.reduce((s, r) => s + r.sessions, 0);

  // players who stopped: not seen for 2+ days, with the quest they were on
  const gone = real
    .filter((u) => now - (u.last_seen || u.created_at) > 2 * 86400000)
    .map((u) => {
      const claimed = main.get(u.id) || {};
      const next = QUESTS.find((x) => !claimed[x.id]);
      return { name: u.username, lastSeen: u.last_seen || u.created_at, daysPlayed: (daysOf.get(u.id) || new Set()).size, questsDone: Object.keys(claimed).length, stuckAt: next ? next.icon + " " + next.title : "🌟 all done", tour: !!u.tutorial };
    })
    .sort((a, b) => b.lastSeen - a.lastSeen)
    .slice(0, 40);

  res.json({
    now,
    since: ACTIVITY_SINCE,
    today: rows.filter((r) => r.day === today).length,
    week: new Set(week.map((r) => r.user_id)).size,
    avgSessionMin: weekSessions ? Math.round(week.reduce((s, r) => s + r.active_ms, 0) / weekSessions / 60000) : 0,
    back1: back(1),
    back7: back(7),
    funnel,
    days,
    gone,
  });
});


// =====================================================================
//  FARM LISTS: saved on the server, so they survive a closed browser,
//  cleared website data and a new phone.
// =====================================================================
addColumn("users", "farm", "TEXT NOT NULL DEFAULT ''");
const FARM_MAX_LISTS = 30;
const FARM_MAX_ENTRIES = 200;

function cleanFarmLists(lists) {
  if (!Array.isArray(lists)) return null;
  const str = (v, n) => String(v == null ? "" : v).slice(0, n);
  const int = (v) => (Number.isFinite(Number(v)) ? Math.round(Number(v)) : 0);
  return lists.slice(0, FARM_MAX_LISTS).map((l) => ({
    id: str(l && l.id, 16),
    name: str(l && l.name, 30) || "Farm list",
    colonyId: int(l && l.colonyId),
    lastStarted: Math.max(0, Math.min(Date.now(), int(l && l.lastStarted))),
    sort: str(l && l.sort, 12) || "manual",
    defaults:Object.fromEntries(Object.entries(l&&l.defaults&&typeof l.defaults==='object'?l.defaults:{}).slice(0,20).map(([k,v])=>[str(k,20),Math.min(10000000,Math.max(0,int(v)))])),
    entries: (Array.isArray(l && l.entries) ? l.entries : []).slice(0, FARM_MAX_ENTRIES).map((e) => {
      const troops = {};
      if (e && e.troops && typeof e.troops === "object") {
        for (const k of Object.keys(e.troops).slice(0, 20)) troops[str(k, 20)] = Math.max(0, int(e.troops[k]));
      }
      return { id: str(e && e.id, 16), x: int(e && e.x), y: int(e && e.y), name: str(e && e.name, 60), troops, on: !(e && e.on === false), last: str(e && e.last, 120) };
    }),
  }));
}

app.get("/api/farm", requireLogin, (req, res) => {
  const row = db.prepare("SELECT farm FROM users WHERE id = ?").get(req.user.id);
  let lists = null;
  try { lists = row && row.farm ? JSON.parse(row.farm).lists : null; } catch (e) {}
  res.json({ lists }); // null = never saved on the server yet
});

// When is a farm target worth raiding again (full bags)? An estimate:
//  - monster camps: their treasure grows at a known speed
//  - colonies: how fast they refilled between the last two raids
// null = no idea yet (counts as ready)
function farmReadyAt(x, y, last, now) {
  if (!last || !last.at) return null;
  const want = last.carry || 0;
  if (!want) return null;
  const isCamp = terrainAt(x, y) === "n" && !db.prepare("SELECT 1 FROM colonies WHERE x = ? AND y = ?").get(x, y);
  if (isCamp) {
    // Only what the raider knows: their own last raid + the camp's public regrowth.
    // The camp's current stash stays hidden (scout it with spies to know for sure).
    const info = campInfo(x, y, now);
    const perHour = RESOURCES.reduce((n, r) => n + info.income[r], 0);
    const cap = RESOURCES.reduce((n, r) => n + freshCamp(x, y).treasure[r], 0);
    const need = Math.min(want, cap);
    if (last.loot >= want * 0.98) return last.at; // bags were full: there was more
    if (perHour <= 0) return null;
    return Math.round(last.at + (need / perHour) * 3600000); // we emptied it: wait for regrowth
  }
  if (last.loot >= want * 0.98) return last.at; // they had even more: go again
  if (!last.prevAt || last.at <= last.prevAt || !last.loot) return null;
  const perMs = last.loot / (last.at - last.prevAt);
  return Math.round(last.at + want / perMs);
}

// What the farm lists achieved: { "x|y": { raids, total, last, readyAt } }
app.get("/api/farm/stats", requireLogin, (req, res) => {
  const out = {};
  for (const r of db.prepare("SELECT x, y, raids, total, last FROM farm_stats WHERE user_id = ?").all(req.user.id)) {
    let last = {};
    try { last = JSON.parse(r.last); } catch (e) {}
    out[r.x + "|" + r.y] = { raids: r.raids, total: r.total, last, readyAt: farmReadyAt(r.x, r.y, last, Date.now()) };
  }
  const q = db.prepare("SELECT farm_quiet FROM users WHERE id = ?").get(req.user.id) || {};
  const outgoing = {};
  for (const m of db.prepare("SELECT m.attacker_id, m.target_x, m.target_y, COUNT(*) AS n FROM movements m JOIN colonies c ON c.id = m.attacker_id WHERE c.user_id = ? AND m.phase = 'out' AND m.mission IN ('raid', 'attack') AND m.arrive_at > ? GROUP BY m.attacker_id, m.target_x, m.target_y").all(req.user.id, Date.now())) {
    outgoing[m.attacker_id + ":" + m.target_x + "|" + m.target_y] = m.n;
  }
  res.json({ stats: out, outgoing, quiet: !!q.farm_quiet, now: Date.now() });
});

// "Only report farm raids with losses" on/off
app.post("/api/farm/quiet", requireLogin, (req, res) => {
  const on = !!(req.body || {}).on;
  db.prepare("UPDATE users SET farm_quiet = ?, farm_hidden = 0 WHERE id = ?").run(on ? 1 : 0, req.user.id);
  res.json({ ok: true, on });
});

app.post("/api/farm", requireLogin, (req, res) => {
  const lists = cleanFarmLists(req.body && req.body.lists);
  if (!lists) return res.status(400).json({ error: "Broken farm lists" });
  db.prepare("UPDATE users SET farm = ? WHERE id = ?").run(JSON.stringify({ lists }), req.user.id);
  res.json({ ok: true });
});

// =====================================================================
//  MAIN COLONY: one colony per player is the ⭐ main colony.
//  Only there resource fields go past level 10 (up to MAIN_FIELD_MAX).
// =====================================================================
addColumn("users", "main_moved_at", "INTEGER NOT NULL DEFAULT 0");

// Every player has exactly one main colony (older worlds: the first one)
function ensureMainColonies() {
  const rows = db.prepare("SELECT id, user_id, state FROM colonies WHERE user_id > 0 ORDER BY id").all();
  const byUser = new Map();
  for (const r of rows) {
    if (!byUser.has(r.user_id)) byUser.set(r.user_id, []);
    byUser.get(r.user_id).push(r);
  }
  for (const list of byUser.values()) {
    const mains = list.filter((r) => { try { return !!JSON.parse(r.state).main; } catch (e) { return false; } });
    if (mains.length === 1) continue;
    const keep = mains[0] || list[0];
    for (const r of list) {
      const st = JSON.parse(r.state);
      const want = r.id === keep.id;
      if (!!st.main === want) continue;
      if (want) st.main = true; else delete st.main;
      db.prepare("UPDATE colonies SET state = ? WHERE id = ?").run(JSON.stringify(st), r.id);
    }
  }
}
ensureMainColonies();

function mainMoveInfo(userId) {
  const row = db.prepare("SELECT main_moved_at FROM users WHERE id = ?").get(userId);
  const nextAt = (row ? row.main_moved_at : 0) + MAIN_MOVE_HOURS * 3600000;
  return { nextAt: nextAt > Date.now() ? nextAt : 0, hours: MAIN_MOVE_HOURS, max: MAIN_FIELD_MAX, normalMax: MAX_LEVEL };
}

// The old main colony loses everything above level 10: fields drop to 10,
// and upgrades above 10 that are still waiting are cancelled and refunded.
function stripMainColony(s, now) {
  let lowered = 0;
  for (const f of s.fields) if (f.level > MAX_LEVEL) { f.level = MAX_LEVEL; lowered++; }
  const keep = [];
  for (const q of s.queue) {
    if (q.kind === "field" && q.targetLevel > MAX_LEVEL) {
      for (const r of RESOURCES) s.res[r] += (q.cost && q.cost[r]) || 0; // refund (storage limit applies later)
    } else if (q.kind === "building" && BUILDING_TYPES[q.type] && BUILDING_TYPES[q.type].mainOnly) {
      // a main-colony-only building in the works: dropped, no refund
    } else keep.push(q);
  }
  const removedRunning = s.queue.length && s.queue[0] !== keep[0];
  s.queue = keep;
  if (removedRunning && s.queue[0]) { s.queue[0].finishAt = null; startNextConstruction(s, now); }
  // 🏰 main-colony-only buildings are torn down at once (no refund)
  s.buildings.forEach((b, i) => { if (b.type && BUILDING_TYPES[b.type].mainOnly) s.buildings[i] = { type: null, level: 0 }; });
  if (s.crewJob && s.crewJob.kind === "building" && BUILDING_TYPES[s.crewJob.type] && BUILDING_TYPES[s.crewJob.type].mainOnly) s.crewJob = null;
  delete s.main;
  return lowered;
}

app.post("/api/main-colony", requireLogin, (req, res) => {
  const id = parseInt((req.body || {}).colonyId, 10);
  const now = Date.now();
  const cols = coloniesOf(req.user.id);
  const target = cols.find((c) => c.id === id);
  if (!target) return res.status(400).json({ error: "That is not your colony" });
  if (target.state.main) return res.status(400).json({ error: "This already is your main colony" });
  const info = mainMoveInfo(req.user.id);
  if (info.nextAt) return res.status(400).json({ error: "You can move your main colony again in " + Math.ceil((info.nextAt - now) / 3600000) + " h" });
  processMovements(now);
  let lowered = 0;
  for (const c of cols) {
    if (!c.state.main) continue;
    update(c.state, tribeOf(c.tribe), now);
    lowered += stripMainColony(c.state, now);
    saveColony(c.id, c.state);
  }
  const fresh = loadColony(target.id);
  update(fresh.state, tribeOf(fresh.tribe), now);
  fresh.state.main = true;
  saveColony(fresh.id, fresh.state);
  db.prepare("UPDATE users SET main_moved_at = ? WHERE id = ?").run(now, req.user.id);
  res.json({ ok: true, lowered });
});

// =====================================================================
//  FAKE PLAYERS ("sleepy colonists"): small, quiet colonies for raiding.
//  They never attack players. Explorers make occasional safe camp raids.
//  They have few points, a handful of troops and
//  small storage, so they are good practice targets for new players.
//  How many there are adjusts by itself to the number of active
//  players and to the age of the world; the owner can scale it.
// =====================================================================
const BOT_TICK_MS = 60000;
const BOT_SCALES = { off: 0, few: 0.5, normal: 1, many: 1.6 };
const BOT_FIRST = ["Rusty", "Dusty", "Sleepy", "Lazy", "Crater", "Moon", "Old", "Tiny", "Red", "Quiet", "Lucky", "Grumpy", "Sandy", "Space", "Comet", "Rocky", "Foggy", "Clumsy", "Dozy", "Nova"];
const BOT_LAST = ["Pete", "Dan", "Molly", "Carl", "Sam", "Lou", "Greta", "Bob", "Ida", "Max", "Rita", "Otto", "Fred", "Lena", "Hank", "Zoe", "Gus", "Nell", "Ray", "Tilda"];

function botScale() {
  const row = db.prepare("SELECT value FROM settings WHERE key = 'bots_scale'").get();
  return row && BOT_SCALES[row.value] !== undefined ? row.value : "normal";
}

// The world's age in days: since the first real player joined
function worldAgeDays(now) {
  const row = db.prepare("SELECT MIN(created_at) AS t FROM users WHERE bot = 0").get();
  return row && row.t ? Math.max(0, (now - row.t) / 86400000) : 0;
}

// How many fake players the world should have right now
// The owner can also type an exact number (empty = automatic)
function botFixed() {
  const row = db.prepare("SELECT value FROM settings WHERE key = 'bots_fixed'").get();
  const n = row ? parseInt(row.value, 10) : NaN;
  return Number.isInteger(n) && n >= 0 ? Math.min(100, n) : null;
}
// One account counts once, in the quadrant of its oldest surviving colony.
function botPopulationGoal(now){
  const scale=botScale();if(!BOT_SCALES[scale])return 0;
  const humans=db.prepare("SELECT COUNT(*) n FROM users WHERE bot=0 AND banned=0 AND MAX(last_seen,created_at)>?").get(now-7*86400000).n;
  const base=scale==='few'?18:scale==='many'?25:22;
  return Math.max(8,base-Math.floor(Math.max(0,humans-30)/5));
}
function botAggressionDelay(){
  const humans=db.prepare("SELECT COUNT(*) n FROM users WHERE bot=0 AND banned=0 AND MAX(last_seen,created_at)>?").get(Date.now()-7*86400000).n;
  return Math.min(4,1+Math.max(0,humans-30)/15);
}
function quadrantPopulation(now) {
  const groups=Array.from({length:4},(_,quadrant)=>({quadrant,inactive:0,bots:0,target:0}));
  for(const r of db.prepare(`SELECT u.bot,u.last_seen,u.created_at,c.x,c.y FROM users u JOIN colonies c ON c.id=(SELECT MIN(id) FROM colonies WHERE user_id=u.id) WHERE u.banned=0`).all()){
    const g=groups[quarterOf(r.x,r.y)];if(r.bot)g.bots++;else if(Math.max(r.last_seen||0,r.created_at||0)<=now-7*86400000)g.inactive++;
  }
  const goal=botFixed()===null?botPopulationGoal(now):botFixed();
  groups.forEach(g=>g.target=Math.floor(goal/4));
  groups.slice().sort((a,b)=>a.inactive-b.inactive||a.quadrant-b.quadrant).slice(0,goal%4).forEach(g=>g.target++);
  return groups;
}
function botTarget(now){return botFixed()===null?botPopulationGoal(now):botFixed();}

// How strong a fake player is. It follows the REAL players: about a fifth of
// the points of a typical active player (median of their main colonies).
// So it adjusts by itself to the game speed and to the age of the world,
// and fake players stay easy targets without being worthless.
function typicalPlayerPoints(now) {
  const pts = db
    .prepare(
      `SELECT colonies.state FROM colonies JOIN users ON users.id = colonies.user_id
       WHERE users.bot = 0 AND users.banned = 0 AND MAX(users.last_seen, users.created_at) > ?`
    )
    .all(now - 3 * 86400000)
    .map((r) => { try { const s = JSON.parse(r.state); return s.main ? colonyPoints(s) : null; } catch (e) { return null; } })
    .filter((v) => v !== null)
    .sort((x, y) => x - y);
  return pts.length ? pts[Math.floor(pts.length / 2)] : 20;
}
function botProfile(now) {
  return botProfileFor(Math.max(14, typicalPlayerPoints(now) * 0.2));
}
// the same profile for any size (each fake player has its own size, see botGrow)
function botProfileFor(goal) {
  const clamp = (v, lo, hi) => Math.max(lo, Math.min(hi, v));
  return {
    goal: Math.round(goal),
    fields: clamp(Math.round(goal / 16), 1, 5), // resource fields
    hq: clamp(Math.round(goal / 18) + 1, 3, 8),
    storage: clamp(Math.round(goal / 28), 0, 6), // warehouse & granary: limits the loot
    wall: clamp(Math.floor(goal / 45), 0, 5),
    troops: clamp(Math.round(2 + goal * 0.06), 2, 12), // a very small home guard
  };
}

