// ---------- player tools ----------
function ownedColonies(userId) {
  return coloniesOf(userId);
}
// give resources to one player (their first colony) or to everybody
app.post("/api/admin/give", requireOwner, (req, res) => {
  const b = req.body || {};
  const gift = {};
  let any = false;
  for (const r of RESOURCES) {
    const v = Math.max(0, Math.min(1000000, Math.round(Number(b[r]) || 0)));
    gift[r] = v;
    if (v) any = true;
  }
  if (!any) return res.status(400).json({ error: "Enter an amount" });
  const now = Date.now();
  let ids;
  let who;
  if (b.all) {
    ids = db.prepare("SELECT colonies.id FROM colonies JOIN users ON users.id = colonies.user_id WHERE users.bot = 0 AND colonies.user_id > 0").all().map((r) => r.id);
    who = "every colony";
  } else {
    const user = db.prepare("SELECT id, username FROM users WHERE id = ?").get(Number(b.id));
    if (!user) return res.status(400).json({ error: "No such player" });
    ids = colonyIdsOf(user.id);
    who = user.username;
  }
  for (const id of ids) {
    const c = loadColony(id);
    update(c.state, tribeOf(c.tribe), now);
    refund(c.state, gift);
    saveColony(c.id, c.state);
  }
  const text = "Gift to " + who + ": " + RESOURCES.map((r) => (gift[r] ? gift[r] + " " + r : "")).filter(Boolean).join(", ");
  adminLog(req, text);
  if (b.all && b.news) addNews("🎁 A gift from the server owner: " + RESOURCES.map((r) => (gift[r] ? gift[r] + " " + r : "")).filter(Boolean).join(", ") + " for every colony!", now, "admin", 24);
  res.json({ ok: true, message: text + " (storage limits apply)" });
});
// log a player out everywhere
app.post("/api/admin/logout", requireOwner, (req, res) => {
  const user = db.prepare("SELECT id, username FROM users WHERE id = ?").get(Number((req.body || {}).id));
  if (!user) return res.status(400).json({ error: "No such player" });
  db.prepare("DELETE FROM sessions WHERE user_id = ?").run(user.id);
  adminLog(req, "Logged out " + user.username);
  res.json({ ok: true, message: user.username + " was logged out" });
});
// a player starts again with one fresh colony (same tribe, same name)
function freshStart(userId, now) {
  const user = db.prepare("SELECT id, username FROM users WHERE id = ?").get(userId);
  if (!user) return false;
  const first = coloniesOf(userId)[0];
  const tribe = first ? first.tribe : "human";
  const ids = colonyIdsOf(userId);
  if (ids.length) {
    const marks = ids.map(() => "?").join(",");
    db.prepare(`DELETE FROM movements WHERE attacker_id IN (${marks})`).run(...ids);
    db.prepare(`UPDATE movements SET phase = 'back', arrive_at = ?, return_at = ?, next_at = ? WHERE target_kind = 'colony' AND target_id IN (${marks})`).run(now, now + 1000, now + 1000, ...ids);
    db.prepare(`DELETE FROM colonies WHERE id IN (${marks})`).run(...ids);
  }
  const spot = findFreeSpot();
  if (!spot) return false;
  createColony(userId, tribe, "New Colony", spot.x, spot.y);
  db.prepare("UPDATE users SET protected_until = ?, quests = '{}', main_moved_at = 0, col_groups = '{}' WHERE id = ?").run(now + protectionHours() * 3600000, userId);
  return true;
}
app.post("/api/admin/restart-player", requireOwner, (req, res) => {
  const user = db.prepare("SELECT id, username FROM users WHERE id = ?").get(Number((req.body || {}).id));
  if (!user) return res.status(400).json({ error: "No such player" });
  if (String((req.body || {}).confirm || "") !== user.username) return res.status(400).json({ error: "Type the exact name to confirm" });
  const now = Date.now();
  if (!freshStart(user.id, now)) return res.status(400).json({ error: "No free land left" });
  adminLog(req, user.username + " starts over with a fresh colony");
  res.json({ ok: true, message: user.username + " starts over" });
});

// ---------- the whole server ----------
// mode "fresh": every player keeps the account and starts over with one new colony
// mode "wipe": only the owners stay (with a new colony), everybody else is deleted
// A new round: everything is swept away and the clock starts at day 1.
// mode "fresh" keeps the accounts, "wipe" deletes all but the owners.
function resetServer(mode, keepBadges) {
  const now = Date.now();
  // 🏛️ the round that ends goes into the Hall of Fame
  try { recordRound(now); } catch (err) { console.error("hall of fame:", err.message); }
  // nobody plays while we sweep
  const wasMaintenance = maintenanceOn();
  setSetting("maintenance", "1");
  try {
    processMovements(now);
    // fake players go first: they are made again by themselves
    for (const u of db.prepare("SELECT id FROM users WHERE bot = 1").all()) deleteUserCompletely(u.id);
    if (mode === "wipe") {
      for (const u of db.prepare("SELECT id, username FROM users").all()) {
        if (!ownerNames().includes(u.username.toLowerCase())) deleteUserCompletely(u.id);
      }
    }
    // world
    db.prepare("DELETE FROM movements").run();
    db.prepare("DELETE FROM farm_stats").run();
    db.prepare("DELETE FROM map_marks").run();
    db.prepare("DELETE FROM meteor_claims").run();
    clearMeteors();
    db.prepare("DELETE FROM events").run();
    db.prepare("DELETE FROM aurora_charge").run();
    db.prepare("DELETE FROM settings WHERE key IN ('season', 'events_next')").run();
    db.prepare("DELETE FROM landmarks").run();
    db.prepare("UPDATE zone SET holder_id = NULL, since = NULL, robots = ? WHERE id = 1").run(zoneRobots());
    setLandmarksOpen(false);
    rerollCamps(null);
    loadEvents();
    seasonCache = null;
    // alliances, mail, reports, news, stats
    for (const t of ["alliance_invites", "alliance_members", "alliance_plan_joins", "alliance_plans", "alliance_posts", "alliance_project_donors", "alliance_project_pots", "alliance_projects", "alliance_levels", "alliance_bank_log", "alliance_bank", "alliance_pacts", "alliance_war_marks", "alliances", "build_asks", "build_help_log", "build_hands", "crew_busy", "market_offers", "shared_reports"]) db.prepare("DELETE FROM " + t).run();
    for (const t of ["reports", "messages", "news", "stats", "stats_log"]) db.prepare("DELETE FROM " + t).run();
    try { legacyBank(now); } catch (err) { console.error("legacy:", err.message); }
    // weekly ranks and achievements only last for one round; champions stay
    for (const b of db.prepare("SELECT id, key FROM badges").all()) if (roundBadge(b.key)) db.prepare("DELETE FROM badges WHERE id = ?").run(b.id);
    if (!keepBadges) db.prepare("DELETE FROM badges").run();
    // colonies: everybody starts over
    for (const u of db.prepare("SELECT id FROM users").all()) freshStart(u.id, now);
    // commanders start over too (a new round is fair for everybody)
    db.prepare("UPDATE users SET hero = ''").run();
    // a new round: the clock starts today
    clockRestartNow(now);
    clockDoneWrite({});
    addNews("🔄 A new round starts on " + thisServerName() + "! Welcome back to Mars.", now, "server", 48);
  } finally {
    setSetting("maintenance", wasMaintenance ? "1" : "0");
  }
  setTimeout(botTick, 3000);
}
app.post("/api/admin/server-reset", requireOwner, (req, res) => {
  if (!confirmed(req, "RESET SERVER")) return res.status(400).json({ error: "Type RESET SERVER to confirm" });
  const b = req.body || {};
  const mode = b.mode === "wipe" ? "wipe" : "fresh";
  resetServer(mode, b.keepBadges !== false); // badges stay with the players
  adminLog(req, "SERVER RESET (" + mode + ")");
  res.json({ ok: true, message: "Server reset (" + mode + "). Everybody starts over." });
});

// ---------- 📅 planned round starts ----------
// The owner plans when new rounds begin. At that moment the server resets
// by itself (accounts stay, everybody gets a new colony). Servers with
// "restartHours" in their preset plan the next round when Aurora ends.
function plannedStarts() {
  try { return JSON.parse(settingOf("planned_starts", "[]")).filter((x) => x > 0).sort((a, b) => a - b); } catch (e) { return []; }
}
function setPlannedStarts(list) {
  setSetting("planned_starts", JSON.stringify([...new Set(list)].sort((a, b) => a - b).slice(0, 20)));
}
function auroraEndedAt() {
  const se = readSeason();
  if (!se || se.kind !== "aurora" || se.active) return 0;
  return (se.winner && se.winner.at) || se.endedAt || 0;
}
function startsTick() {
  const now = Date.now();
  let list = plannedStarts();
  // an automatic next round after Aurora (once per round)
  const ended = auroraEndedAt();
  if (THIS_PRESET.restartHours && ended && !list.length && settingOf("auto_planned", "") !== String(ended)) {
    list.push(ended + THIS_PRESET.restartHours * 3600000);
    setSetting("auto_planned", String(ended));
    setPlannedStarts(list);
    addNews("📅 The next round starts " + new Date(list[0]).toUTCString().replace(":00 GMT", " UTC") + ".", now, "server", THIS_PRESET.restartHours + 1);
  }
  const due = list.filter((x) => x <= now);
  if (!due.length) return;
  setPlannedStarts(list.filter((x) => x > now));
  resetServer("fresh", true);
  adminLog(null, "NEW ROUND (planned start)");
}
setInterval(() => {
  try { startsTick(); } catch (e) { console.error("starts:", e.message); }
}, 30000);
app.get("/api/admin/starts", requireOwner, (req, res) => {
  res.json({ starts: plannedStarts(), restartHours: THIS_PRESET.restartHours || 0 });
});
// body: { add: time } or { remove: time }
app.post("/api/admin/starts", requireOwner, (req, res) => {
  const b = req.body || {};
  let list = plannedStarts();
  if (b.add != null) {
    const t = Math.round(Number(b.add));
    if (!(t > Date.now() + 60000) || t > Date.now() + 366 * 86400000) return res.status(400).json({ error: "Pick a time in the future" });
    list.push(t);
    adminLog(req, "Planned a new round: " + new Date(t).toISOString());
  } else if (b.remove != null) {
    list = list.filter((x) => x !== Number(b.remove));
    adminLog(req, "Removed a planned round");
  }
  setPlannedStarts(list);
  res.json({ ok: true, starts: plannedStarts() });
});
// Public: when this server's rounds start. The login screen of every
