function normEmail(e) {
  const m = String(e || "").trim().toLowerCase().match(/^([^@\s]+)@([^@\s]+)$/);
  if (!m) return "";
  let local = m[1].split("+")[0];
  let domain = m[2];
  if (domain === "googlemail.com") domain = "gmail.com";
  if (domain === "gmail.com") local = local.replace(/\./g, "");
  return local + "@" + domain;
}
function checkEmail(e) {
  const email = String(e || "").trim();
  if (email.length > 120 || !/^[^\s@]{1,64}@[^\s@]+\.[^\s@]{2,}$/.test(email)) return "Enter a valid email address";
  if (DISPOSABLE_MAIL.has(email.split("@")[1].toLowerCase())) return "Throw-away email addresses are not allowed. Please use your real one.";
  return null;
}
function emailTaken(norm, exceptUserId) {
  const u = db.prepare("SELECT id FROM accounts WHERE norm_email = ? AND email_verified = 1").get(norm);
  if (u && u.id !== exceptUserId) return true;
  return !!db.prepare("SELECT 1 FROM pending_signups WHERE norm_email = ? AND created_at > ?").get(norm, Date.now() - SIGNUP_HOURS * 3600000);
}
function sha(t) {
  return crypto.createHash("sha256").update(t).digest("hex");
}
function newToken() {
  return crypto.randomBytes(24).toString("hex");
}
function baseUrl(req) {
  const proto = String(req.headers["x-forwarded-proto"] || (req.secure ? "https" : "http")).split(",")[0];
  return (process.env.PUBLIC_URL || proto + "://" + req.headers.host).replace(/\/+$/, "");
}
setInterval(() => {
  db.prepare("DELETE FROM pending_signups WHERE created_at < ?").run(Date.now() - SIGNUP_HOURS * 3600000);
  db.prepare("DELETE FROM mail_tokens WHERE expires_at < ?").run(Date.now());
}, 600000);

// ---------- devices ----------
function ipHash(req) {
  let salt = settingOf("ip_salt", "");
  if (!salt) { salt = newToken(); setSetting("ip_salt", salt); }
  return sha(salt + "|" + req.ip).slice(0, 24);
}
function deviceOf(req) {
  const d = readCookie(req, "marsl_dev");
  return d && /^[0-9a-f]{32}$/.test(d) ? d : null;
}
function deviceCap() {
  const n = Number(settingOf("device_cap", String(DEFAULT_DEVICE_CAP)));
  return Number.isFinite(n) ? n : DEFAULT_DEVICE_CAP; // 0 = no limit
}
// Called on every login: remembers the device (and gives a new one a cookie)
function rememberDevice(req, userId) {
  let dev = deviceOf(req);
  const cookies = [];
  if (!dev) {
    dev = crypto.randomBytes(16).toString("hex");
    cookies.push("marsl_dev=" + dev + "; HttpOnly; SameSite=Lax; Path=/; Max-Age=" + 2 * 365 * 86400 + (req.secure ? "; Secure" : ""));
  }
  const now = Date.now();
  db.prepare("INSERT INTO device_links (user_id, device, ip_hash, first_seen, last_seen) VALUES (?, ?, ?, ?, ?) ON CONFLICT (user_id, device, ip_hash) DO UPDATE SET last_seen = excluded.last_seen").run(userId, dev, ipHash(req), now, now);
  return cookies;
}
function accountsOnDevice(dev) {
  if (!dev) return 0;
  const a = db.prepare("SELECT COUNT(DISTINCT device_links.user_id) AS n FROM device_links JOIN users ON users.id = device_links.user_id WHERE device_links.device = ? AND users.multi_ok = 0").get(dev).n;
  const p = db.prepare("SELECT COUNT(*) AS n FROM pending_signups WHERE device = ? AND created_at > ?").get(dev, Date.now() - SIGNUP_HOURS * 3600000).n;
  return a + p;
}
// Two different players on the same device cannot send each other anything
function accountsLinked(a, b) {
  if (!a || !b || a === b) return false;
  const ok = db.prepare("SELECT COUNT(*) AS n FROM users WHERE id IN (?, ?) AND multi_ok = 1").get(a, b).n;
  if (ok) return false;
  return !!db.prepare("SELECT 1 FROM device_links x JOIN device_links y ON x.device = y.device WHERE x.user_id = ? AND y.user_id = ? LIMIT 1").get(a, b);
}
