function confirmMail(lang, name) {
  const t = MAIL_LANGS[MAIL_LANGS[lang] ? lang : "en"];
  return { subject: t.subject, lines: [t.hi.replace("NAME", name), t.line.replace("HOURS", String(SIGNUP_HOURS))], button: t.button };
}

async function startSignup(req, res, who) {
  const body = req.body || {};
  const bad = checkEmail(body.email);
  if (bad) return res.status(400).json({ error: bad });
  const email = String(body.email).trim();
  const norm = normEmail(email);
  if (emailTaken(norm)) return res.status(400).json({ error: "There is already an account (or a waiting sign-up) with that email address" });
  if (db.prepare("SELECT 1 FROM pending_signups WHERE LOWER(username) = LOWER(?) AND created_at > ?").get(who.username, Date.now() - SIGNUP_HOURS * 3600000)) {
    return res.status(400).json({ error: "That name is waiting for its confirmation email. Pick another one." });
  }
  const cap = deviceCap();
  if (cap > 0 && accountsOnDevice(deviceOf(req)) >= cap) {
    return res.status(400).json({ error: "This device already has " + cap + " accounts. Please play with those." });
  }
  if (blocked("mail-ip:" + req.ip, 8)) return res.status(429).json({ error: "Too many sign-ups from here. Try again later." });
  const salt = crypto.randomBytes(16).toString("hex");
  const token = newToken();
  const now = Date.now();
  // the mail goes first: a sign-up is only waiting for confirmation once its mail was accepted
  try {
    const mail = confirmMail(who.lang, who.username);
    await sendMail(email, mail.subject, mail.lines, mail.button, baseUrl(req) + "/verify?token=" + token);
  } catch (e) {
    console.error("Confirmation mail to " + email + " failed: " + e.message);
    mailProblem = { at: Date.now(), error: e.message };
    return res.status(502).json({ error: "The confirmation mail could not be sent right now. Please try again in a few minutes." });
  }
  db.prepare("INSERT INTO pending_signups (token_hash, username, email, norm_email, pass_hash, salt, tribe, device, ip_hash, created_at, sent_at, lang) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)").run(sha(token), who.username, email, norm, hashPassword(who.password, salt), salt, who.tribe, deviceOf(req) || "", ipHash(req), now, now, MAIL_LANGS[who.lang] ? who.lang : "en");
  hit("mail-ip:" + req.ip, 3600000);
  hit("reg:" + req.ip, 3600000);
  res.json({ ok: true, verify: true, email });
}

