function accountEmailInfo(accountId) {
  const u = db.prepare("SELECT email, email_verified FROM accounts WHERE id = ?").get(accountId);
  return { email: u && u.email_verified ? u.email : null, mailReady: mailReady() };
}
app.post("/api/email", requireAcct, (req, res) => {
  req.user = req.acct;
  if (!mailReady()) return res.status(400).json({ error: "This server can't send email yet." });
  const bad = checkEmail((req.body || {}).email);
  if (bad) return res.status(400).json({ error: bad });
  const email = String(req.body.email).trim();
  const norm = normEmail(email);
  if (emailTaken(norm, req.user.id)) return res.status(400).json({ error: "That email address is already used by another account" });
  if (blocked("mail-user:" + req.user.id, 5)) return res.status(429).json({ error: "Too many mails. Try again later." });
  hit("mail-user:" + req.user.id, 3600000);
  const token = newToken();
  db.prepare("DELETE FROM mail_tokens WHERE user_id = ? AND kind = 'email'").run(req.user.id);
  db.prepare("INSERT INTO mail_tokens (token_hash, kind, user_id, email, norm_email, expires_at) VALUES (?, 'email', ?, ?, ?, ?)").run(sha(token), req.user.id, email, norm, Date.now() + SIGNUP_HOURS * 3600000);
  const lg = mlang((req.body || {}).lang);
  mailTry(email, mt(lg).cSub, [mt(lg).cHi.replace("NAME", req.user.username)], mt(lg).cBtn, baseUrl(req) + "/verify-email?token=" + token + "&lang=" + lg);
  res.json({ ok: true });
});
app.get("/verify-email", (req, res) => {
  const row = db.prepare("SELECT * FROM mail_tokens WHERE token_hash = ? AND kind = 'email' AND expires_at > ?").get(sha(String(req.query.token || "")), Date.now());
  const lg = mlang(req.query.lang);
  if (!row || emailTaken(row.norm_email, row.user_id)) return res.status(400).send(mailPage("Link not valid", "<p>" + mailEsc(mt(lg).eBad) + '</p><a class="btn" href="/">' + mailEsc(mt(lg).back) + "</a>", false, lg));
  db.prepare("UPDATE accounts SET email = ?, norm_email = ?, email_verified = 1 WHERE id = ?").run(row.email, row.norm_email, row.user_id);
  db.prepare("DELETE FROM mail_tokens WHERE token_hash = ?").run(row.token_hash);
  res.send(mailPage(mt(lg).eTitle, "<p>" + mailEsc(mt(lg).eDone) + '</p><a class="btn" href="/">' + mailEsc(mt(lg).back) + "</a>", true, lg));
});

// ---------- the owner's view ----------
app.get("/api/admin/accounts", requireOwner, (req, res) => {
  const now = Date.now();
  const name = (id) => { const u = db.prepare("SELECT id, username, multi_ok, last_seen FROM users WHERE id = ?").get(id); return u ? { id: u.id, name: u.username, ok: !!u.multi_ok, lastSeen: u.last_seen } : null; };
  const group = (col) => {
    const out = [];
    for (const g of db.prepare("SELECT " + col + " AS k FROM device_links GROUP BY " + col + " HAVING COUNT(DISTINCT user_id) > 1").all()) {
      const users = db.prepare("SELECT DISTINCT user_id FROM device_links WHERE " + col + " = ?").all(g.k).map((r) => name(r.user_id)).filter((u) => u && !db.prepare("SELECT bot FROM users WHERE id = ?").get(u.id).bot);
      if (users.length > 1) out.push({ users });
    }
    return out;
  };
  res.json({
    mail: { ready: mailReady(), dev: MAIL_DEV, from: MAIL_FROM || null, problem: mailProblem },
    emailRequired: emailRequired(),
    deviceCap: deviceCap(),
    verified: db.prepare("SELECT COUNT(*) AS n FROM users WHERE email_verified = 1").get().n,
    waiting: db.prepare("SELECT COUNT(*) AS n FROM pending_signups WHERE created_at > ?").get(now - SIGNUP_HOURS * 3600000).n,
    pending: db.prepare("SELECT rowid AS id, username, email, created_at FROM pending_signups WHERE created_at > ? ORDER BY created_at DESC").all(now - SIGNUP_HOURS * 3600000),
    sameDevice: group("device"),
    sameNetwork: group("ip_hash").filter((g) => !db.prepare("SELECT 1 FROM device_links a JOIN device_links b ON a.device = b.device AND a.user_id < b.user_id WHERE a.user_id = ? AND b.user_id = ?").get(g.users[0].id, g.users[1].id)),
  });
});
// the owner clears a sign-up whose confirmation mail never arrived, so the player can register again
app.post("/api/admin/pending-clear", requireOwner, (req, res) => {
  const id = Number((req.body || {}).id);
  const row = id ? db.prepare("SELECT username FROM pending_signups WHERE rowid = ?").get(id) : null;
  if (!row) return res.status(404).json({ error: "That sign-up is already gone." });
  db.prepare("DELETE FROM pending_signups WHERE rowid = ?").run(id);
  res.json({ ok: true, message: "Cleared the waiting sign-up of " + row.username + ". They can register again." });
});
// ---------- 🌍 community translations ----------
// players suggest a better text for a phrase, an owner approves it, and approved texts replace the built-in ones
db.exec("CREATE TABLE IF NOT EXISTS translations (id INTEGER PRIMARY KEY AUTOINCREMENT, lang TEXT NOT NULL, key TEXT NOT NULL, text TEXT NOT NULL, author TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'pending', created_at INTEGER NOT NULL, decided_at INTEGER, decided_by TEXT)");
db.exec("CREATE INDEX IF NOT EXISTS idx_translations_lang ON translations (lang, status)");
db.exec("CREATE TABLE IF NOT EXISTS i18n_seen (key TEXT PRIMARY KEY, n INTEGER NOT NULL DEFAULT 1, last_at INTEGER NOT NULL)");
db.exec("CREATE TABLE IF NOT EXISTS i18n_skips (username TEXT NOT NULL, key TEXT NOT NULL, skipped_at INTEGER NOT NULL, PRIMARY KEY(username,key))");
const TR_LANG_ORDER = ["de", "it", "fr", "tr", "es", "ru", "vi", "pt", "id", "pl", "cs", "sk"]; // same order as the arrays in the page
function trLangs() { return Object.keys(MAIL_LANGS).filter((l) => l !== "en"); }
// the built-in phrases, read out of the page itself so there is only one place to edit them
let BUILTIN_STRINGS = null;
function builtInStrings() {
  if (BUILTIN_STRINGS) return BUILTIN_STRINGS;
  const a = PAGE.indexOf("/*GTR*/") + 7, b = PAGE.indexOf("/*GTR_END*/");
  try { BUILTIN_STRINGS = JSON.parse("{" + PAGE.slice(a, b).trim().replace(/,\s*$/, "") + "}"); } catch (e) { return {}; }
  return BUILTIN_STRINGS;
}
function translationProblem(key, text) {
  if (typeof key !== "string" || typeof text !== "string") return "Missing text";
  text = text.trim();
  if (!text) return "Write a translation first";
  if (key.length > 800 || text.length > 900) return "That text is too long";
  if (!/[A-Za-z]{2}/.test(key)) return "That phrase can’t be translated";
  if (/[<>]/.test(text)) return "Plain text only, no < or >";
  if ((key.match(/#/g) || []).length !== (text.match(/#/g) || []).length) return "Keep every # in the text: it stands for a number";
  return "";
}
// Names are account data, not game copy. Keep player handles out of both the
// translator suggestions and the shared list of phrases players have seen.
let translationNamesCache = [], translationNamesCachedAt = 0;
function translationSourceHasPlayerName(source) {
  const text = String(source || "");
  if (Date.now() - translationNamesCachedAt > 15000) {
    translationNamesCache = db.prepare("SELECT username FROM users").all().map((row) => String(row.username || "").trim()).filter((name) => name.length >= 2);
    translationNamesCachedAt = Date.now();
  }
  return translationNamesCache.some((name) => {
    if (name.length < 2) return false;
    const escaped = name.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
    return new RegExp("(^|[^A-Za-z0-9_])" + escaped + "($|[^A-Za-z0-9_])", "i").test(text);
  });
}
// Approved translations survive rounds and synchronize via the account hub.
function approvedTranslations() { return db.prepare("SELECT lang,key,text,decided_at FROM translations WHERE status='approved' ORDER BY decided_at,id").all(); }
function mergeTranslations(rows) {
  db.exec("BEGIN IMMEDIATE");
  try {
    for (const r of rows) {
    if(!trLangs().includes(r.lang)||translationProblem(r.key,r.text)||!Number.isFinite(r.decided_at))continue;
    const prev=db.prepare("SELECT decided_at,text FROM translations WHERE lang=? AND key=? AND status='approved' ORDER BY decided_at DESC LIMIT 1").get(r.lang,r.key);
    if(prev && prev.decided_at>=r.decided_at)continue;
    db.prepare("UPDATE translations SET status='superseded' WHERE lang=? AND key=? AND status='approved'").run(r.lang,r.key);
    db.prepare("INSERT INTO translations(lang,key,text,author,status,created_at,decided_at,decided_by) VALUES(?,?,?,'sync','approved',?,?,'sync')").run(r.lang,r.key,r.text,r.decided_at,r.decided_at);
    }
    db.exec("COMMIT");
  } catch (err) {
    db.exec("ROLLBACK");
    throw err;
  }
}
let translationSyncAt=0,translationSyncJob=null;
async function syncTranslations(force=false) {
  if(!HUB_URL||!HOP_SHARED)return;
  if(translationSyncJob)return translationSyncJob;
  if(!force && Date.now()-translationSyncAt<5000)return;
  translationSyncJob=(async()=>{
    const body=JSON.stringify({rows:approvedTranslations()});
    const signature=crypto.createHmac('sha256',HOP_SECRET).update(body).digest('hex');
    const response=await fetch(HUB_URL+'/api/i18n/sync',{method:'POST',headers:{'Content-Type':'application/json','X-Translation-Signature':signature},body,signal:AbortSignal.timeout(8000)});
    if(!response.ok)throw new Error('Translation sync failed');
    const result=await response.json();if(!Array.isArray(result.rows))throw new Error('Invalid translation sync response');
    mergeTranslations(result.rows);translationSyncAt=Date.now();
  })().finally(()=>{translationSyncJob=null;});
  return translationSyncJob;
}
app.post('/api/i18n/sync',(req,res)=>{
  if(HUB_URL||!HOP_SHARED)return res.status(403).json({error:'Not a translation hub'});
  const expected=crypto.createHmac('sha256',HOP_SECRET).update(JSON.stringify(req.body)).digest('hex');
  const sig=String(req.get('X-Translation-Signature')||'');
  if(sig.length!==expected.length||!crypto.timingSafeEqual(Buffer.from(sig),Buffer.from(expected)))return res.status(403).json({error:'Invalid signature'});
  if(!Array.isArray(req.body.rows)||req.body.rows.length>20000)return res.status(400).json({error:'Invalid translations'});
  mergeTranslations(req.body.rows);res.json({rows:approvedTranslations()});
});
setInterval(()=>{syncTranslations().catch(()=>{});},5000);
app.get("/api/i18n", (req, res) => {
  // Propagate in the background so the language file is always served quickly.
  syncTranslations().catch(()=>{});
  const lang = String(req.query.lang || "");
  const state = db.prepare("SELECT COUNT(*) AS n, COALESCE(MAX(decided_at),0) AS rev FROM translations WHERE lang = ? AND status = 'approved'").get(lang);
  const etag = '"i18n-' + lang + '-' + state.n + '-' + state.rev + '"';
  res.setHeader("ETag", etag);
  const out = {};
  res.setHeader("Cache-Control", "no-cache");
  if (req.get("If-None-Match") === etag) return res.status(304).end();
  if (trLangs().includes(lang)) db.prepare("SELECT key, text FROM translations WHERE lang = ? AND status = 'approved' ORDER BY id").all(lang).forEach((r) => { out[r.key] = r.text; });
  res.json(out);
});
app.get("/api/i18n/mine", requireLogin, (req, res) => {
  const lang = String(req.query.lang || "");
  const out = {};
  db.prepare("SELECT key, text FROM translations WHERE lang = ? AND author = ? AND status = 'pending'").all(lang, req.user.username).forEach((r) => { out[r.key] = r.text; });
  res.json({ pending: out });
});
app.post("/api/i18n/suggest", requireLogin, (req, res) => {
  const b = req.body || {};
  const lang = String(b.lang || "");
  if (!trLangs().includes(lang)) return res.status(400).json({ error: "Unknown language" });
  const bad = translationProblem(b.key, b.text);
  if (bad) return res.status(400).json({ error: bad });
  if (!Object.prototype.hasOwnProperty.call(builtInStrings(), b.key)) return res.status(400).json({ error: "Choose a phrase from the game text catalog." });
  const text = b.text.trim();
  const now = Date.now();
  if (db.prepare("SELECT COUNT(*) AS n FROM translations WHERE author = ? AND created_at > ?").get(req.user.username, now - 86400000).n >= 150) return res.status(429).json({ error: "That’s plenty for today. Thank you! Come back tomorrow." });
  db.prepare("DELETE FROM translations WHERE author = ? AND lang = ? AND key = ? AND status = 'pending'").run(req.user.username, lang, b.key);
  db.prepare("INSERT INTO translations (lang, key, text, author, created_at) VALUES (?, ?, ?, ?, ?)").run(lang, b.key, text, req.user.username, now);
  res.json({ ok: true });
});
// phrases players met that are not translated yet: they become the source list for translators
app.post("/api/i18n/seen", requireLogin, (req, res) => res.json({ ok: true }));
app.post("/api/i18n/filter-suggestions", requireLogin, (req, res) => {
  const keys = Array.isArray((req.body || {}).keys) ? req.body.keys.slice(0, 250) : [];
  const blocked = keys.filter((key) => typeof key !== "string" || key.length > 800 || translationSourceHasPlayerName(key));
  res.json({ blocked });
});
app.get("/api/i18n/skipped", requireLogin, (req, res) => {
  const keys = db.prepare("SELECT key FROM i18n_skips WHERE username = ?").all(req.user.username).map((row) => row.key);
  res.json({ keys });
});
app.post("/api/i18n/skip", requireLogin, (req, res) => {
  const key = (req.body || {}).key;
  if (typeof key !== "string" || !Object.prototype.hasOwnProperty.call(builtInStrings(), key)) return res.status(400).json({ error: "That phrase can’t be skipped." });
  db.prepare("INSERT INTO i18n_skips(username,key,skipped_at) VALUES(?,?,?) ON CONFLICT(username,key) DO UPDATE SET skipped_at=excluded.skipped_at").run(req.user.username, key, Date.now());
  res.json({ ok: true });
});
app.get("/api/admin/translations", requireOwner, (req, res) => {
  const rows = db.prepare("SELECT id, lang, key, text, author, created_at FROM translations WHERE status = 'pending' ORDER BY lang, id LIMIT 400").all();
  const built = builtInStrings();
  rows.forEach((r) => { const i = TR_LANG_ORDER.indexOf(r.lang); r.old = built[r.key] && i >= 0 ? built[r.key][i] || "" : ""; });
  const counts = {};
  trLangs().forEach((l) => {
    const i = TR_LANG_ORDER.indexOf(l);
    counts[l] = { approved: db.prepare("SELECT COUNT(DISTINCT key) AS n FROM translations WHERE lang = ? AND status = 'approved'").get(l).n, built: Object.keys(built).filter((k) => built[k][i]).length };
  });
  res.json({ pending: rows, counts, langs: trLangs(), seen: db.prepare("SELECT COUNT(*) AS n FROM i18n_seen").get().n, total: Object.keys(built).length });
});
app.post("/api/admin/translations/decide", requireOwner, async (req, res) => {
  const b = req.body || {};
  const ids = (Array.isArray(b.ids) ? b.ids : [b.id]).map(Number).filter(Boolean).slice(0, 400);
  let n = 0;
  ids.forEach((id) => {
    const r = db.prepare("SELECT * FROM translations WHERE id = ? AND status = 'pending'").get(id);
    if (!r) return;
    let text = r.text;
    if (b.ok && typeof b.text === "string" && ids.length === 1) {
      if (translationProblem(r.key, b.text)) return;
      text = b.text.trim();
    }
    if (b.ok) db.prepare("UPDATE translations SET status = 'superseded' WHERE lang = ? AND key = ? AND status = 'approved'").run(r.lang, r.key);
    db.prepare("UPDATE translations SET status = ?, text = ?, decided_at = ?, decided_by = ? WHERE id = ?").run(b.ok ? "approved" : "rejected", text, Date.now(), req.user.username, id);
    n++;
  });
  adminLog(req, (b.ok ? "Approved " : "Rejected ") + n + " translation" + (n === 1 ? "" : "s"));
  let syncPending=false;try{await syncTranslations(true);}catch(e){syncPending=true;}
  const syncNote = syncPending ? " · saved locally; cross-server sync pending" : !HOP_SHARED ? (HUB_URL ? " · saved locally; set the same HOP_SECRET on every server" : " · saved on this standalone server; configure HOP_SECRET and connect the other servers to the main hub") : HUB_URL ? " · shared with the main server hub" : " · published on this shared hub; connected servers receive it within seconds";
  res.json({ ok: true, message: (b.ok ? "Approved " : "Rejected ") + n + (b.ok ? syncNote : "") });
});
// a translation file for Crowdin, Weblate or any text editor: { "English phrase": "translation" }
app.get("/api/admin/i18n-export", requireOwner, (req, res) => {
  const lang = String(req.query.lang || "");
  const built = builtInStrings();
  const i = TR_LANG_ORDER.indexOf(lang);
  const out = {};
  const keys = new Set(Object.keys(built));
  db.prepare("SELECT DISTINCT key FROM translations WHERE status = 'approved'").all().forEach((r) => keys.add(r.key));
  const own = {};
  if (lang !== "en" && i >= 0) db.prepare("SELECT key, text FROM translations WHERE lang = ? AND status = 'approved' ORDER BY id").all(lang).forEach((r) => { own[r.key] = r.text; });
  [...keys].sort().forEach((k) => { out[k] = lang === "en" ? k : own[k] || (built[k] && built[k][i]) || ""; });
  if (lang !== "en" && i < 0) return res.status(400).json({ error: "Unknown language" });
  res.setHeader("Content-Disposition", 'attachment; filename="marsl-' + lang + '.json"');
  res.setHeader("Content-Type", "application/json; charset=utf-8");
  res.end(JSON.stringify(out, null, 1));
});
app.post("/api/admin/i18n-import", requireOwner, (req, res) => {
  const b = req.body || {};
  const lang = String(b.lang || "");
  if (!trLangs().includes(lang)) return res.status(400).json({ error: "Unknown language" });
  const strings = b.strings && typeof b.strings === "object" ? b.strings : null;
  if (!strings) return res.status(400).json({ error: "Paste a JSON file first" });
  const built = builtInStrings();
  const i = TR_LANG_ORDER.indexOf(lang);
  const now = Date.now();
  let n = 0, skipped = 0;
  Object.keys(strings).slice(0, 6000).forEach((k) => {
    const t = strings[k];
    if (typeof t !== "string" || !t.trim() || translationProblem(k, t)) { if (typeof t === "string" && t.trim()) skipped++; return; }
    if (built[k] && built[k][i] === t.trim()) return; // unchanged
    db.prepare("UPDATE translations SET status = 'superseded' WHERE lang = ? AND key = ? AND status = 'approved'").run(lang, k);
    db.prepare("INSERT INTO translations (lang, key, text, author, status, created_at, decided_at, decided_by) VALUES (?, ?, ?, ?, 'approved', ?, ?, ?)").run(lang, k, t.trim(), "import", now, now, req.user.username);
    n++;
  });
  adminLog(req, "Imported " + n + " " + lang + " translations");
  res.json({ ok: true, message: "Imported " + n + " translation" + (n === 1 ? "" : "s") + (skipped ? ", skipped " + skipped + " that broke the rules (# count, < >)" : "") });
});
app.post("/api/admin/accounts", requireOwner, (req, res) => {
  const b = req.body || {};
  const msgs = [];
  if (b.emailRequired !== undefined) {
    if (b.emailRequired && !mailReady()) return res.status(400).json({ error: "Set BREVO_API_KEY and MAIL_FROM on the server first" });
    setSetting("email_required", b.emailRequired ? "1" : "0");
    msgs.push(b.emailRequired ? "Sign-up needs a confirmed email" : "Sign-up without email");
  }
  if (b.deviceCap !== undefined) {
    const n = Math.max(0, Math.min(20, Math.round(Number(b.deviceCap)) || 0));
    setSetting("device_cap", String(n));
    msgs.push(n ? "Max " + n + " accounts per device" : "No account limit per device");
  }
  if (b.userId !== undefined) {
    const u = db.prepare("SELECT username FROM users WHERE id = ?").get(Number(b.userId));
    if (!u) return res.status(400).json({ error: "No such player" });
    db.prepare("UPDATE users SET multi_ok = ? WHERE id = ?").run(b.ok ? 1 : 0, Number(b.userId));
    msgs.push(u.username + (b.ok ? " is cleared (not linked to anyone)" : " is linked again"));
  }
  const message = msgs.join(" · ") || "Saved";
  adminLog(req, message);
  res.json({ ok: true, message });
});
// =====================================================================
//  🎖️ THE COMMANDER - every player has one. It is stationed in one of
//  your colonies. From there it can lead attacks and raids, it makes the
//  colony harder to take while it is at home, and (with the Foreman
//  skill) it boosts that colony's production.
//  It gains experience in battle, finds gear in monster camps and keeps
//  the bounty of the camps it beats in its inventory.
//  It can fall: then it needs a full server day to recover and loses a
//  quarter of its progress to the next level. Moving it to another colony
//  takes a walk and a minute of settling in (no bonus anywhere meanwhile),
//  so it can't flip back and forth between colonies.
//  Bonuses stay small on purpose.
// =====================================================================
