function heroPoints(h) {
  return {
    atk: Math.round((HERO_ATK_BASE + HERO_ATK_LVL * (h.level - 1) + h.pts.str * HERO_SKILLS.str.per + heroGearStats(h).atk) * speedScale()),
    def: Math.round((HERO_DEF_BASE + HERO_DEF_LVL * (h.level - 1) + h.pts.str * HERO_SKILLS.str.per + heroGearStats(h).def) * speedScale()),
  };
}
// gear from older versions: bring it up to the current table
function heroFixItem(x) {
  if (!x || x.kind === "crate" || !HERO_GEAR[x.slot]) return x;
  const ti = Math.max(0, Math.min(3, (x.tier || 1) - 1));
  x.tier = ti + 1;
  const G = HERO_GEAR[x.slot];
  x.name = G.tiers[ti][0];
  x.icon = G.tiers[ti][1];
  x.rarity = HERO_RARITY[ti].key;
  delete x.pct;
  delete x.pts;
  // bonus stats are picked once (older gear gets them now)
  if (!Array.isArray(x.aff)) {
    const pool = Object.keys(HERO_AFFIX).filter((k) => !G.main[k]);
    x.aff = [];
    for (let i = 0; i < HERO_AFFIX_N[ti] && pool.length; i++) x.aff.push(pool.splice(Math.floor(Math.random() * pool.length), 1)[0]);
  }
  x.stats = {};
  for (const k in G.main) x.stats[k] = G.main[k][ti];
  for (const k of x.aff) if (HERO_AFFIX[k]) x.stats[k] = (x.stats[k] || 0) + HERO_AFFIX[k] * (ti + 1);
  x.rank=Math.max(0,Math.min(5,Math.floor(x.rank||0)));
  for(const k in x.stats)x.stats[k]=Math.round(x.stats[k]*(1+x.rank*.08)*100)/100;
  if(x.rank)x.name += " +"+x.rank;
  return x;
}

// experience from level L to L+1: a smooth curve (100, 240, 420, 640 ... 8740)
function heroNeed(level) {
  return Math.round((80 * level + 20 * level * level) / 10) * 10;
}
function heroSpeed(h) {
  return HERO_SPEED * (1 + heroGearStats(h).move / 100 + ((h.pts && h.pts.way) || 0) * HERO_SKILLS.way.per / 100) * (heroRule(h, "explorer", 75) ? 2 : 1);
}
function heroRecoverMs() {
  return Math.round(serverDayMs() * 0.25);
}
function heroLockMs() {
  return Math.round(HERO_SETTLE_MS / MOVE_SPEED); // settling in after a move
}

function heroDefault(userId) {
  const cols = coloniesOf(userId);
  const main = cols.find((c) => c.state.main) || cols[0];
  return { name: "Commander", arch: "", home: main ? main.id : 0, level: 1, xp: 0, pts: Object.assign({}, HERO_PTS0), away: 0, hurtUntil: 0, lockUntil: 0, move: null, gear: { weapon: null, armor: null }, bag: [] };
}
// The commander of a player, brought up to date (back home? moved? healed?)
function heroOf(userId, now) {
  now = now || Date.now();
  const row = db.prepare("SELECT hero FROM users WHERE id = ?").get(userId);
  if (!row) return null;
  let h = null;
  try { h = row.hero ? JSON.parse(row.hero) : null; } catch (e) {}
  if (!h) h = heroDefault(userId);
  h.pts = Object.assign({}, HERO_PTS0, h.pts || {});
  // older saves: Leadership + Guard became Strength (what doesn't fit is free again)
  if (h.pts.lead !== undefined || h.pts.guard !== undefined) {
    h.pts.str = Math.min(HERO_SKILLS.str.max, (h.pts.str || 0) + (h.pts.lead || 0) + (h.pts.guard || 0));
    delete h.pts.lead;
    delete h.pts.guard;
  }
  // Clamp legacy allocations; removed points become free without deleting XP or gear.
  let budget = Math.max(0, (h.level - 1) * 4);
  for (const k of Object.keys(HERO_SKILLS)) {
    const limit = heroSkillLimit(h, k);
    h.pts[k] = Math.min(budget, limit, Math.max(0, Math.floor(Number(h.pts[k]) || 0)));
    budget -= h.pts[k];
  }
  h.gear = Object.assign({ weapon: null, armor: null, helmet: null, boots: null, trinket: null }, h.gear || {});
  h.bag = h.bag || [];
  h.bag.forEach(heroFixItem);
  for (const slot of HERO_SLOTS) heroFixItem(h.gear[slot]);
  h.lockUntil = h.lockUntil || 0;
  if (h.away && !db.prepare("SELECT 1 FROM movements WHERE id = ?").get(h.away)) h.away = 0;
  h.stats = Object.assign({ fights: 0, wins: 0, xp: 0, adv: 0 }, h.stats || {});
  if (h.level >= HERO_QUIRK_LEVEL && !HERO_QUIRKS[h.quirk]) { const qk = Object.keys(HERO_QUIRKS); h.quirk = qk[Math.floor(Math.random() * qk.length)]; h.quirkNew = 1; }
  if (h.stance && !HERO_STANCES[h.stance]) h.stance = "";
  if (h.adv && now >= h.adv.until) advFinish(userId, h); // back from an adventure
  if (advSync(h, now)) heroSave(userId, h);
  if (h.move && now >= h.move.at) {
    h.home = h.move.to;
    h.lockUntil = h.move.at + heroLockMs();
    h.move = null;
  }
  const mine = colonyIdsOf(userId);
  if (!mine.includes(h.home)) {
    h.home = mine[0] || 0;
    h.move = null;
  }
  const tr = h.home ? db.prepare("SELECT tribe FROM colonies WHERE id = ?").get(h.home) : null;
  h.tribe = tr ? tr.tribe : h.tribe || "human";
  return h;
}
function heroSave(userId, h) {
  db.prepare("UPDATE users SET hero = ? WHERE id = ?").run(JSON.stringify(h), userId);
  heroProdCache.delete(userId);
  heroPerkCache.delete(userId);
}
function heroFree(h) {
  return (h.level - 1) * 4 - Object.keys(HERO_SKILLS).reduce((n, k) => n + (h.pts[k] || 0), 0);
}
// Bonuses in percent
function heroBonus(h) {
  return {
    atk: Math.min(30, heroGearStats(h).atkPct + (h.pts.spear || 0) * HERO_SKILLS.spear.per + (h.tribe === "chicken" ? (h.pts.path || 0) * HERO_PATHS.chicken.per * (1+heroGearStats(h).identity/100) : 0)),
    def: Math.min(30, heroGearStats(h).defPct + (h.tribe === "human" ? (h.pts.path || 0) * HERO_PATHS.human.per * (1+heroGearStats(h).identity/100) : 0)),
    mend: heroMend(h) * 100,
    atk: Math.min(30, heroGearStats(h).atkPct + (h.pts.spear || 0) * HERO_SKILLS.spear.per + (h.pts.haul || 0) * HERO_SKILLS.haul.per + (h.tribe === "chicken" ? (h.pts.path || 0) * HERO_PATHS.chicken.per * (1+heroGearStats(h).identity/100) : 0)),
    def: Math.min(30, heroGearStats(h).defPct + (h.pts.haul || 0) * HERO_SKILLS.haul.per + (h.tribe === "human" ? (h.pts.path || 0) * HERO_PATHS.human.per * (1+heroGearStats(h).identity/100) : 0)),
    carry: heroGearStats(h).carry,
    prod: Math.round(h.pts.prod * HERO_SKILLS.prod.per * PRODUCTION_SPEED * 10) / 10, // real per hour, like the fields
    prodPct: Math.min(25, h.pts.prod * HERO_SKILLS.prod.pct + heroGearStats(h).prod), // and a share of the colony's own production
  };
}
function heroHome(h, colonyId, now) {
  return h.home === colonyId && !h.away && !h.move && !h.adv && !(h.hurtUntil > now);
}

// ⛏️ Foreman: the commander's own production (a fixed amount of every
// resource per hour, the same in a small and a big colony), only in the
// colony it is stationed in. Cached for a few seconds, because the
// production is asked for all the time.
heroReady = true;
const heroProdCache = new Map();
// 🎭 archetype rules and quirks that change colony numbers (upkeep, bunkers, market)
var heroPerkCache = new Map();
function heroPerks(userId) {
  if (!userId || BOT_IDS.has(userId) || !heroReady) return null;
  const now = Date.now();
  let c = heroPerkCache.get(userId);
  if (!c || c.until <= now) {
    const h = heroOf(userId, now);
    c = {
      until: now + 20000,
      home: h ? h.home : 0,
      glutton: !!h && h.quirk === "glutton",
      qm25: heroRule(h, "quartermaster", 25),
      qm50: heroRule(h, "quartermaster", 50),
      qm75: heroRule(h, "quartermaster", 75),
      qm100: heroRule(h, "quartermaster", 100),
      stash: h && h.arch === "quartermaster" ? (h.pts.stash || 0) * HERO_SKILLS.stash.per : 0,
    };
    heroPerkCache.set(userId, c);
  }
  return c;
}
function heroProdFlat(userId, colonyId) {
  if (!userId || !colonyId || BOT_IDS.has(userId)) return 0;
  const now = Date.now();
  let c = heroProdCache.get(userId);
  if (!c || c.until <= now) {
    const h = heroOf(userId, now);
    c = { at: 0, flat: 0, pct: 0, until: now + 20000 };
    // 1.0.224: it produces in its home colony whatever it is doing (away, on the road, on an adventure or recovering)
    if (h && (h.pts.prod > 0 || heroBonus(h).prodPct > 0) && h.home) {
      c.at = h.home;
      c.flat = heroBonus(h).prod;
      c.pct = heroBonus(h).prodPct;
    }
    if (h && h.move) c.until = Math.min(c.until, h.move.at);
    if (h && h.adv) c.until = Math.min(c.until, h.adv.until);
    if (h && h.hurtUntil > now) c.until = Math.min(c.until, h.hurtUntil);
    heroProdCache.set(userId, c);
  }
  return c.at === colonyId ? c : null;
}
// Bring all colonies of a player up to date (before archetype rules or quirks change upkeep)
function heroSettleAll(userId, now) {
  for (const id of colonyIdsOf(userId)) heroSettle(id, now);
  heroPerkCache.delete(userId);
}
// Bring a colony up to date (before its production changes)
function heroSettle(colonyId, now) {
  const c = colonyId ? loadColony(colonyId) : null;
  if (!c) return;
  update(c.state, tribeOf(c.tribe), now);
  saveColony(c.id, c.state);
}

// Can the commander go along on this trip?
function heroSendCheck(userId, colonyId, mission, kind) {
  const h = heroOf(userId);
  if (!h) return "You have no commander";
  if (!["attack", "raid"].includes(mission)) return "The commander only leads attacks and raids";
  if (!["colony", "camp", "landmark"].includes(kind)) return "The commander only fights at colonies, monster camps and landmarks";
  const now = Date.now();
  if (h.hurtUntil > now) return "Your commander is still recovering";
  if (h.adv) return "Your commander is on an adventure";
  if (h.home !== colonyId || h.move) return "Your commander is not in this colony";
  if (h.away) return "Your commander is already out with an army";
  return null;
}
function heroGoes(userId, movementId) {
  const h = heroOf(userId);
  h.away = movementId;
  heroSave(userId, h);
}
// ⚔️ orders against 🛡️ stances: every order beats one stance and loses to another.
// The defending stance counts when its commander is at home (Warlord 75: Fortify
// and Ambush also while it is away). Returns multipliers for the fight.
function defStance(col, now) {
  if (!col || BOT_IDS.has(col.userId)) return null;
  const h = heroOf(col.userId, now);
  if (!h || !HERO_STANCES[h.stance] || h.home !== col.id) return null;
  if (heroHome(h, col.id, now)) return { key: h.stance, h };
  if (h.stance !== "evacuate" && heroRule(h, "warlord", 75)) return { key: h.stance, h };
  return null;
}
function battleMods(order, aHero, st) {
  const M = { atk: 1, loss: 1, carry: 1, bomb: 1, def: 1, hide: 1, aimOff: false, view: null };
  const O = aHero && HERO_ORDERS[order] ? order : "";
  const S = st ? st.key : "";
  if (!O && !S) return M;
  const k = 1 + (aHero ? (aHero.pts.orders || 0) * HERO_SKILLS.orders.per / 100 : 0);
  const ks = (1 + (st ? (st.h.pts.bulwark || 0) * HERO_SKILLS.bulwark.per / 100 : 0)) * (aHero && heroRule(aHero, "warlord", 100) && O ? 0.5 : 1);
  if (O === "charge") {
    M.atk *= 1 + 0.15 * k + (aHero.quirk === "showoff" ? 0.05 : 0);
    if (!heroRule(aHero, "warlord", 25)) M.loss *= 1.1;
  } else if (O === "pillage") {
    M.carry *= 1 + 0.3 * k;
    if (!heroRule(aHero, "warlord", 50)) M.atk *= 0.9;
  } else if (O === "precision") {
    M.bomb *= 1 + 0.25 * k;
  }
  if (S === "fortify") {
    if (O === "charge") M.def *= 1 + 0.15 * ks;
    if (O === "pillage") M.hide *= 0.7;
  } else if (S === "ambush") {
    if (O === "pillage") M.def *= 1 + 0.2 * ks;
    if (O === "precision") M.def *= 0.9;
  } else if (S === "evacuate") {
    M.hide *= 1 + 0.3 * (1 + (st.h.pts.bulwark || 0) * HERO_SKILLS.bulwark.per / 100);
    M.def *= 0.9;
    if (O === "precision") M.aimOff = true;
  }
  const res = O && S ? (HERO_ORDERS[O].beats === S ? "win" : HERO_ORDERS[O].loses === S ? "lose" : "even") : "";
  M.view = { order: O ? { key: O, icon: HERO_ORDERS[O].icon, name: HERO_ORDERS[O].name } : null, stance: S ? { key: S, icon: HERO_STANCES[S].icon, name: HERO_STANCES[S].name } : null, result: res };
  return M;
}
function lossWith(frac, mul) {
  return frac >= 1 ? 1 : Math.min(1, frac * mul);
}
// attack (ground + air) of an army led by the commander
function heroLead(attack, h) {
  const k = (1 + heroBonus(h).atk / 100) * (h.quirk === "coward" ? 0.95 : 1);
  return { g: attack.g * k + heroPoints(h).atk, a: attack.a * k };
}
// The defending commander (only at home and healthy)
function heroDefending(col, now) {
  if (!col || BOT_IDS.has(col.userId)) return null;
  const h = heroOf(col.userId, now);
  return h && heroHome(h, col.id, now) ? h : null;
}
function heroGuard(defense, h) {
  const k = 1 + heroBonus(h).def / 100;
  const p = heroPoints(h).def;
  defense.g = defense.g * k + p;
  defense.a = defense.a * k + p;
}
function heroItem(slot, tier) {
  if (!HERO_GEAR[slot]) slot = HERO_SLOTS[Math.floor(Math.random() * HERO_SLOTS.length)];
  return heroFixItem({ id: crypto.randomBytes(4).toString("hex"), kind: "gear", slot, tier: tier + 1 });
}
const HERO_CONSUMABLES = {
  dressing: {icon:"🩹",name:"Field dressing",text:"Restores 25 commander health. Use while at home.",heal:25,weight:45},
  medkit: {icon:"🧰",name:"Medkit",text:"Restores 60 commander health. Use while at home.",heal:60,weight:25},
  journal: {icon:"📓",name:"Field journal",text:"Grants 10% of the XP needed for your current level. Use while at home.",weight:20},
  recovery: {icon:"💊",name:"Recovery kit",text:"Halves remaining fallen recovery time, leaving at least one minute.",weight:10},
  respec: {icon:"🧭",name:"Insight token",text:"Uncommon. Required to reset commander skills.",weight:12}
};
function heroConsumableDrop(h, kind, route) {
  if(Math.random() >= (kind === "long" ? .20 : kind === "medium" ? .15 : .10) + (route === "danger" ? .05 : 0)) return null;
  const keys=Object.keys(HERO_CONSUMABLES); let roll=Math.random()*100;
  const key=keys.find(k => (roll-=HERO_CONSUMABLES[k].weight)<0)||keys[0];
  h.consumables=h.consumables||{};
  h.consumables[key]=Math.max(0,Math.floor(Number(h.consumables[key])||0))+1;
  return {key,icon:HERO_CONSUMABLES[key].icon,name:HERO_CONSUMABLES[key].name,count:1};
}
function heroCrate(h) {
  return h.bag.find((x) => x.kind === "crate") || null;
}
// After a fight: experience, maybe a new level, the bounty of a camp,
// maybe gear, maybe a fall. Returns a short note for the report.
function heroAfterFight(userId, h, o) {
  // one fight gives at most one level, so a big battle can not skip the curve
  const cap = h.level >= HERO_MAX_LEVEL ? 0 : heroNeed(h.level);
  const G = heroGearStats(h);
  const note = { name: h.name, level: h.level, bonus: o.bonus, xp: Math.max(0, Math.min(cap, Math.round(o.xp * (o.scrap ? 1 : 1 + G.xp / 100)))) };
  if (o.dmg > 0) o.dmg *= 1 - Math.min(HERO_CAPS.ward, G.ward + ((h.pts && h.pts.vit) || 0) * HERO_SKILLS.vit.ward) / 100;
  const huntPct = h.arch === "explorer" ? (h.pts.hunter || 0) * HERO_SKILLS.hunter.per : 0;
  if (o.bounty && (G.bounty || huntPct)) {
    const b = {};
    for (const r of RESOURCES) b[r] = Math.round((o.bounty[r] || 0) * (1 + (G.bounty + huntPct) / 100));
    o.bounty = b;
  }
  h.stats = Object.assign({ fights: 0, wins: 0, xp: 0, adv: 0 }, h.stats || {});
  if (o.won !== undefined || o.beaten !== undefined) {
    h.stats.fights++;
    if (o.won || (o.won === undefined && !o.beaten)) h.stats.wins++;
  }
  if(o.campTier===2)note.xp=Math.round(note.xp*(1+heroGearStats(h).frontier/100));
  h.stats.xp += note.xp;
  // ❤️ what the fight or the trip cost
  if (o.dmg > 0) {
    const hp = heroHp(h, o.at);
    const left = Math.round(hp - o.dmg);
    note.hpLost = Math.round(Math.min(hp, o.dmg));
    o._left = left;
    if (left <= 0 && !o.safe) o.beaten = true;
    else heroSetHp(h, Math.max(1, left), o.at);
  }
  // 🐔 a coward runs before it can fall
  if (o.beaten && !o.safe && h.quirk === "coward") { o.beaten = false; if (o._left !== undefined && o._left <= 0) heroSetHp(h, 1, o.at); note.ranAway = true; }
  h.xp += note.xp;
  while (h.level < HERO_MAX_LEVEL && h.xp >= heroNeed(h.level)) {
    h.xp -= heroNeed(h.level);
    h.level++;
    note.levelUp = h.level;
    if (h.level >= HERO_MAX_LEVEL) giveBadge(userId, "legend", "🌟", "Legendary Commander", o.at);
  }
  if (note.levelUp && !o.beaten) heroSetHp(h, HERO_HP, o.at);
  if (h.level >= HERO_MAX_LEVEL) h.xp = 0;
  if (o.beaten) {
    h.away = 0;
    h.hurtUntil = o.at + heroRecoverMs();
    h.hp = HERO_HP_BACK;
    h.hpAt = h.hurtUntil;
    h.xp = Math.round(h.xp * (1 - HERO_FALL_XP));
    note.hurt = true;
  } else {
    // the bounty of a camp goes into the inventory (one stash for all of it)
    if (o.bounty && lootTotal(o.bounty) > 0) {
      let crate = heroCrate(h);
      if (!crate && h.bag.length < HERO_BAG) {
        crate = { id: crypto.randomBytes(4).toString("hex"), kind: "crate", icon: "📦", name: "Bounty stash", res: { wood: 0, stone: 0, metal: 0, food: 0 } };
        h.bag.push(crate);
      }
      if (crate) {
        for (const r of RESOURCES) crate.res[r] = (crate.res[r] || 0) + (o.bounty[r] || 0);
        note.stash = o.bounty;
      }
    }
    if (o.campTier !== undefined && o.won) {
      // monster camps sometimes leave gear behind (better in the outer camps)
      if (Math.random() < (0.06 + 0.04 * o.campTier) * (heroRule(h, "explorer", 100) ? 2 : 1)) {
        const tier = heroRollTier(HERO_DROPS.camp[Math.min(HERO_DROPS.camp.length - 1, o.campTier)]);
        const item = heroItem(null, tier);
        if (h.bag.length < HERO_BAG) {
          h.bag.push(item);
          note.found = item;
        } else note.bagFull = item;
      }
    }
  }
  heroSave(userId, h);
  return note;
}

function heroView(userId, colonyId, now) {
  const h = heroOf(userId, now);
  if (!h) return null;
  heroSave(userId, h);
  const homeCol = h.home ? db.prepare("SELECT name, x, y FROM colonies WHERE id = ?").get(h.home) : null;
  const here = h.home === colonyId;
  let status = "home";
  if (h.hurtUntil > now) status = "fallen";
  else if (h.adv) status = "adventure";
  else if (h.move) status = "moving";
  else if (h.away) status = "away";
  let moveMs = 0;
  if (!here && homeCol) {
    const me = db.prepare("SELECT x, y FROM colonies WHERE id = ?").get(colonyId);
    if (me) moveMs = travelMs(distance(homeCol.x, homeCol.y, me.x, me.y), heroSpeed(h));
  }
  const bonus = heroBonus(h);
  const crate = heroCrate(h);
  return {
    name: h.name,
    level: h.level,
    maxLevel: HERO_MAX_LEVEL,
    xp: h.xp,
    need: h.level >= HERO_MAX_LEVEL ? 0 : heroNeed(h.level),
    free: heroFree(h),
    skills: Object.keys(HERO_SKILLS).map((k) => {
      const sk = Object.assign({ key: k, lvl: h.pts[k], open: heroSkillLimit(h, k) > 0 }, HERO_SKILLS[k], k === "path" ? HERO_PATHS[h.tribe] || HERO_PATHS.human : {});
      if (k === "path") { sk.cap = heroPathMax(h); sk.path = true; if (!sk.cap) sk.lockText = "Opens at level " + HERO_PATH_OPEN; }
      if (k === "str") {
        sk.per = Math.round(sk.per * speedScale());
        sk.btn = "+" + sk.per;
      }
      if (k === "prod") {
        sk.per = sk.per * PRODUCTION_SPEED;
        sk.btn = "+" + Math.round(sk.per*100)/100 + "/h";
        sk.text = HERO_SKILLS.prod.text;
      }
      return sk;
    }),
    bonus,
    status,
    hurtLeft: Math.max(0, h.hurtUntil - now),
    reviveMs: heroReviveMs(),
    reviveCost: status === "fallen" && h.hurtUntil - now > heroReviveMs() ? heroReviveCost(h) : null,
    respecCost: heroRespecCost(h),
    road: HERO_ROAD.map((r) => Object.assign({ done: h.level >= r.lv }, r)),
    moveLeft: h.move ? Math.max(0, h.move.at - now) : 0,
    lockLeft: Math.max(0, h.lockUntil - now),
    here,
    homeId: h.home || 0,
    home: homeCol ? homeCol.name : "",
    moveMs,
    gear: h.gear,
    upgradeScale:1,
    bag: h.bag.map((x) => (x.kind === "crate" ? Object.assign({}, x, { total: lootTotal(x.res) }) : Object.assign({ kind: "gear" }, x))),
    consumables: Object.keys(HERO_CONSUMABLES).map(k=>Object.assign({key:k,count:Math.max(0,Math.floor(Number((h.consumables||{})[k])||0))},HERO_CONSUMABLES[k])),
    bagMax: HERO_BAG,
    stash: crate ? crate.res : null,
    // room in the colony you are looking at (the stash pours into it), so the player sees what fits
    stashTo: (db.prepare("SELECT name FROM colonies WHERE id = ?").get(colonyId) || {}).name || "",
    stashRoom: (function () {
      const hc = colonyId ? loadColony(colonyId) : null;
      if (!hc) return null;
      update(hc.state, tribeOf(hc.tribe), now);
      const cap = capacities(hc.state), room = {};
      for (const r of RESOURCES) room[r] = Math.max(0, Math.floor(cap[r] - hc.state.res[r]));
      return room;
    })(),
    cosmetics:h.cosmetics||[],starMetal:h.starMetal||0,
    stats: h.stats,
    hp: Math.floor(heroHp(h, now)),
    hpMax: HERO_HP,
    regen: heroRegen(h),
    gearStats: heroGearStats(h),
    statInfo: HERO_STATS,
    slots: HERO_SLOTS.map((k) => ({ key: k, name: HERO_GEAR[k].name })),
    hpFullIn: heroHp(h, now) >= HERO_HP || h.hurtUntil > now ? 0 : Math.round(((HERO_HP - heroHp(h, now)) / heroRegen(h)) * serverDayMs()),
    points: heroPoints(h),
    rarities: HERO_RARITY,
    adventure: advView(h, now),
    advEvent: advEventView(h),
    title: legacyTitle(userId),
    // 🎭 archetype, stance, quirk and the order list for the send window
    arch: h.arch === undefined ? null : h.arch,
    archLevel: HERO_ARCH_LEVEL,
    archPts: heroArchPts(h),
    arches: Object.keys(HERO_ARCHES).map((k) => { const A = HERO_ARCHES[k]; return { key: k, icon: A.icon, name: A.name, text: A.text, nodes: A.nodes.map((n) => HERO_SKILLS[n].icon + " " + HERO_SKILLS[n].name), rules: A.rules }; }),
    stance: h.stance || "",
    stances: Object.keys(HERO_STANCES).map((k) => Object.assign({ key: k }, HERO_STANCES[k])),
    orders: Object.keys(HERO_ORDERS).map((k) => Object.assign({ key: k }, HERO_ORDERS[k])),
    quirk: HERO_QUIRKS[h.quirk] ? Object.assign({ key: h.quirk, reroll: h.quirkRound !== roundNumber() }, HERO_QUIRKS[h.quirk]) : null,
    quirkLevel: HERO_QUIRK_LEVEL,
  };
}

app.post("/api/hero", requireLogin, (req, res) => {
  withColony(req, res, (s, tribe, colony) => {
    const b = req.body || {};
    const now = Date.now();
    const h = heroOf(req.user.id, now);
    if (!h) return "You have no commander";
    if (b.action === "consume") {
      const key=String(b.key||""), item=HERO_CONSUMABLES[key];
      const count=Math.floor(Number((h.consumables||{})[key])||0);
      if(!item || count<1)return "You do not have that consumable";
      if(key === "respec")return "Insight tokens are spent when resetting skills";
      if(key === "recovery") {
        if(h.hurtUntil-now<=60000)return "Recovery kits require more than one minute of fallen recovery remaining";
        h.hurtUntil=now+Math.max(60000,Math.ceil((h.hurtUntil-now)/2));h.hpAt=h.hurtUntil;
      } else {
        if(h.away||h.adv||h.move||h.hurtUntil>now)return "Your commander must be healthy and at home";
        if(item.heal){
          const hp=heroHp(h,now);if(hp>=HERO_HP)return "Your commander already has full health";
          heroSetHp(h,Math.min(HERO_HP,hp+item.heal),now);
        }else{
          if(h.level>=HERO_MAX_LEVEL)return "Your commander is already at maximum level";
          heroAfterFight(req.user.id,h,{xp:Math.max(1,Math.round(heroNeed(h.level)*.1)),scrap:true,at:now});
        }
      }
      h.consumables[key]=count-1;
    } else if (b.action === "arch") {
      const A = HERO_ARCHES[String(b.key || "")];
      if (!A) return "Unknown archetype";
      if (h.level < HERO_ARCH_LEVEL) return "Archetypes open at commander level " + HERO_ARCH_LEVEL;
      if (h.arch) return "Your commander is already a " + HERO_ARCHES[h.arch].name + ". Reset the skills to choose again.";
      heroSettleAll(req.user.id, now);
      heroGearChange(h, now);
      h.arch = String(b.key);
      // points in skills of other archetypes come back as free points
      for (const k of Object.keys(HERO_SKILLS)) if (heroSkillLimit(h, k) === 0) h.pts[k] = 0;
      req.extra = { archPicked: A.name };
    } else if (b.action === "stance") {
      const k = String(b.key || "");
      if (k && !HERO_STANCES[k]) return "Unknown stance";
      h.stance = k;
    } else if (b.action === "quirk") {
      if (!HERO_QUIRKS[h.quirk]) return "Your commander gets a quirk at level " + HERO_QUIRK_LEVEL;
      if (h.quirkRound === roundNumber()) return "The quirk can be rerolled once per round";
      heroSettleAll(req.user.id, now);
      heroGearChange(h, now);
      const others = Object.keys(HERO_QUIRKS).filter((q) => q !== h.quirk);
      h.quirk = others[Math.floor(Math.random() * others.length)];
      h.quirkRound = roundNumber();
      req.extra = { quirk: HERO_QUIRKS[h.quirk].name };
    } else if (b.action === "quirk-seen") {
      h.quirkNew = 0;
    } else if (b.action === "event") {
      const r = advEventPick(req.user.id, h, s, b.pick === "b" ? "b" : "a", now);
      if (r.error) return r.error;
      req.extra = { eventText: r.text };
      return null;
    } else if (b.action === "skill") {
      const sk = HERO_SKILLS[b.key];
      if (!sk) return "Unknown skill";
      if (sk.arch && heroSkillLimit(h, b.key) === 0) return h.arch ? "That skill belongs to another archetype" : "Pick an archetype at level " + HERO_ARCH_LEVEL + " first";
      if (sk.arch) heroSettleAll(req.user.id, now);
      if (heroFree(h) <= 0) return "No skill points left. Win fights to level up!";
      if (h.pts[b.key] >= sk.max) return sk.name + " is already at its best";
      if (b.key === "path") {
        const pm = heroPathMax(h);
        if (!pm) return "The tribe path opens at level " + HERO_PATH_OPEN;
        if (h.pts.path >= pm) return "Gain commander levels to unlock more tribe-path capacity";
      }
      if (b.key === "prod") heroSettle(h.home, now);
      if (b.key === "vit") heroGearChange(h, now); // lock in the health grown so far
      h.pts[b.key]++;
    } else if (b.action === "respec") {
      const spent = Object.keys(HERO_SKILLS).reduce((n, k) => n + (h.pts[k] || 0), 0);
      if (!spent && !h.arch) return "There are no skill points to reset";
      h.consumables=h.consumables||{};
      if((h.consumables.respec||0)<1)return "Resetting skills requires an Insight token, found on adventures";
      h.consumables.respec--;
      if (h.pts.prod) heroSettle(h.home, now);
      heroGearChange(h, now);
      heroSettleAll(req.user.id, now);
      h.pts = Object.assign({}, HERO_PTS0);
      if (h.arch !== undefined || h.level >= HERO_ARCH_LEVEL) h.arch = ""; // choose again
      h.balanceRespec = 1;
    } else if (b.action === "equip") {
      const i = h.bag.findIndex((x) => x.id === b.id && x.kind !== "crate");
      if (i < 0) return "That item is gone";
      heroGearChange(h, now);
      if (heroBonus(h).prodPct || h.bag[i].stats.prod) heroSettle(h.home, now);
      const item = h.bag.splice(i, 1)[0];
      if (h.gear[item.slot]) h.bag.push(h.gear[item.slot]);
      h.gear[item.slot] = item;
    } else if (b.action === "unequip") {
      const slot = HERO_SLOTS.includes(b.slot) ? b.slot : "weapon";
      if (!h.gear[slot]) return "Nothing to take off";
      if (h.bag.length >= HERO_BAG) return "The inventory is full";
      heroGearChange(h, now);
      if (h.gear[slot].stats.prod) heroSettle(h.home, now);
      h.bag.push(h.gear[slot]);
      h.gear[slot] = null;
    } else if (b.action === "upgrade") {
      const item=h.bag.find(x=>x.id===b.id&&HERO_GEAR[x.slot]);
      if(!item)return "Put the item in your inventory before upgrading";
      const rank=item.rank||0;if(rank>=5)return "Maximum upgrade rank reached";
      const material=!!b.material;if(material&&!(h.starMetal>0))return "No Star Metal available";
      const duplicate=b.duplicate&&h.bag.find(x=>x.id!==item.id&&x.slot===item.slot&&x.tier===item.tier&&!(x.rank>0));
      if(b.duplicate&&!duplicate)return "Requires an unupgraded duplicate of the same slot and rarity";
      const price=Math.round(150*item.tier*(rank+1)*(material?0:duplicate?.35:1)),cost=Object.fromEntries(RESOURCES.map(k=>[k,price]));
      if(!canAfford(s,cost))return "Needs "+price+" of each resource in this colony";
      pay(s,cost);if(material)h.starMetal--;if(duplicate)h.bag=h.bag.filter(x=>x!==duplicate);
      item.rank=rank+1;heroFixItem(item);
    } else if (b.action === "scrap") {
      const i = h.bag.findIndex((x) => x.id === b.id && x.kind !== "crate");
      if (i < 0) return "That item is gone";
      const item = h.bag.splice(i, 1)[0];
      heroAfterFight(req.user.id, h, { xp: HERO_SCRAP_XP[item.tier - 1] || 40, scrap: true, at: now });
      return null;
    } else if (b.action === "open") {
      // the chosen amounts go into the colony you are looking at (any of your colonies), as much as fits
      const crate = heroCrate(h);
      if (!crate) return "The stash is empty";
      const want = b.take && typeof b.take === "object" ? b.take : null;
      const asked = {};
      let any = 0;
      for (const r of RESOURCES) {
        asked[r] = want ? Math.max(0, Math.floor(Number(want[r]) || 0)) : Infinity;
        any += asked[r] > 0 ? 1 : 0;
      }
      if (!any) return "Pick an amount to collect";
      const home = { id: colony.id, state: s, tribe: colony.tribe };
      const cap = capacities(home.state);
      let moved = 0;
      for (const r of RESOURCES) {
        const take = Math.max(0, Math.min(asked[r], crate.res[r] || 0, Math.floor(cap[r] - home.state.res[r])));
        home.state.res[r] += take;
        crate.res[r] -= take;
        moved += take;
      }
      if (moved <= 0) return "The storage of " + colony.name + " is full";
      if (lootTotal(crate.res) <= 0) h.bag.splice(h.bag.indexOf(crate), 1);
    } else if (b.action === "move") {
      // Usually the colony being looked at, but a colony can also be named
      // directly (e.g. "restation here" from the send screen, without first
      // switching to look at it).
      let dest = colony;
      if (b.to !== undefined) {
        const toId = Number(b.to);
        if (toId !== colony.id) {
          const row = db.prepare("SELECT id, user_id, x, y FROM colonies WHERE id = ?").get(toId);
          if (!row || row.user_id !== req.user.id) return "Pick one of your own colonies";
          dest = row;
        }
      }
      if (h.home === dest.id) return "Your commander is already here";
      if (h.away || h.move || h.adv) return "Your commander is busy";
      if (h.hurtUntil > now) return "Your commander is still recovering";
      if (h.lockUntil > now) return "Your commander has just settled in. It can move again in " + Math.max(1, Math.ceil((h.lockUntil - now) / 1000)) + " s";
      const from = db.prepare("SELECT x, y FROM colonies WHERE id = ?").get(h.home);
      heroSettle(h.home, now);
      h.move = { to: dest.id, from: h.home, start: now, at: now + (from ? travelMs(distance(from.x, from.y, dest.x, dest.y), heroSpeed(h)) : 0) };
    } else if (b.action === "revive") {
      if (!(h.hurtUntil > now)) return "Your commander isn't fallen";
      const dur = heroReviveMs();
      if (h.hurtUntil - now <= dur) return "It's already due back sooner than that";
      const cost = heroReviveCost(h);
      const home = h.home === colony.id ? { id: colony.id, state: s, tribe: colony.tribe } : loadColony(h.home);
      if (!home) return "Your commander has no colony";
      if (home.state !== s) update(home.state, tribeOf(home.tribe), now);
      if (!canAfford(home.state, cost)) return "Not enough resources in " + (db.prepare("SELECT name FROM colonies WHERE id = ?").get(h.home) || {}).name;
      pay(home.state, cost);
      if (home.state !== s) saveColony(home.id, home.state);
      h.hurtUntil = now + dur;
      h.hp = HERO_HP_BACK;
      h.hpAt = h.hurtUntil;
    } else if (b.action === "rename") {
      const name = String(b.name || "").replace(/\s+/g, " ").trim();
      if (name.length < 2 || name.length > 20) return "The name needs 2 to 20 characters";
      if (/[<>"'`&\\]/.test(name)) return "Please don't use < > \" ' ` & or \\ in the name";
      h.name = name;
    } else return "Unknown action";
    heroSave(req.user.id, h);
    return null;
  });
});

// =====================================================================
//  🕊️ DIPLOMACY between alliances
//  Pacts: a non-aggression pact (NAP) or a confederation (also shares
//  warnings about incoming attacks). Both stop attacks and spying.
//  Ending a pact takes a notice of half a server day.
// =====================================================================
db.exec(`
  CREATE TABLE IF NOT EXISTS alliance_pacts (
    id      INTEGER PRIMARY KEY AUTOINCREMENT,
    a       INTEGER NOT NULL,
    b       INTEGER NOT NULL,
    kind    TEXT NOT NULL,
    state   TEXT NOT NULL,
    at      INTEGER NOT NULL,
    ends_at INTEGER NOT NULL DEFAULT 0
  );
  DROP TABLE IF EXISTS alliance_wars;
  CREATE TABLE IF NOT EXISTS alliance_war_marks (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    a  INTEGER NOT NULL,
    b  INTEGER NOT NULL,
    at INTEGER NOT NULL
  );
`);
const WAR_MAX = 3; // wars at the same time per alliance
const PACT_MAX = 4; // pacts and open offers per alliance
const PACT_NAMES = { nap: "Non-aggression pact", confed: "Confederation" };

function warBetween(a, b) {
  if (!a || !b || a === b) return null;
  return db.prepare("SELECT * FROM alliance_war_marks WHERE (a = ? AND b = ?) OR (a = ? AND b = ?)").get(a, b, b, a) || null;
}
function pactBetween(a, b) {
  if (!a || !b || a === b) return null;
  return db.prepare("SELECT * FROM alliance_pacts WHERE ((a = ? AND b = ?) OR (a = ? AND b = ?)) AND state IN ('on', 'ending')").get(a, b, b, a) || null;
}
// Two players whose alliances have a pact can't attack or spy on each other
function pactBlocks(u1, u2) {
  const x = allianceOf(u1);
  const y = allianceOf(u2);
  if (!x || !y || x.id === y.id) return null;
  const p = pactBetween(x.id, y.id);
  if (!p) return null;
  return "🕊️ Your alliances have a " + (p.kind === "confed" ? "confederation" : "non-aggression pact") + ". No attacks or spying.";
}
// Members of confederated alliances (they see each other's incoming attacks)
function confedMemberIds(aid) {
  const ids = [];
  for (const p of db.prepare("SELECT a, b FROM alliance_pacts WHERE kind = 'confed' AND state IN ('on', 'ending') AND (a = ? OR b = ?)").all(aid, aid)) {
    for (const m of allianceMembers(p.a === aid ? p.b : p.a)) ids.push(m.id);
  }
  return ids;
}
// For the map: what is my alliance to the alliance of that player?
function diploRelations(userId, now) {
  const me = allianceOf(userId);
  const rel = new Map();
  if (!me) return { me: null, rel };
  for (const p of db.prepare("SELECT * FROM alliance_pacts WHERE state IN ('on', 'ending') AND (a = ? OR b = ?)").all(me.id, me.id)) rel.set(p.a === me.id ? p.b : p.a, p.kind);
  for (const w of db.prepare("SELECT * FROM alliance_war_marks WHERE a = ? OR b = ?").all(me.id, me.id)) rel.set(w.a === me.id ? w.b : w.a, "war");
  return { me: me.id, rel };
}
function diploRelOf(R, userId) {
  if (!R.me) return null;
  const a = allianceOf(userId);
  return a ? R.rel.get(a.id) || null : null;
}
// What the troops of a list cost
function troopsValue(troops, tribe) {
  let n = 0;
  for (const k in troops) {
    const u = tribe.units[k];
    if (u) n += troops[k] * (u.cost.wood + u.cost.stone + u.cost.metal + u.cost.food);
  }
  return Math.round(n);
}
function diploPost(aid, text, now) {
  db.prepare("INSERT INTO alliance_posts (alliance_id, user_id, at, body) VALUES (?, 0, ?, ?)").run(aid, now, text);
}
function diploTick() {
  const now = Date.now();
  db.prepare("DELETE FROM alliance_pacts WHERE state = 'ending' AND ends_at <= ?").run(now);
  // offers nobody answered within 3 server days
  db.prepare("DELETE FROM alliance_pacts WHERE state = 'offer' AND at < ?").run(now - 3 * serverDayMs());
  db.prepare("DELETE FROM alliance_pacts WHERE a NOT IN (SELECT id FROM alliances) OR b NOT IN (SELECT id FROM alliances)").run();
  db.prepare("DELETE FROM alliance_war_marks WHERE a NOT IN (SELECT id FROM alliances) OR b NOT IN (SELECT id FROM alliances)").run();
}
setInterval(() => {
  try { diploTick(); } catch (e) { console.error("diplomacy:", e.message); }
}, 30000);

function diploView(aid, now) {
  const tagOf = (id) => db.prepare("SELECT tag, name FROM alliances WHERE id = ?").get(id) || { tag: "?", name: "a former alliance" };
  const pacts = db.prepare("SELECT * FROM alliance_pacts WHERE a = ? OR b = ? ORDER BY id").all(aid, aid).map((p) => {
    const other = p.a === aid ? p.b : p.a;
    const t = tagOf(other);
    return { id: p.id, tag: t.tag, name: t.name, kind: p.kind, kindName: PACT_NAMES[p.kind], state: p.state === "offer" ? (p.a === aid ? "sent" : "got") : p.state, endsAt: p.ends_at };
  });
  const wars = db.prepare("SELECT * FROM alliance_war_marks WHERE a = ? OR b = ? ORDER BY id").all(aid, aid).map((w) => {
    const t = tagOf(w.a === aid ? w.b : w.a);
    return { id: w.id, tag: t.tag, name: t.name, since: w.at, declared: w.a === aid };
  });
  return { pacts, wars, noticeMs: Math.round(serverDayMs() / 2) };
}

app.post("/api/alliance/diplo", requireLogin, (req, res) => {
  allianceAction(req, res, (b) => {
    const me = allianceOf(req.user.id);
    if (!me) return "You're not in an alliance";
    if (me.role !== "leader") return "Only the leader handles diplomacy";
    const now = Date.now();
    const action = String(b.action || "");
    const byTag = () => db.prepare("SELECT id, tag, name FROM alliances WHERE tag = ?").get(String(b.tag || "").trim());
    const mine = "[" + me.tag + "] " + me.name;
    if (action === "pact") {
      const kind = b.kind === "confed" ? "confed" : "nap";
      const o = byTag();
      if (!o) return "No alliance with that tag";
      if (o.id === me.id) return "That's your own alliance";
      if (db.prepare("SELECT 1 FROM alliance_pacts WHERE (a = ? AND b = ?) OR (a = ? AND b = ?)").get(me.id, o.id, o.id, me.id)) return "There already is a pact or an offer with [" + o.tag + "]";
      if (warBetween(me.id, o.id)) return "You are at war with [" + o.tag + "]. End the war first.";
      if (db.prepare("SELECT COUNT(*) AS n FROM alliance_pacts WHERE a = ? OR b = ?").get(me.id, me.id).n >= PACT_MAX) return "At most " + PACT_MAX + " pacts and offers at a time";
      db.prepare("INSERT INTO alliance_pacts (a, b, kind, state, at) VALUES (?, ?, ?, 'offer', ?)").run(me.id, o.id, kind, now);
      diploPost(o.id, "🕊️ " + mine + " offers a " + PACT_NAMES[kind].toLowerCase() + ". Your leader can accept it under Diplomacy.", now);
      return null;
    }
    if (action === "accept" || action === "decline" || action === "cancel") {
      const p = db.prepare("SELECT * FROM alliance_pacts WHERE id = ? AND (a = ? OR b = ?)").get(Number(b.id), me.id, me.id);
      if (!p) return "That pact is gone";
      const other = p.a === me.id ? p.b : p.a;
      const name = PACT_NAMES[p.kind].toLowerCase();
      if (action === "accept") {
        if (p.state !== "offer" || p.b !== me.id) return "Nothing to accept";
        db.prepare("UPDATE alliance_pacts SET state = 'on', at = ? WHERE id = ?").run(now, p.id);
        diploPost(other, "🕊️ " + mine + " accepted your " + name + ".", now);
        diploPost(me.id, "🕊️ The " + name + " with [" + (db.prepare("SELECT tag FROM alliances WHERE id = ?").get(other) || {}).tag + "] is now in force.", now);
      } else if (p.state === "offer") {
        db.prepare("DELETE FROM alliance_pacts WHERE id = ?").run(p.id);
        diploPost(other, "🕊️ " + mine + (p.a === me.id ? " withdrew its offer of a " : " declined your ") + name + ".", now);
      } else if (p.state === "on") {
        const notice = Math.round(serverDayMs() / 2);
        db.prepare("UPDATE alliance_pacts SET state = 'ending', ends_at = ? WHERE id = ?").run(now + notice, p.id);
        diploPost(other, "🕊️ " + mine + " ended your " + name + ". It stays in force for " + Math.round(notice / 3600000) + " more hours.", now);
      } else return "That pact is already ending";
      return null;
    }
    if (action === "war") {
      const o = byTag();
      if (!o) return "No alliance with that tag";
      if (o.id === me.id) return "That's your own alliance";
      if (pactBetween(me.id, o.id)) return "You have a pact with [" + o.tag + "]. End it first (it takes half a server day).";
      if (warBetween(me.id, o.id)) return "You are already at war with [" + o.tag + "]";
      if (db.prepare("SELECT COUNT(*) AS n FROM alliance_war_marks WHERE a = ? OR b = ?").get(me.id, me.id).n >= WAR_MAX) return "At most " + WAR_MAX + " wars at the same time";
      db.prepare("INSERT INTO alliance_war_marks (a, b, at) VALUES (?, ?, ?)").run(me.id, o.id, now);
      diploPost(o.id, "⚔️ " + mine + " declared war on you. Their members are marked red on your map.", now);
      diploPost(me.id, "⚔️ War on [" + o.tag + "] is declared. Their members are marked red on your map.", now);
      return null;
    }
    if (action === "peace") {
      const w = db.prepare("SELECT * FROM alliance_war_marks WHERE id = ? AND (a = ? OR b = ?)").get(Number(b.id), me.id, me.id);
      if (!w) return "That war is over";
      db.prepare("DELETE FROM alliance_war_marks WHERE id = ?").run(w.id);
      const other = w.a === me.id ? w.b : w.a;
      diploPost(other, "🕊️ " + mine + " ended the war.", now);
      diploPost(me.id, "🕊️ The war with [" + (db.prepare("SELECT tag FROM alliances WHERE id = ?").get(other) || {}).tag + "] is over.", now);
      return null;
    }
    return "Unknown action";
  });
});

// =====================================================================
//  🏛️ HALL OF FAME - when a round ends (the server starts over) the
//  winners are written down for good, and the best players get badges.
//  Those champion badges stay with the player in every round that follows.
//  Badges for weekly ranks and achievements only last for one round.
// =====================================================================
db.exec(`
  CREATE TABLE IF NOT EXISTS hall_of_fame (
    id         INTEGER PRIMARY KEY AUTOINCREMENT,
    round      INTEGER NOT NULL,
    server     TEXT NOT NULL,
    started_at INTEGER NOT NULL,
    ended_at   INTEGER NOT NULL,
    data       TEXT NOT NULL
  );
`);
function roundNumber() {
  return Number(settingOf("round_no", "1")) || 1;
}
// Winners of the server goals of this round (set when they happen)
function rememberRoundWinner(kind, key, name, at) {
  const names = teamMembers(key).map((id) => usernameOf(id));
  setSetting("round_" + kind, JSON.stringify({ name, players: names.slice(0, 20), at }));
}
function recordRound(now) {
  const players = db.prepare("SELECT id, username FROM users WHERE bot = 0").all();
  const ranked = players.map((u) => ({ id: u.id, name: u.username, points: playerPoints(u.id) })).filter((p) => p.points > 0).sort((a, b) => b.points - a.points);
  if (!ranked.length) return null;
  const round = roundNumber();
  const info = (p) => {
    const c = db.prepare("SELECT tribe FROM colonies WHERE user_id = ? ORDER BY id LIMIT 1").get(p.id);
    const a = allianceOf(p.id);
    return { name: p.name, points: p.points, tribe: c ? tribeOf(c.tribe).icon : "", tag: a ? a.tag : null };
  };
  const best = (col) => {
    const r = db.prepare("SELECT stats." + col + " AS n, users.username AS name FROM stats JOIN users ON users.id = stats.user_id WHERE users.bot = 0 AND stats." + col + " > 0 ORDER BY stats." + col + " DESC LIMIT 1").get();
    return r ? { name: r.name, n: r.n, id: (db.prepare("SELECT id FROM users WHERE username = ?").get(r.name) || {}).id } : null;
  };
  const parse = (k) => { try { return JSON.parse(settingOf(k, "null")); } catch (e) { return null; } };
  const data = {
    server: thisServerName(),
    speed: PRODUCTION_SPEED,
    players: players.length,
    aurora: parse("round_aurora"),
    relic: parse("round_relic"),
    top: ranked.slice(0, 5).map(info),
    alliances: allianceRanking().slice(0, 3).map((a) => ({ tag: a.tag, name: a.name, points: a.points, members: a.members })),
    attacker: best("atk_kills"),
    defender: best("def_kills"),
    raider: best("loot"),
    hunter: best("npc_kills"),
  };
  db.prepare("INSERT INTO hall_of_fame (round, server, started_at, ended_at, data) VALUES (?, ?, ?, ?, ?)").run(round, THIS_SERVER, serverStartAt(), now, JSON.stringify(data));
  // badges for the champions of the round (they stay for good)
  const medals = ["🥇", "🥈", "🥉"];
  ranked.slice(0, 3).forEach((p, i) => giveBadge(p.id, "r" + round + "p" + (i + 1), medals[i], "#" + (i + 1) + " · " + thisServerName() + " x" + PRODUCTION_SPEED + " · " + new Date(now).toISOString().slice(0, 10), now));
  if (data.attacker && data.attacker.id) giveBadge(data.attacker.id, "r" + round + "atk", "⚔️", "Top attacker · " + thisServerName() + " x" + PRODUCTION_SPEED + " · " + new Date(now).toISOString().slice(0, 10), now);
  if (data.defender && data.defender.id) giveBadge(data.defender.id, "r" + round + "def", "🛡️", "Top defender · " + thisServerName() + " x" + PRODUCTION_SPEED + " · " + new Date(now).toISOString().slice(0, 10), now);
  for (const k of ["attacker", "defender", "raider", "hunter"]) if (data[k]) delete data[k].id;
  db.prepare("UPDATE hall_of_fame SET data = ? WHERE id = (SELECT MAX(id) FROM hall_of_fame)").run(JSON.stringify(data));
  setSetting("round_no", String(round + 1));
  db.prepare("DELETE FROM settings WHERE key IN ('round_aurora', 'round_relic')").run();
  // pacts and wars belong to the round
  db.prepare("DELETE FROM alliance_pacts").run();
  db.prepare("DELETE FROM alliance_war_marks").run();
  return round;
}
app.get("/api/hall", (req, res) => {
  const rows = db.prepare("SELECT * FROM hall_of_fame ORDER BY id DESC LIMIT 30").all();
  res.json({
    server: thisServerName(),
    speed: PRODUCTION_SPEED,
    round: roundNumber(),
    roundStart: serverStartAt(),
    rounds: rows.map((r) => Object.assign({ round: r.round, startedAt: r.started_at, endedAt: r.ended_at }, JSON.parse(r.data))),
  });
});

// =====================================================================
//  🧭 THE FIRST DAY - a short path for new players. A few steps that
//  teach the basics, then a choice: build in peace or raid. Both kits
//  are worth about the same.
// =====================================================================
addColumn("users", "firstday", "TEXT NOT NULL DEFAULT ''");
const FIRST_DAY_KIT = 2000; // resources, or troops worth that much
const FIRST_DAY_STEPS = [
  { key: "field", icon: "🌾", text: "Upgrade a resource field", why: "Fields produce all the time, even while you're away.", go: "field::1",
    done: (s) => s.fields.some((f) => f.level >= 1) },
  { key: "store", icon: "🛢️", text: "Build a {warehouse}", why: "Storage limits what you can keep. When it's full, production goes to waste.", go: "b:warehouse",
    done: (s) => levelOf(s, "warehouse") >= 1 },
  { key: "troops", icon: "⚔️", text: "Train your first troops", why: "Troops defend your colony and raid monster camps for loot. The {barracks} needs {hq} level 3.", go: "b:barracks",
    done: (s) => countUnits(s.troops) + countUnits(s.away) > 0 },
  { key: "spy", icon: "🔍", text: "Spy on a monster camp", why: "Spies show what waits at a target before you risk an attack.", go: "spy",
    done: (s) => !!(s.qstats && s.qstats.spied) },
];
function firstDayState(userId) {
  const row = db.prepare("SELECT firstday, created_at FROM users WHERE id = ?").get(userId);
  if (!row) return null;
  let f = {};
  try { f = row.firstday ? JSON.parse(row.firstday) : {}; } catch (e) {}
  return { f, created: row.created_at };
}
// The starter troops for raiders: the cheapest fighter that needs no research
function firstDayUnit(tribe) {
  let best = null;
  for (const k in tribe.units) {
    const u = tribe.units[k];
    if (u.lab || isSettler(u) || isScout(u) || isSiege(u) || u.atk <= u.defG || u.building !== "barracks") continue;
    const c = u.cost.wood + u.cost.stone + u.cost.metal + u.cost.food;
    if (!best || c < best.c) best = { key: k, u, c };
  }
  return best ? { key: best.key, icon: best.u.icon, name: best.u.name, count: Math.max(1, Math.round(FIRST_DAY_KIT / best.c)) } : null;
}
function firstDayView(userId, colony, now) {
  const st = firstDayState(userId);
  if (!st || st.f.path || st.f.hidden || st.f.onb || onbActive(userId, st)) return null; // the landing replaced it
  // only for new players (or the ones who already started it)
  if (!st.f.seen && now - st.created > 7 * 86400000) return null;
  const tribe = tribeOf(colony.tribe);
  const names = tribe.names;
  const fill = (t) => t.replace(/\{(\w+)\}/g, (m, k) => (names[k] ? names[k][0] : k));
  const s = colony.state;
  const steps = FIRST_DAY_STEPS.map((x) => ({ key: x.key, icon: x.icon, text: fill(x.text), why: fill(x.why), go: x.go, done: !!x.done(s) }));
  const unit = firstDayUnit(tribe);
  const per = Math.round(FIRST_DAY_KIT / 4);
  return {
    steps,
    ready: steps.every((x) => x.done),
    builder: { wood: per, stone: per, metal: per, food: per },
    raider: unit,
    protection: protectionOf(userId, now),
  };
}
app.post("/api/firstday", requireLogin, (req, res) => {
  withColony(req, res, (s, tribe, colony) => {
    const b = req.body || {};
    const st = firstDayState(req.user.id);
    if (!st || st.f.path) return "Already done";
    if (b.choice === "hide") st.f.hidden = Date.now();
    else {
      const v = firstDayView(req.user.id, colony, Date.now());
      if (!v) return "Already done";
      if (!v.ready) return "Finish the steps first";
      if (b.choice === "builder") refund(s, v.builder);
      else if (b.choice === "raider" && v.raider) s.troops[v.raider.key] = (s.troops[v.raider.key] || 0) + v.raider.count;
      else return "Pick a path";
      st.f.path = b.choice;
      st.f.at = Date.now();
    }
    db.prepare("UPDATE users SET firstday = ? WHERE id = ?").run(JSON.stringify(st.f), req.user.id);
    return null;
  });
});

// =====================================================================
//  📊 BATTLE LOG - every fight is written down (60 days), so the owner
//  can see win rates per tribe and unit and tune the balance.
// =====================================================================
db.exec(`
  CREATE TABLE IF NOT EXISTS battle_log (
    id        INTEGER PRIMARY KEY AUTOINCREMENT,
    at        INTEGER NOT NULL,
    kind      TEXT NOT NULL,
    mission   TEXT NOT NULL,
    atk_tribe TEXT NOT NULL,
    def_tribe TEXT NOT NULL,
    bot       INTEGER NOT NULL DEFAULT 0,
    win       INTEGER NOT NULL,
    atk       TEXT NOT NULL,
    def       TEXT NOT NULL,
    a         INTEGER NOT NULL,
    d         INTEGER NOT NULL,
    hero      INTEGER NOT NULL DEFAULT 0
  );
  CREATE INDEX IF NOT EXISTS battle_log_at ON battle_log (at);
`);
function packLosses(troops, lost) {
  const out = {};
  for (const k in troops) if (troops[k] > 0) out[k] = [troops[k], (lost && lost[k]) || 0];
  return JSON.stringify(out);
}
function logBattle(o) {
  try {
    db.prepare("INSERT INTO battle_log (at, kind, mission, atk_tribe, def_tribe, bot, win, atk, def, a, d, hero) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)").run(
      o.at, o.kind, o.mission, o.atkTribe, o.defTribe, o.bot ? 1 : 0, o.win ? 1 : 0, packLosses(o.atk, o.atkLost), packLosses(o.def, o.defLost), Math.round(o.A), Math.round(o.D), o.hero ? 1 : 0
    );
  } catch (e) {
    console.error("battle log:", e.message);
  }
}
setInterval(() => {
  db.prepare("DELETE FROM battle_log WHERE at < ?").run(Date.now() - 60 * 86400000);
}, 3600000);

app.get("/api/admin/balance", requireOwner, (req, res) => {
  const days = Math.max(1, Math.min(60, Number(req.query.days) || 7));
  const bots = req.query.bots === "1";
  const now = Date.now();
  const rows = db.prepare("SELECT * FROM battle_log WHERE at > ?" + (bots ? "" : " AND bot = 0")).all(now - days * 86400000);
  const tribes = Object.keys(TRIBES);
  const pct = (a, b) => (b ? Math.round((a / b) * 100) : null);
  // tribe against tribe (players only)
  const match = {};
  for (const a of tribes) {
    match[a] = {};
    for (const d of tribes) match[a][d] = { n: 0, w: 0 };
  }
  const tribeSum = {};
  for (const t of tribes) tribeSum[t] = { pvp: 0, pvpWin: 0, camp: 0, campWin: 0, sent: 0, lost: 0, defN: 0, defWin: 0 };
  const unitSum = {};
  const unitRow = (tribe, k) => {
    const key = tribe + ":" + k;
    if (!unitSum[key]) unitSum[key] = { tribe, key: k, n: 0, win: 0, sent: 0, lost: 0, defN: 0, had: 0, defLost: 0 };
    return unitSum[key];
  };
  let pvp = 0;
  let camp = 0;
  let hero = 0;
  for (const r of rows) {
    const atk = JSON.parse(r.atk);
    const def = JSON.parse(r.def);
    if (r.hero) hero++;
    const T = tribeSum[r.atk_tribe];
    if (r.kind === "pvp") {
      pvp++;
      if (match[r.atk_tribe] && match[r.atk_tribe][r.def_tribe]) {
        match[r.atk_tribe][r.def_tribe].n++;
        match[r.atk_tribe][r.def_tribe].w += r.win;
      }
      if (T) { T.pvp++; T.pvpWin += r.win; }
      const D = tribeSum[r.def_tribe];
      if (D) { D.defN++; D.defWin += 1 - r.win; }
      for (const k in def) {
        const u = unitRow(r.def_tribe, k);
        u.defN++;
        u.had += def[k][0];
        u.defLost += def[k][1];
      }
    } else {
      camp++;
      if (T) { T.camp++; T.campWin += r.win; }
    }
    for (const k in atk) {
      const u = unitRow(r.atk_tribe, k);
      u.n++;
      u.win += r.win;
      u.sent += atk[k][0];
      u.lost += atk[k][1];
      if (T) { T.sent += atk[k][0]; T.lost += atk[k][1]; }
    }
  }
  const units = Object.values(unitSum)
    .filter((u) => TRIBES[u.tribe] && TRIBES[u.tribe].units[u.key])
    .map((u) => {
      const def = TRIBES[u.tribe].units[u.key];
      return { tribe: TRIBES[u.tribe].icon, icon: def.icon, name: def.name, battles: u.n, winRate: pct(u.win, u.n), sent: u.sent, lossRate: pct(u.lost, u.sent), defBattles: u.defN, defLossRate: pct(u.defLost, u.had) };
    })
    .sort((a, b) => b.battles + b.defBattles - (a.battles + a.defBattles));
  res.json({
    days,
    bots,
    total: rows.length,
    pvp,
    camp,
    hero: pct(hero, rows.length),
    tribes: tribes.map((t) => ({ key: t, icon: TRIBES[t].icon, name: TRIBES[t].name, pvp: tribeSum[t].pvp, pvpWin: pct(tribeSum[t].pvpWin, tribeSum[t].pvp), def: tribeSum[t].defN, defWin: pct(tribeSum[t].defWin, tribeSum[t].defN), camp: tribeSum[t].camp, campWin: pct(tribeSum[t].campWin, tribeSum[t].camp), lossRate: pct(tribeSum[t].lost, tribeSum[t].sent) })),
    match: tribes.map((a) => ({ icon: TRIBES[a].icon, name: TRIBES[a].name, vs: tribes.map((d) => ({ icon: TRIBES[d].icon, n: match[a][d].n, win: pct(match[a][d].w, match[a][d].n) })) })),
    units,
  });
});

// =====================================================================
//  🚩 REPORTS & APPEALS
//  Players can report another player (cheating, abuse, a bad name...).
//  A blocked player, or one whose accounts are linked by device, can
//  write an appeal. The owner answers both on the admin page.
// =====================================================================
db.exec(`
  CREATE TABLE IF NOT EXISTS player_reports (
    id        INTEGER PRIMARY KEY AUTOINCREMENT,
    at        INTEGER NOT NULL,
    by_id     INTEGER NOT NULL,
    target_id INTEGER NOT NULL,
    reason    TEXT NOT NULL,
    text      TEXT NOT NULL DEFAULT '',
    status    TEXT NOT NULL DEFAULT 'open',
    outcome   TEXT NOT NULL DEFAULT '',
    closed_at INTEGER NOT NULL DEFAULT 0
  );
  CREATE TABLE IF NOT EXISTS appeals (
    id        INTEGER PRIMARY KEY AUTOINCREMENT,
    at        INTEGER NOT NULL,
    user_id   INTEGER NOT NULL,
    kind      TEXT NOT NULL,
    text      TEXT NOT NULL,
    status    TEXT NOT NULL DEFAULT 'open',
    answer    TEXT NOT NULL DEFAULT '',
    closed_at INTEGER NOT NULL DEFAULT 0
  );
`);
const REPORT_REASONS = {
  multi: "More than one account / cheating",
  abuse: "Insults or harassment",
  name: "Offensive name",
  bug: "Using a bug",
  other: "Something else",
};
const REPORTS_PER_DAY = 5;
function cleanText(t, max) {
  return String(t || "").replace(/\s+/g, " ").trim().slice(0, max);
}
// a message from the owner who handled it
function ownerMail(fromId, toId, subject, body) {
  db.prepare("INSERT INTO messages (from_id, to_id, subject, body, created_at) VALUES (?, ?, ?, ?, ?)").run(fromId, toId, subject, body, Date.now());
}

app.post("/api/report-player", requireLogin, (req, res) => {
  const b = req.body || {};
  const target = db.prepare("SELECT id, username, bot FROM users WHERE username = ?").get(String(b.name || "").trim());
  if (!target || target.bot) return res.status(400).json({ error: "No such player" });
  if (target.id === req.user.id) return res.status(400).json({ error: "You can't report yourself" });
  if (!REPORT_REASONS[b.reason]) return res.status(400).json({ error: "Pick a reason" });
  const now = Date.now();
  if (db.prepare("SELECT 1 FROM player_reports WHERE by_id = ? AND target_id = ? AND status = 'open'").get(req.user.id, target.id)) return res.status(400).json({ error: "You already reported " + target.username + ". The owner will look at it." });
  if (db.prepare("SELECT COUNT(*) AS n FROM player_reports WHERE by_id = ? AND at > ?").get(req.user.id, now - 86400000).n >= REPORTS_PER_DAY) return res.status(429).json({ error: "That's enough reports for today" });
  db.prepare("INSERT INTO player_reports (at, by_id, target_id, reason, text) VALUES (?, ?, ?, ?, ?)").run(now, req.user.id, target.id, b.reason, cleanText(b.text, 500));
  res.json({ ok: true, message: "Thanks! The server owner will look at it." });
});

// Accounts that share a device with another account (and aren't cleared)
function linkedTo(userId) {
  const u = db.prepare("SELECT multi_ok FROM users WHERE id = ?").get(userId);
  if (!u || u.multi_ok) return [];
  return db.prepare("SELECT DISTINCT y.user_id AS id FROM device_links x JOIN device_links y ON x.device = y.device WHERE x.user_id = ? AND y.user_id != ?").all(userId, userId)
    .map((r) => db.prepare("SELECT username, multi_ok, bot FROM users WHERE id = ?").get(r.id))
    .filter((r) => r && !r.multi_ok && !r.bot)
    .map((r) => r.username);
}
function appealOf(userId, kind) {
  const a = db.prepare("SELECT * FROM appeals WHERE user_id = ? AND kind = ? ORDER BY id DESC LIMIT 1").get(userId, kind);
  return a ? { status: a.status, answer: a.answer, at: a.at } : null;
}
function linkView(userId) {
  const names = linkedTo(userId);
  if (!names.length) return null;
  return { names, appeal: appealOf(userId, "link") };
}
function addAppeal(userId, kind, text) {
  const t = cleanText(text, 800);
  if (t.length < 10) return "Please explain in at least 10 characters";
  if (db.prepare("SELECT 1 FROM appeals WHERE user_id = ? AND kind = ? AND status = 'open'").get(userId, kind)) return "Your appeal is waiting for an answer";
  if (db.prepare("SELECT COUNT(*) AS n FROM appeals WHERE user_id = ? AND at > ?").get(userId, Date.now() - 86400000).n >= 2) return "Please wait a day before writing again";
  db.prepare("INSERT INTO appeals (at, user_id, kind, text) VALUES (?, ?, ?, ?)").run(Date.now(), userId, kind, t);
  return null;
}
// linked accounts: from inside the game
app.post("/api/appeal", requireLogin, (req, res) => {
  if (!linkedTo(req.user.id).length) return res.status(400).json({ error: "Your account isn't linked to another one" });
  const no = addAppeal(req.user.id, "link", (req.body || {}).text);
  if (no) return res.status(400).json({ error: no });
  res.json({ ok: true, message: "Sent. The server owner will answer here." });
});
// blocked accounts: from the login screen (name + password prove it's you)
app.post("/api/appeal-blocked", (req, res) => {
  const b = req.body || {};
  if (blocked("appeal:" + req.ip, LOGIN_TRIES)) return res.status(429).json({ error: "Too many tries. Try again later." });
  // from the hand-over link of the main account (or, for old accounts, name + password)
  const o = b.t ? hopRead(b.t, true) : null;
  const user = o ? db.prepare("SELECT * FROM users WHERE hub = ?").get(o.u) : db.prepare("SELECT * FROM users WHERE username = ?").get(String(b.username || "").trim());
  if (!user || (!o && !passwordMatches(String(b.password || ""), user.salt, user.pass_hash))) return res.status(400).json({ error: b.t ? "This link is too old. Pick the server again on the main server." : "Wrong name or password" });
  if (!user.banned) return res.status(400).json({ error: "This account isn't blocked. Just log in!" });
  if (b.text) {
    const no = addAppeal(user.id, "ban", b.text);
    if (no) return res.status(400).json({ error: no });
  }
  res.json({ ok: true, appeal: appealOf(user.id, "ban") });
});

app.get("/api/admin/moderation", requireOwner, (req, res) => {
  const name = (id) => usernameOf(id);
  const reports = db.prepare("SELECT * FROM player_reports WHERE status = 'open' OR closed_at > ? ORDER BY status = 'open' DESC, id DESC LIMIT 60").all(Date.now() - 14 * 86400000).map((r) => ({
    id: r.id, at: r.at, by: name(r.by_id), target: name(r.target_id), targetId: r.target_id,
    reason: REPORT_REASONS[r.reason] || r.reason, text: r.text, status: r.status, outcome: r.outcome,
    count: db.prepare("SELECT COUNT(*) AS n FROM player_reports WHERE target_id = ?").get(r.target_id).n,
  }));
  const appeals = db.prepare("SELECT * FROM appeals WHERE status = 'open' OR closed_at > ? ORDER BY status = 'open' DESC, id DESC LIMIT 60").all(Date.now() - 14 * 86400000).map((a) => ({
    id: a.id, at: a.at, name: name(a.user_id), kind: a.kind, text: a.text, status: a.status, answer: a.answer,
    linked: a.kind === "link" ? linkedTo(a.user_id) : [],
  }));
  res.json({ now: Date.now(), reports, appeals, open: reports.filter((r) => r.status === "open").length + appeals.filter((a) => a.status === "open").length });
});
// body: { report, action: dismiss|warn|block, note } or { appeal, action: accept|deny, answer }
app.post("/api/admin/moderation", requireOwner, (req, res) => {
  const b = req.body || {};
  const now = Date.now();
  const note = cleanText(b.note || b.answer, 500);
  if (b.report) {
    const r = db.prepare("SELECT * FROM player_reports WHERE id = ? AND status = 'open'").get(Number(b.report));
    if (!r) return res.status(400).json({ error: "That report is already handled" });
    const target = usernameOf(r.target_id);
    let outcome;
    if (b.action === "warn") {
      ownerMail(req.user.id, r.target_id, "⚠️ A warning from the server owner", note || "Please play fair and be kind to the other players. Next time your account may be blocked.");
      outcome = "warned";
    } else if (b.action === "block") {
      db.prepare("UPDATE users SET banned = 1 WHERE id = ?").run(r.target_id);
      db.prepare("DELETE FROM sessions WHERE user_id = ?").run(r.target_id);
      outcome = "blocked";
    } else outcome = "dismissed";
    // every open report about that player is handled with it
    const all = db.prepare("SELECT id, by_id FROM player_reports WHERE target_id = ? AND status = 'open'").all(r.target_id);
    for (const x of all) {
      db.prepare("UPDATE player_reports SET status = 'done', outcome = ?, closed_at = ? WHERE id = ?").run(outcome + (note ? ": " + note : ""), now, x.id);
      ownerMail(req.user.id, x.by_id, "🚩 Your report about " + target, "Thanks for your report. The server owner looked into it" + (outcome === "dismissed" ? " and found nothing to act on." : " and took action."));
    }
    adminLog(req, "Report about " + target + ": " + outcome);
    return res.json({ ok: true, message: target + ": " + outcome });
  }
  if (b.appeal) {
    const a = db.prepare("SELECT * FROM appeals WHERE id = ? AND status = 'open'").get(Number(b.appeal));
    if (!a) return res.status(400).json({ error: "That appeal is already handled" });
    const name = usernameOf(a.user_id);
    const ok = b.action === "accept";
    if (ok && a.kind === "ban") db.prepare("UPDATE users SET banned = 0 WHERE id = ?").run(a.user_id);
    if (ok && a.kind === "link") db.prepare("UPDATE users SET multi_ok = 1 WHERE id = ?").run(a.user_id);
    db.prepare("UPDATE appeals SET status = ?, answer = ?, closed_at = ? WHERE id = ?").run(ok ? "accepted" : "denied", note, now, a.id);
    adminLog(req, "Appeal of " + name + " (" + a.kind + "): " + (ok ? "accepted" : "denied"));
    return res.json({ ok: true, message: name + ": appeal " + (ok ? "accepted" : "denied") });
  }
  res.status(400).json({ error: "Nothing to do" });
});

// =====================================================================
//  ⚡ FASTER CONSTRUCTION - ways to shorten a build job. None of them
//  can be bought outright:
//   🕐 Overtime      once per server day and colony: −20% of one job (max 60 min)
//   🏘️ Helping hands every other colony of yours, once per server day: −10%
//   🤝 Alliance help you pick one job, every member who helps: −4% (max 20%)
//  The free ones together skip at most half of a job.
//  🎖️ Commander's crew: where the commander is stationed it builds one
//  small job (up to level 5) next to the normal queue.
//  (Minutes are shorter on faster servers.)
// =====================================================================
db.exec(`
  CREATE TABLE IF NOT EXISTS build_asks (
    colony_id INTEGER PRIMARY KEY,
    user_id   INTEGER NOT NULL,
    job_id    TEXT NOT NULL,
    helpers   TEXT NOT NULL DEFAULT '[]',
    at        INTEGER NOT NULL
  );
  CREATE TABLE IF NOT EXISTS build_help_log (
    user_id   INTEGER NOT NULL,
    owner_id  INTEGER NOT NULL,
    day       INTEGER NOT NULL,
    n         INTEGER NOT NULL DEFAULT 0,
    PRIMARY KEY (user_id, owner_id, day)
  );
  CREATE TABLE IF NOT EXISTS crew_busy (
    user_id   INTEGER PRIMARY KEY,
    colony_id INTEGER NOT NULL,
    finish_at INTEGER NOT NULL
  );
  CREATE TABLE IF NOT EXISTS build_hands (
    colony_id INTEGER PRIMARY KEY,
    day       INTEGER NOT NULL
  );
`);

let jobSeq = 0;
function newJobId() {
  jobSeq = (jobSeq + 1) % 46656;
  return Date.now().toString(36) + jobSeq.toString(36) + Math.floor(Math.random() * 1296).toString(36);
}
// every build job of a colony: the queue plus the crew's job
function jobsOf(s) {
  return s.crewJob ? s.queue.concat([s.crewJob]) : s.queue;
}
function crewOn(s, kind, slot) {
  return !!(s.crewJob && s.crewJob.kind === kind && s.crewJob.slot === slot);
}
function findJob(s, id) {
  return jobsOf(s).find((q) => q.id === id) || null;
}
// ---------- cancelling a job: how much comes back ----------
function incomingHostile(colonyId) {
  return !!db.prepare("SELECT 1 FROM movements WHERE target_kind = 'colony' AND target_id = ? AND phase = 'out' AND depart_at <= ? AND mission IN ('attack', 'raid') AND attacker_id != ?").get(colonyId, Date.now(), colonyId);
}
// 100 when it is early and quiet, else 75 (the same for every kind of job and training order)
function cancelPctAt(s, at, now) {
  const early = now - (at || 0) <= BUILD_CANCEL_MS;
  return early && !incomingHostile(s._cid) ? 100 : Math.round(BUILD_CANCEL_REFUND * 100);
}
function cancelPct(s, job, now) {
  return cancelPctAt(s, job.at, now);
}
// what the client shows next to a cancel button
function cancelView(s, at, now) {
  return { refundPct: cancelPctAt(s, at, now), refundMs: Math.max(0, BUILD_CANCEL_MS - (now - (at || 0))) };
}
// give back a share of the cost; returns the share in percent
function refundAt(s, cost, at, now) {
  const pct = cancelPctAt(s, at, now);
  const back = {};
  for (const r of RESOURCES) back[r] = Math.floor(((cost && cost[r]) || 0) * pct / 100);
  refund(s, back);
  return pct;
}
function refundJob(s, job, now) {
  return refundAt(s, job.cost, job.at, now);
}
function jobLeft(job, now) {
  return job.finishAt ? Math.max(0, job.finishAt - now) : job.duration;
}
// the job's full build time, before anything was cut
function jobBase(job) {
  return job.full || job.duration;
}
// how much free help this job can still take
function freeRoom(job, now) {
  return Math.max(0, Math.min(Math.floor(jobBase(job) * BOOST_FREE_MAX) - (job.cut || 0), jobLeft(job, now)));
}
function cutJob(job, ms, now) {
  if (!job.full) job.full = job.duration;
  if (job.finishAt) job.finishAt = Math.max(now, job.finishAt - ms);
  else job.duration = Math.max(0, job.duration - ms);
  job.cut = (job.cut || 0) + ms;
}
function serverDayNo(now) {
  const an = clockAnchor();
  return Math.floor(an.d + (now - an.t) / serverDayMs());
}
function nextDayAt(now) {
  const an = clockAnchor();
  return Math.round(an.t + (serverDayNo(now) + 1 - an.d) * serverDayMs());
}
function overtimeMs(job, now) {
  return Math.min(Math.round(jobBase(job) * OVERTIME_CUT), Math.round((OVERTIME_MAX_MIN * 60000) / BUILD_SPEED), freeRoom(job, now));
}
// 🏘️ helping hands: a colony that lends a hand gives up one of its own
// build queue slots until the job it helped with is finished (or cancelled)
addColumn("build_hands", "for_colony", "INTEGER");
addColumn("build_hands", "job", "TEXT");
const handsCache = new Map();
function handsLend(colonyId, now) {
  const hit = handsCache.get(colonyId);
  if (hit && hit.until > now) return hit.v;
  let v = null;
  const r = db.prepare("SELECT for_colony, job FROM build_hands WHERE colony_id = ?").get(colonyId);
  if (r && r.job) {
    const row = db.prepare("SELECT name, state FROM colonies WHERE id = ?").get(r.for_colony);
    let j = null;
    if (row) {
      try {
        const st = JSON.parse(row.state);
        j = (st.queue || []).concat(st.crewJob ? [st.crewJob] : []).find((q) => q.id === r.job) || null;
      } catch (e) {}
    }
    if (j && !(j.finishAt && j.finishAt <= now)) v = { colonyId: r.for_colony, colony: row.name, finishAt: j.finishAt || 0 };
  }
  if (r && !v) db.prepare("DELETE FROM build_hands WHERE colony_id = ?").run(colonyId);
  handsCache.set(colonyId, { v, until: now + 2000 });
  return v;
}
// how many jobs this colony's build queue takes right now
function queueCap(s, now) {
  return QUEUE_LIMIT - (s._cid && handsLend(s._cid, now || Date.now()) ? 1 : 0);
}
// my other colonies that can lend a hand: not lending already, and a free queue slot
function handsReady(userId, colonyId, now) {
  return colonyIdsOf(userId).filter((id) => {
    if (id === colonyId || handsLend(id, now)) return false;
    const row = db.prepare("SELECT state FROM colonies WHERE id = ?").get(id);
    let busy = 0;
    try { busy = (JSON.parse(row.state).queue || []).filter((q) => !q.finishAt || q.finishAt > now).length; } catch (e) {}
    return busy < QUEUE_LIMIT;
  });
}
// how many more times I can help this ally today
function allyHelpsLeft(userId, ownerId, now) {
  const r = db.prepare("SELECT n FROM build_help_log WHERE user_id = ? AND owner_id = ? AND day = ?").get(userId, ownerId, serverDayNo(now));
  return Math.max(0, ALLY_HELPS_PER_MEMBER - (r ? r.n : 0));
}
function askDone(colonyId) {
  if (colonyId) db.prepare("DELETE FROM build_asks WHERE colony_id = ?").run(colonyId);
}

// What the client needs for one job
function jobBoostView(s, q, now) {
  const base = jobBase(q);
  const left = jobLeft(q, now);
  return {
    id: q.id,
    ...cancelView(s, q.at, now),
    fullMs: base,
    cutMs: q.cut || 0,
    freeLeftMs: freeRoom(q, now),
    freeMaxMs: Math.floor(base * BOOST_FREE_MAX),
    overtimeMs: overtimeMs(q, now),
    handsMs: Math.min(Math.round(base * HANDS_CUT), freeRoom(q, now)),
    allyMs: q.ally || 0,
    allyMaxMs: Math.round(base * ALLY_HELP_MAX),
    helpers: (q.helpers || []).length,
    asked: s.askJob === q.id,
    freeNow: !!q.finishAt && left <= freeFinishMs(),
  };
}
function boostView(s, userId, colonyId, now) {
  const mine = colonyIdsOf(userId).length;
  return {
    overtime: s.overtimeDay !== serverDayNo(now),
    nextDay: nextDayAt(now),
    hands: (function () {
      const ready = handsReady(userId, colonyId, now);
      // every other colony, so the player can pick who helps (and see why one can't)
      const list = coloniesOf(userId).filter((c) => c.id !== colonyId).map((c) => {
        const ok = ready.includes(c.id);
        const busy = (c.state.queue || []).filter((q) => !q.finishAt || q.finishAt > now).length;
        return { id: c.id, name: c.name, ok, busy, cap: QUEUE_LIMIT, why: ok ? "" : handsLend(c.id, now) ? "already helping" : "queue full" };
      });
      return { ready: ready.length, total: Math.max(0, mine - 1), list };
    })(),
    ally: !!allianceOf(userId),
    askJob: s.askJob || null,
    terra: Math.floor(s.terra),
    pct: { overtime: Math.round(OVERTIME_CUT * 100), hands: Math.round(HANDS_CUT * 100), ally: Math.round(ALLY_HELP_CUT * 100), allyMax: Math.round(ALLY_HELP_MAX * 100), free: Math.round(BOOST_FREE_MAX * 100) },
    overtimeMaxMs: Math.round((OVERTIME_MAX_MIN * 60000) / BUILD_SPEED),
    freeFinishMs: freeFinishMs(),
  };
}

// ---------- 🎖️ the commander's crew ----------
function crewWhyNot(s, c, kind, slot) {
  if (c.error && c.error !== "Build queue is full") return c.error;
  if (s.crewJob) return "The crew is busy";
  if (c.target > CREW_MAX_LEVEL) return "The crew only builds up to level " + CREW_MAX_LEVEL;
  if (s.queue.some((q) => q.kind === kind && q.slot === slot)) return "It is already in the build queue";
  if (!c.cost || !canAfford(s, c.cost)) return "Not enough resources";
  return null;
}
function crewFits(s, userId, c, kind, slot) {
  return !crewWhyNot(s, c, kind, slot);
}
// The crew is one for the whole account: while it builds in one colony it can't start
// anything in another one (even if the commander walks there).
function crewClear(colonyId) {
  if (colonyId) db.prepare("DELETE FROM crew_busy WHERE colony_id = ?").run(colonyId);
}
function crewBusyElsewhere(userId, colonyId, now) {
  const row = db.prepare("SELECT * FROM crew_busy WHERE user_id = ?").get(userId);
  if (!row || row.colony_id === colonyId) return null;
  const c = row.finish_at > now ? loadColony(row.colony_id) : null;
  if (c) {
    update(c.state, tribeOf(c.tribe), now);
    saveColony(c.id, c.state);
  }
  if (!c || c.userId !== userId || !c.state.crewJob) { db.prepare("DELETE FROM crew_busy WHERE user_id = ?").run(userId); return null; }
  return { colony: c.name, leftMs: jobLeft(c.state.crewJob, now) };
}
function crewHere(userId, colonyId, now) {
  const h = heroOf(userId, now);
  // the crew works wherever the commander is stationed, even while it is away, hurt or on an adventure
  return !!h && h.home === colonyId && !h.move;
}
function crewView(s, tribe, userId, now) {
  const here = crewHere(userId, s._cid, now);
  const j = s.crewJob;
  const away = here && !j ? crewBusyElsewhere(userId, s._cid, now) : null;
  // why the crew can't build here right now (the commander is elsewhere or busy)
  let off = null;
  if (!here && !j) {
    const h = heroOf(userId, now);
    if (!h) off = null;
    else if (h.move) off = { why: "moving", leftMs: Math.max(0, h.move.at - now) };
    else if (h.home !== s._cid) {
      const c = db.prepare("SELECT name FROM colonies WHERE id = ?").get(h.home);
      off = { why: "elsewhere", colony: c ? c.name : "" };
    }
  }
  return {
    here,
    away,
    off,
    free: here && !j && !away,
    maxLevel: CREW_MAX_LEVEL,
    job: j
      ? Object.assign({ name: tribe.names[j.type][0], icon: tribe.names[j.type][1], targetLevel: j.targetLevel, durationMs: jobBase(j), remainingMs: jobLeft(j, now), active: true, crew: true }, jobBoostView(s, j, now))
      : null,
  };
}
// Start a build job in the queue, or with the crew
function startJob(s, userId, c, job, crew) {
  const now = Date.now();
  job.at = now;
  if (!crew) {
    if (c.error) return c.error;
    pay(s, c.cost);
    s.queue.push(job);
    startNextConstruction(s, now);
    return null;
  }
  if (!crewHere(userId, s._cid, now)) return "Your commander has to be stationed here";
  const far = crewBusyElsewhere(userId, s._cid, now);
  if (far) return "The crew is still busy in " + far.colony + " (" + fmtMs(far.leftMs) + " left)";
  const no = crewWhyNot(s, c, job.kind, job.slot);
  if (no) return no;
  pay(s, c.cost);
  job.finishAt = now + job.duration;
  s.crewJob = job;
  db.prepare("INSERT INTO crew_busy (user_id, colony_id, finish_at) VALUES (?, ?, ?) ON CONFLICT (user_id) DO UPDATE SET colony_id = excluded.colony_id, finish_at = excluded.finish_at").run(userId, s._cid, job.finishAt);
  return null;
}

// ---------- 📋 the plan queue ----------
// One free slot behind the build queue: "after this, build that". A planned
// job starts by itself as soon as the queue has room and the colony can pay.
// Until then its cost is reserved: trade routes leave those resources alone.
const PLAN_SLOTS = 1;
const PLAN_DEAD = /Max level|already have|limit here|Unknown|Choose a building|All lots are full|Upgrade one of them/;
function planCheck(s, tribe, p) {
  if (p.kind === "field") {
    if (!s.fields[p.slot]) return { error: "Unknown field" };
    const c = checkField(s, p.slot);
    return { c, job: { id: newJobId(), kind: "field", slot: p.slot, type: s.fields[p.slot].type, targetLevel: c.target, cost: c.cost, duration: c.duration, finishAt: null } };
  }
  let slot = p.slot;
  if (slot === undefined || !(slot >= 0 && slot < BUILDING_SLOTS) || (p.type && slotType(s, slot) && slotType(s, slot) !== p.type)) slot = freeSlot(s);
  if (slot < 0) return { c: { error: "All lots are full" } };
  const c = checkBuilding(s, tribe, slot, p.type);
  return { c, job: { id: newJobId(), kind: "building", slot, type: c.type, targetLevel: c.target, cost: c.cost, duration: c.duration, finishAt: null } };
}
// what each planned job will cost (later entries for the same spot go one level higher)
function planCosts(s, tribe) {
  const seen = {};
  return s.plan.map((p) => {
    const key = p.kind + ":" + (p.kind === "field" ? p.slot : p.type || (p.slot >= 0 && p.slot < BUILDING_SLOTS ? slotType(s, p.slot) : ""));
    const extra = seen[key] || 0;
    seen[key] = extra + 1;
    if (p.kind === "field") {
      const f = s.fields[p.slot];
      if (!f) return null;
      const target = f.level + jobsOf(s).filter((q) => q.kind === "field" && q.slot === p.slot).length + 1 + extra;
      return { target, cost: fieldCost(f.type, target) };
    }
    const type = p.type || (p.slot >= 0 && p.slot < BUILDING_SLOTS ? slotType(s, p.slot) : null);
    if (!type) return null;
    const slot = p.slot >= 0 && p.slot < BUILDING_SLOTS && slotType(s, p.slot) === type ? p.slot : -1;
    const lv = slot >= 0 ? s.buildings[slot].level + jobsOf(s).filter((q) => q.kind === "building" && q.slot === slot).length : 0;
    const target = lv + 1 + extra;
    return { target, cost: buildingCost(s, type, target), type };
  });
}
function planView(s, tribe) {
  const costs = planCosts(s, tribe), names = tribe.names;
  return {
    slots: PLAN_SLOTS,
    reserve: planReserve(s, tribe),
    note: s.planNote && Date.now() - s.planNote.at < 3600000 ? s.planNote.text : "",
    list: s.plan.map((p, i) => {
      const x = costs[i] || {};
      const type = p.kind === "field" ? s.fields[p.slot] && s.fields[p.slot].type : x.type;
      const why = planCheck(s, tribe, p).c.error || "";
      const lv = x.target || 1;
      return { ms: type ? (p.kind === "field" ? fieldDuration(s, type, lv) : buildingDuration(s, type, lv)) : 0, kind: p.kind, slot: p.slot, type, name: names[type] ? names[type][0] : type || "?", icon: names[type] ? names[type][1] : "🏗️", target: x.target || 0, cost: x.cost || null, why: i === 0 ? why : "Waits for the plan above" };
    }),
  };
}
function planReserve(s, tribe) {
  const out = { wood: 0, stone: 0, metal: 0, food: 0 };
  if (!s.plan || !s.plan.length) return out;
  for (const x of planCosts(s, tribe)) if (x) for (const r of RESOURCES) out[r] += x.cost[r] || 0;
  for (const r of RESOURCES) out[r] = Math.min(out[r], Math.max(0, Math.floor(s.res[r])));
  return out;
}
function runPlan(s, tribe, userId) {
  if (!s.plan || !s.plan.length) return 0;
  let started = 0;
  for (let i = 0; i < PLAN_SLOTS + 1 && s.plan.length; i++) {
    const p = s.plan[0];
    const x = planCheck(s, tribe, p);
    if (x.c.error) {
      if (PLAN_DEAD.test(x.c.error)) { s.plan.shift(); s.planNote = { text: x.c.error, at: Date.now() }; continue; }
      break; // waits: money, room in the queue or a building that is still going up
    }
    startJob(s, userId, x.c, x.job, false);
    s.plan.shift();
    started++;
  }
  return started;
}
app.post("/api/plan", requireLogin, (req, res) => {
  withColony(req, res, (s, tribe) => {
    const b = req.body || {};
    if (s.plan.length >= PLAN_SLOTS) return "The plan has " + PLAN_SLOTS + " slots. Remove one first.";
    const kind = b.kind === "field" ? "field" : "building";
    const slot = parseInt(b.slot, 10);
    const p = { kind, slot: isNaN(slot) ? -1 : slot, at: Date.now() };
    if (kind === "building" && b.type) {
      if (!BUILDING_TYPES[String(b.type)]) return "Unknown building";
      p.type = String(b.type);
    }
    if (kind === "field" && !s.fields[p.slot]) return "Unknown field";
    if (kind === "building" && !p.type && !(p.slot >= 0 && p.slot < BUILDING_SLOTS && slotType(s, p.slot))) return "Choose a building";
    // only plans that can work some day: the final checks run when it starts
    s.plan.push(p);
    const x = planCheck(s, tribe, p);
    if (s.plan.length === 1 && x.c.error && PLAN_DEAD.test(x.c.error)) { s.plan.pop(); return x.c.error; }
    runPlan(s, tribe, req.user.id);
    return null;
  });
});
app.post("/api/plan/del", requireLogin, (req, res) => {
  withColony(req, res, (s) => {
    const i = parseInt((req.body || {}).i, 10);
    if (!(i >= 0 && i < s.plan.length)) return "That plan is gone already";
    s.plan.splice(i, 1);
    return null;
  });
});
// planned jobs also start while nobody is looking
setInterval(() => {
  try {
    const now = Date.now();
    for (const r of db.prepare("SELECT id FROM colonies WHERE state LIKE '%\"plan\":[{%'").all()) {
      const c = loadColony(r.id);
      if (!c || !c.state.plan || !c.state.plan.length) continue;
      const tribe = tribeOf(c.tribe);
      update(c.state, tribe, now);
      if (runPlan(c.state, tribe, c.userId)) saveColony(c.id, c.state);
    }
  } catch (e) { console.error("plan", e); }
}, 15000);

// ---------- the speed-ups of my own jobs ----------
app.post("/api/boost", requireLogin, (req, res) => {
  withColony(req, res, (s, tribe, colony) => {
    const body = req.body || {};
    const now = Date.now();
    const job = findJob(s, String(body.job || ""));
    if (!job) return "That job is already done";
    const how = String(body.how || "");
    const day = serverDayNo(now);
    if (how === "overtime") {
      if (s.overtimeDay === day) return "Overtime is used up for today";
      const ms = overtimeMs(job, now);
      if (ms <= 0) return "This job has had all the free help it can take";
      cutJob(job, ms, now);
      s.overtimeDay = day;
    } else if (how === "hands") {
      if (colonyIdsOf(req.user.id).length < 2) return "You need a second colony for this";
      // only the colonies the player picked
      const want = Array.isArray(body.from) ? body.from.map(Number) : [];
      if (!want.length) return "Pick which colonies should help";
      const free = handsReady(req.user.id, colony.id, now);
      const ready = want.filter((id) => free.includes(id));
      if (!ready.length) return "Those colonies have no free build slot (or are already helping)";
      const per = Math.round(jobBase(job) * HANDS_CUT);
      const room = freeRoom(job, now);
      if (room <= 0) return "This job has had all the free help it can take";
      const n = Math.min(ready.length, Math.ceil(room / per));
      cutJob(job, Math.min(room, n * per), now);
      const mark = db.prepare("INSERT INTO build_hands (colony_id, day, for_colony, job) VALUES (?, ?, ?, ?) ON CONFLICT (colony_id) DO UPDATE SET day = excluded.day, for_colony = excluded.for_colony, job = excluded.job");
      ready.slice(0, n).forEach((id) => { mark.run(id, day, colony.id, job.id); handsCache.delete(id); });
    } else if (how === "ask") {
      if (!allianceOf(req.user.id)) return "Join an alliance first";
      if ((job.ally || 0) >= Math.round(jobBase(job) * ALLY_HELP_MAX) || freeRoom(job, now) <= 0) return "This job has had all the free help it can take";
      s.askJob = job.id;
      db.prepare("INSERT INTO build_asks (colony_id, user_id, job_id, helpers, at) VALUES (?, ?, ?, ?, ?) ON CONFLICT (colony_id) DO UPDATE SET job_id = excluded.job_id, helpers = excluded.helpers, at = excluded.at")
        .run(colony.id, req.user.id, job.id, JSON.stringify(job.helpers || []), now);
    } else if (how === "free") {
      // the last minutes of a job being built are free (5 min on x1, 1 min on x10)
      if (!job.finishAt) return "Only a job that is being built can be finished for free";
      const left = jobLeft(job, now);
      if (left > freeFinishMs()) return "Free in the last " + fmtMs(freeFinishMs());
      cutJob(job, left, now);
    } else if (how === "unask") {
      s.askJob = null;
      askDone(colony.id);
    } else return "Unknown speed-up";
    update(s, tribe, now);
    return null;
  });
});
function fmtMs(ms) {
  const m = Math.round(ms / 60000);
  return m >= 60 ? Math.round(m / 6) / 10 + " h" : Math.max(1, m) + " min";
}

// ---------- 🤝 helping an ally ----------
app.post("/api/build-help", requireLogin, (req, res) => {
  const now = Date.now();
  const uid = req.user.id;
  const me = allianceOf(uid);
  if (!me) return res.status(400).json({ error: "Join an alliance first" });
  const row = db.prepare("SELECT * FROM build_asks WHERE colony_id = ?").get(parseInt((req.body || {}).colony, 10) || 0);
  if (!row) return res.status(400).json({ error: "That request is gone" });
  if (row.user_id === uid) return res.status(400).json({ error: "You can’t help yourself" });
  const other = allianceOf(row.user_id);
  if (!other || other.id !== me.id) return res.status(400).json({ error: "Only allies can help" });
  if (allyHelpsLeft(uid, row.user_id, now) <= 0) return res.status(400).json({ error: "You already helped " + (usernameOf(row.user_id) || "this ally") + " " + ALLY_HELPS_PER_MEMBER + " times today" });
  const c = loadColony(row.colony_id);
  if (!c || c.userId !== row.user_id) { askDone(row.colony_id); return res.status(400).json({ error: "That request is gone" }); }
  const tribe = tribeOf(c.tribe);
  update(c.state, tribe, now);
  const s = c.state;
  const job = findJob(s, row.job_id);
  if (!job || s.askJob !== job.id) {
    askDone(c.id);
    saveColony(c.id, s);
    return res.status(400).json({ error: "That job is already done" });
  }
  job.helpers = job.helpers || [];
  if (job.helpers.includes(uid)) return res.status(400).json({ error: "You already helped with this job" });
  const base = jobBase(job);
  const ms = Math.min(Math.round(base * ALLY_HELP_CUT), Math.round(base * ALLY_HELP_MAX) - (job.ally || 0), freeRoom(job, now));
  if (ms <= 0) return res.status(400).json({ error: "This job can’t take more help" });
  cutJob(job, ms, now);
  job.ally = (job.ally || 0) + ms;
  job.helpers.push(uid);
  const full = job.ally >= Math.round(base * ALLY_HELP_MAX) || freeRoom(job, now) <= 0;
  if (full) { s.askJob = null; askDone(c.id); }
  else db.prepare("UPDATE build_asks SET helpers = ? WHERE colony_id = ?").run(JSON.stringify(job.helpers), c.id);
  update(s, tribe, now);
  saveColony(c.id, s);
  db.prepare("INSERT INTO build_help_log (user_id, owner_id, day, n) VALUES (?, ?, ?, 1) ON CONFLICT (user_id, owner_id, day) DO UPDATE SET n = n + 1").run(uid, row.user_id, serverDayNo(now));
  res.json({ ok: true, ms });
});

// Open requests in my alliance (for the alliance page)
function buildAsksView(aid, uid, now) {
  const rows = db
    .prepare(
      `SELECT build_asks.*, users.username FROM build_asks
         JOIN alliance_members ON alliance_members.user_id = build_asks.user_id
         JOIN users ON users.id = build_asks.user_id
        WHERE alliance_members.alliance_id = ? ORDER BY build_asks.at`
    )
    .all(aid);
  const list = [];
  for (const r of rows) {
    const c = loadColony(r.colony_id);
    if (!c || c.userId !== r.user_id) { askDone(r.colony_id); continue; }
    const tribe = tribeOf(c.tribe);
    update(c.state, tribe, now);
    const job = findJob(c.state, r.job_id);
    if (!job || c.state.askJob !== job.id) { askDone(c.id); continue; }
    const base = jobBase(job);
    list.push({
      colony: c.id, owner: r.username, colonyName: c.name, mine: r.user_id === uid,
      icon: tribe.names[job.type][1], name: tribe.names[job.type][0], level: job.targetLevel,
      leftMs: jobLeft(job, now), running: !!job.finishAt,
      helped: (job.helpers || []).includes(uid), helpers: (job.helpers || []).length, left: allyHelpsLeft(uid, r.user_id, now),
      allyPct: Math.round(((job.ally || 0) / base) * 100), maxPct: Math.round(ALLY_HELP_MAX * 100),
    });
  }
  return { list, per: Math.round(ALLY_HELP_CUT * 100), perMember: ALLY_HELPS_PER_MEMBER };
}
// how many requests I could still help with (the dot on the alliance tab)
function allyAskCount(uid, now) {
  const me = allianceOf(uid);
  if (!me) return 0;
  const rows = db
    .prepare("SELECT build_asks.user_id, build_asks.helpers FROM build_asks JOIN alliance_members ON alliance_members.user_id = build_asks.user_id WHERE alliance_members.alliance_id = ? AND build_asks.user_id != ?")
    .all(me.id, uid);
  let n = 0;
  for (const r of rows) {
    let h = [];
    try { h = JSON.parse(r.helpers); } catch (e) {}
    if (!h.includes(uid) && allyHelpsLeft(uid, r.user_id, now) > 0) n++;
  }
  return n;
}

