// =====================================================================
//  ⚖️ LEGAL PAGE + 🗑️ ACCOUNT DELETION
//  /legal shows the legal notice (Impressum) and the privacy policy. The
//  owner fills in the details on the admin page (Server tab); the texts
//  are built from them. It is a template, not legal advice.
//  A player can delete their own account in the settings; everything
//  that belongs to them goes with it.
// =====================================================================
const LEGAL_FIELDS = [
  // key, label, placeholder, group, needed
  ["name", "Name or company", "Jane Doe", "imprint", true],
  ["street", "Street and number", "Example Street 1", "imprint", true],
  ["city", "ZIP and city", "12345 Example City", "imprint", true],
  ["country", "Country", "Germany", "imprint", false],
  ["email", "Email", "contact@example.com", "imprint", true],
  ["phone", "Phone (optional)", "", "imprint", false],
  ["responsible", "Responsible for the content, if not you (optional)", "", "imprint", false],
  ["vat", "VAT ID (optional)", "", "imprint", false],
  ["extraImprint", "More for the legal notice (optional)", "", "imprint", false, true],
  ["privacyEmail", "Email for data requests (empty = the email above)", "", "privacy", false],
  ["hostName", "Hosting provider", "alwaysdata", "privacy", false],
  ["hostAddress", "Hosting provider address", "", "privacy", false],
  ["mailAddress", "Mail provider address (Brevo)", "", "privacy", false],
  ["authority", "Data protection authority of your state (optional)", "", "privacy", false],
  ["extraPrivacy", "More for the privacy policy (optional)", "", "privacy", false, true],
];
function legalRead() {
  let o = {};
  try { o = JSON.parse(settingOf("legal", "{}")) || {}; } catch (e) {}
  const out = {};
  for (const f of LEGAL_FIELDS) out[f[0]] = String(o[f[0]] || "").slice(0, f[5] ? 2000 : 200);
  if (!out.hostName) out.hostName = "alwaysdata";
  return out;
}
function legalMissing(L) {
  return LEGAL_FIELDS.filter((f) => f[4] && !L[f[0]].trim()).map((f) => f[1]);
}
app.get("/api/admin/legal", requireOwner, (req, res) => {
  const L = legalRead();
  res.json({ fields: LEGAL_FIELDS.map((f) => ({ key: f[0], label: f[1], hint: f[2], group: f[3], needed: f[4], long: !!f[5], value: L[f[0]] })), missing: legalMissing(L), mail: mailReady() });
});
app.post("/api/admin/legal", requireOwner, (req, res) => {
  const b = (req.body && req.body.fields) || {};
  const o = {};
  for (const f of LEGAL_FIELDS) o[f[0]] = String(b[f[0]] === undefined ? "" : b[f[0]]).replace(/\r/g, "").trim().slice(0, f[5] ? 2000 : 200);
  setSetting("legal", JSON.stringify(o));
  adminLog(req, "Legal page saved");
  const miss = legalMissing(legalRead());
  res.json({ ok: true, message: miss.length ? "Saved. Still missing: " + miss.join(", ") : "Saved. The legal page is complete" });
});

