if (PATCH_NOTES[0].v !== GAME_VERSION) console.warn("⚠️ Patch notes: the newest entry (" + PATCH_NOTES[0].v + ") is not the current version (" + GAME_VERSION + ")");

function patchNotesPage(lang) {
  const idx = TR_LANG_ORDER.indexOf(lang);
  const pnTitle = idx >= 0 && builtInStrings()["Patch notes"] ? builtInStrings()["Patch notes"][idx] : "Patch notes";
  let h = "<h1>" + escHtml(pnTitle) + '</h1><p class="sub">MarsL ' + escHtml(GAME_VERSION) + ' · <a href="/">' + escHtml(legalT(lang).back) + "</a></p>";
  PATCH_NOTES.forEach((p0, i) => {
    const p = p0.i18n && p0.i18n[lang] ? Object.assign({}, p0, p0.i18n[lang]) : p0;
    const head = (p.v === "earlier" ? "" : '<span class="ver">' + escHtml(p.v) + "</span> ") + escHtml(p.title) + (p.date ? ' <small class="dt">' + escHtml(p.date) + "</small>" : "");
    let body = "";
    for (const g of p.groups) body += "<h3>" + escHtml(g[0]) + "</h3><ul>" + g[1].map((x) => "<li>" + escHtml(x) + "</li>").join("") + "</ul>";
    h += '<details class="patch"' + (i < 2 ? " open" : "") + "><summary>" + head + "</summary>" + body + "</details>";
  });
  return h;
}
app.get("/patch-notes", (req, res) => {
  res.setHeader("Cache-Control", "no-store");
  const lang = String(req.query.lang || "");
  const idx = TR_LANG_ORDER.indexOf(lang);
  const ttl = idx >= 0 && builtInStrings()["Patch notes"] ? builtInStrings()["Patch notes"][idx] : "Patch notes";
  res.send(LEGAL_SHELL.split("__TITLE__").join(escHtml(ttl)).split("__BODY__").join(patchNotesPage(lang)).replace('<html lang="en">', '<html lang="' + (idx >= 0 ? lang : "en") + '">'));
});
app.get("/api/patch-notes", (req, res) => {
  res.json({ version: GAME_VERSION, notes: PATCH_NOTES });
});

// =====================================================================
//  v95 - VACATION MODE and ACCOUNT SITTING
//  Vacation: nobody can attack or spy on you, you cannot send troops.
//  Your colonies keep growing. After it ends there is a short shield
//  and a pause before the next vacation.
//  Sitting: up to 2 alliance mates may manage your colonies (build, train,
//  research, speed up) while you are away. They can not send anything.
// =====================================================================
const VAC_MIN_DAYS = 1; // server days
const VAC_MAX_DAYS = 14;
const VAC_COOLDOWN_DAYS = 7;
const VAC_SHIELD_FRAC = 0.25; // of a server day, after the vacation ends
const SITTERS_MAX = 2;
const SIT_LOG_MAX = 30;

addColumn("users", "vac", "TEXT NOT NULL DEFAULT '{}'");
addColumn("sessions", "sit_for", "INTEGER");
db.exec(`
  CREATE TABLE IF NOT EXISTS account_sitters (
    user_id   INTEGER NOT NULL,
    sitter_id INTEGER NOT NULL,
    at        INTEGER NOT NULL,
    PRIMARY KEY (user_id, sitter_id)
  );
  CREATE TABLE IF NOT EXISTS sit_log (
    id        INTEGER PRIMARY KEY AUTOINCREMENT,
    user_id   INTEGER NOT NULL,
    sitter_id INTEGER NOT NULL,
    at        INTEGER NOT NULL,
    what      TEXT NOT NULL
  );
  CREATE INDEX IF NOT EXISTS sit_log_user ON sit_log (user_id, id);
`);

function vacRaw(userId) {
  const r = db.prepare("SELECT vac FROM users WHERE id = ?").get(userId);
  try { return JSON.parse((r && r.vac) || "{}") || {}; } catch (e) { return {}; }
}
function vacSave(userId, v) {
  db.prepare("UPDATE users SET vac = ? WHERE id = ?").run(JSON.stringify(v), userId);
}
function vacEnd(userId, v, at) {
  v.from = 0;
  v.shield = at + Math.round(serverDayMs() * VAC_SHIELD_FRAC);
  v.cool = at + VAC_COOLDOWN_DAYS * serverDayMs();
  vacSave(userId, v);
}
// { on, from, until, minEnd, shield, cool }  (times are 0 when they do not apply)
function vacationOf(userId, now) {
  now = now || Date.now();
  const v = vacRaw(userId);
  if (v.from && v.until <= now) vacEnd(userId, v, v.until); // the time ran out by itself
  return {
    on: !!v.from,
    from: v.from || 0,
    until: v.from ? v.until : 0,
    minEnd: v.from ? v.from + VAC_MIN_DAYS * serverDayMs() : 0,
    shield: !v.from && v.shield > now ? v.shield : 0,
    cool: !v.from && v.cool > now ? v.cool : 0,
  };
}

function vacStartCheck(userId, now) {
  const v = vacationOf(userId, now);
  if (v.on) return "You are already on vacation";
  if (v.cool) return "You can start the next vacation in " + fmtDuration(v.cool - now);
  const ids = colonyIdsOf(userId);
  if (!ids.length) return "You have no colony";
  const mark = ids.map(() => "?").join(",");
  if (db.prepare("SELECT 1 FROM movements WHERE attacker_id IN (" + mark + ") AND mission != 'trade' AND phase IN ('out', 'back')").get(...ids)) return "Wait until all your troops are home";
  if (db.prepare("SELECT 1 FROM movements WHERE target_id IN (" + mark + ") AND target_kind = 'colony' AND phase = 'out' AND mission IN ('attack', 'raid', 'scout') AND attacker_id NOT IN (" + mark + ")").get(...ids, ...ids)) return "An enemy is on the way to you. Vacation can start once it has landed.";
  if (zoneHolderUser(zoneRow()) === userId) return "You hold the Landing Zone. Hand it over before you leave.";
  if (coloniesOf(userId).some((c) => c.state.relic)) return "You hold a landmark relic. Hand it over before you leave.";
  return null;
}
function fmtDuration(ms) {
  const m = Math.max(1, Math.round(ms / 60000));
  if (m < 90) return m + " min";
  const h = m / 60;
  if (h < 48) return Math.round(h * 10) / 10 + " h";
  return Math.round((h / 24) * 10) / 10 + " days";
}

function vacationView(userId, now) {
  now = now || Date.now();
  const v = vacationOf(userId, now);
  return Object.assign({}, v, { minDays: VAC_MIN_DAYS, maxDays: VAC_MAX_DAYS, dayMs: serverDayMs(), shieldMs: Math.round(serverDayMs() * VAC_SHIELD_FRAC), cooldownDays: VAC_COOLDOWN_DAYS, canStart: v.on || v.cool ? null : vacStartCheck(userId, now) });
}
function vacationOn(userId, now) {
  return vacationOf(userId, now).on;
}

app.post("/api/vacation/start", requireLogin, (req, res) => {
  const now = Date.now();
  const days = Math.round(Number((req.body || {}).days));
  if (!(days >= VAC_MIN_DAYS && days <= VAC_MAX_DAYS)) return res.status(400).json({ error: "Choose " + VAC_MIN_DAYS + " to " + VAC_MAX_DAYS + " days" });
  const no = vacStartCheck(req.user.id, now);
  if (no) return res.status(400).json({ error: no });
  vacSave(req.user.id, Object.assign(vacRaw(req.user.id), { from: now, until: now + days * serverDayMs(), days }));
  endProtection(req.user.id); // vacation replaces the newbie shield
  withColony(req, res, null);
});

app.post("/api/vacation/end", requireLogin, (req, res) => {
  const now = Date.now();
  const v = vacationOf(req.user.id, now);
  if (!v.on) return withColony(req, res, null);
  if (now < v.minEnd) return res.status(400).json({ error: "A vacation lasts at least " + VAC_MIN_DAYS + " day. You can end it in " + fmtDuration(v.minEnd - now) + "." });
  vacEnd(req.user.id, vacRaw(req.user.id), now);
  withColony(req, res, null);
});

// =====================================================================
//  ACCOUNT SITTING
// =====================================================================
function sittersOf(userId) {
  return db.prepare("SELECT users.id, users.username, account_sitters.at FROM account_sitters JOIN users ON users.id = account_sitters.sitter_id WHERE account_sitters.user_id = ? ORDER BY account_sitters.at").all(userId);
}
function sitsFor(sitterId) {
  return db.prepare("SELECT users.id, users.username FROM account_sitters JOIN users ON users.id = account_sitters.user_id WHERE account_sitters.sitter_id = ? ORDER BY users.username").all(sitterId);
}
// May this sitter look after that player right now? (same alliance, listed, not blocked)
function sitAllowed(sitterId, userId) {
  if (!db.prepare("SELECT 1 FROM account_sitters WHERE user_id = ? AND sitter_id = ?").get(userId, sitterId)) return false;
  if (!areAllies(sitterId, userId)) return false;
  const u = db.prepare("SELECT banned FROM users WHERE id = ?").get(userId);
  return !!u && !u.banned;
}

// While sitting only these actions are allowed (everything else that changes things is refused)
const SIT_POST_OK = [
  /^\/api\/field\//, /^\/api\/building\//, /^\/api\/construct$/, /^\/api\/cancel$/, /^\/api\/cancel-job$/, /^\/api\/cancel-training$/,
  /^\/api\/train$/, /^\/api\/research$/, /^\/api\/upgrade-unit$/, /^\/api\/heal$/, /^\/api\/boost$/, /^\/api\/switch$/,
  /^\/api\/recall$/, /^\/api\/cancel-move$/, /^\/api\/reports\/seen$/, /^\/api\/sit\/(start|stop)$/, /^\/api\/logout$/,
];
const SIT_GET_NO = [/^\/api\/account/, /^\/api\/messages/, /^\/api\/dev\//, /^\/api\/admin\//];
const VAC_POST_NO = [/^\/api\/send$/, /^\/api\/waves$/, /^\/api\/trade$/, /^\/api\/market\/accept$/];

function pathOf(req) {
  return String(req.originalUrl || req.url || req.path || "").split("?")[0];
}

// Returns a text if this request must not go through
function requestGuard(req, actorId, sitting) {
  const p = pathOf(req);
  const post = req.method === "POST";
  if (sitting) {
    if (post && !SIT_POST_OK.some((r) => r.test(p))) return "🪑 Sitters can't do that. Build, train, research and speed up are fine.";
    if (!post && SIT_GET_NO.some((r) => r.test(p))) return "🪑 Sitters can't look at that.";
  }
  if (post && VAC_POST_NO.some((r) => r.test(p)) && vacationOn(actorId)) return "🏖️ You are on vacation. End it first to send anything.";
  return null;
}

function sitLog(userId, sitterId, p) {
  const what = p.replace(/^\/api\//, "");
  db.prepare("INSERT INTO sit_log (user_id, sitter_id, at, what) VALUES (?, ?, ?, ?)").run(userId, sitterId, Date.now(), what);
  db.prepare("DELETE FROM sit_log WHERE user_id = ? AND id NOT IN (SELECT id FROM sit_log WHERE user_id = ? ORDER BY id DESC LIMIT ?)").run(userId, userId, SIT_LOG_MAX);
}
const SIT_LOG_NAMES = {
  field: "upgraded a field", building: "upgraded a building", construct: "built something", cancel: "cancelled a build", "cancel-job": "cancelled a job",
  "cancel-training": "cancelled training", train: "trained troops", research: "started research", "upgrade-unit": "upgraded a unit", heal: "healed troops",
  boost: "sped something up", recall: "recalled troops", "cancel-move": "cancelled a movement",
};
function sitLogView(userId) {
  return db.prepare("SELECT sit_log.at, sit_log.what, users.username FROM sit_log JOIN users ON users.id = sit_log.sitter_id WHERE sit_log.user_id = ? ORDER BY sit_log.id DESC LIMIT 12").all(userId).map((r) => ({
    at: r.at,
    by: r.username,
    what: SIT_LOG_NAMES[String(r.what).split("/")[0]] || String(r.what).split("/")[0],
  }));
}

// requireLogin asks: is this session sitting for someone? Returns that player or null.
function sitTarget(row) {
  if (!row.sit_for) return null;
  if (!sitAllowed(row.id, row.sit_for)) {
    db.prepare("UPDATE sessions SET sit_for = NULL WHERE user_id = ? AND sit_for = ?").run(row.id, row.sit_for);
    return null;
  }
  return db.prepare("SELECT id, username FROM users WHERE id = ?").get(row.sit_for) || null;
}

function sittingView(req) {
  const realId = req.sitterId || req.user.id;
  const out = {
    sitting: req.sitterId ? { id: req.user.id, name: req.user.username } : null,
    maxSitters: SITTERS_MAX,
    forOthers: sitsFor(realId).filter((x) => areAllies(realId, x.id)),
  };
  if (!req.sitterId) {
    out.sitters = sittersOf(req.user.id).map((x) => ({ name: x.username, ally: areAllies(req.user.id, x.id) }));
    out.log = sitLogView(req.user.id);
  }
  return out;
}

app.get("/api/sitting", requireLogin, (req, res) => {
  res.json(sittingView(req));
});

app.post("/api/sitting/add", requireLogin, (req, res) => {
  if (req.sitterId) return res.status(400).json({ error: "Not while sitting" });
  const t = db.prepare("SELECT id, username FROM users WHERE username = ?").get(String((req.body || {}).name || "").trim());
  if (!t || t.id === req.user.id) return res.status(400).json({ error: "Pick a player from your alliance" });
  if (!areAllies(req.user.id, t.id)) return res.status(400).json({ error: "A sitter has to be in your alliance" });
  if (accountsLinked(req.user.id, t.id)) return res.status(400).json({ error: LINKED_MSG });
  if (sittersOf(req.user.id).length >= SITTERS_MAX) return res.status(400).json({ error: "You can have " + SITTERS_MAX + " sitters at most" });
  db.prepare("INSERT OR IGNORE INTO account_sitters (user_id, sitter_id, at) VALUES (?, ?, ?)").run(req.user.id, t.id, Date.now());
  res.json(sittingView(req));
});

app.post("/api/sitting/remove", requireLogin, (req, res) => {
  if (req.sitterId) return res.status(400).json({ error: "Not while sitting" });
  const t = db.prepare("SELECT id FROM users WHERE username = ?").get(String((req.body || {}).name || ""));
  if (t) {
    db.prepare("DELETE FROM account_sitters WHERE user_id = ? AND sitter_id = ?").run(req.user.id, t.id);
    db.prepare("UPDATE sessions SET sit_for = NULL WHERE user_id = ? AND sit_for = ?").run(t.id, req.user.id);
  }
  res.json(sittingView(req));
});

app.post("/api/sit/start", requireLogin, (req, res) => {
  const realId = req.sitterId || req.user.id;
  const t = db.prepare("SELECT id, username FROM users WHERE username = ?").get(String((req.body || {}).name || ""));
  if (!t || t.id === realId || !sitAllowed(realId, t.id)) return res.status(400).json({ error: "You can't sit for that player (they must list you and be in your alliance)" });
  db.prepare("UPDATE sessions SET sit_for = ?, active_colony = NULL WHERE token = ?").run(t.id, req.token);
  res.json({ ok: true });
});

app.post("/api/sit/stop", requireLogin, (req, res) => {
  db.prepare("UPDATE sessions SET sit_for = NULL, active_colony = NULL WHERE token = ?").run(req.token);
  res.json({ ok: true });
});

// Wiki numbers for vacation and sitting
function wikiVacation() {
  return { vacMin: VAC_MIN_DAYS, vacMax: VAC_MAX_DAYS, vacCool: VAC_COOLDOWN_DAYS, vacShieldMs: Math.round(serverDayMs() * VAC_SHIELD_FRAC), dayMs: serverDayMs(), sitters: SITTERS_MAX };
}

// =====================================================================
//  v95 - OPEN MARKET OFFERS
//  A player puts goods on the board ("give 500 metal, want 600 wood").
//  The goods and the merchants that will carry them wait at the market.
//  Whoever takes the offer pays with their own merchants; both loads
//  travel at the same time. Offers run out after one server day.
// =====================================================================
const OFFER_MAX = 3; // open offers per player
const OFFER_MIN = 50;
const OFFER_RATIO_MIN = 0.5; // want / give
const OFFER_RATIO_MAX = 2;
const OFFER_LIST = 40;

db.exec(`
  CREATE TABLE IF NOT EXISTS market_offers (
    id         INTEGER PRIMARY KEY AUTOINCREMENT,
    user_id    INTEGER NOT NULL,
    colony_id  INTEGER NOT NULL,
    give_res   TEXT NOT NULL,
    give_amt   INTEGER NOT NULL,
    want_res   TEXT NOT NULL,
    want_amt   INTEGER NOT NULL,
    merchants  INTEGER NOT NULL,
    ally_only  INTEGER NOT NULL DEFAULT 0,
    created_at INTEGER NOT NULL,
    expires_at INTEGER NOT NULL
  );
  CREATE INDEX IF NOT EXISTS market_offers_colony ON market_offers (colony_id);
`);

function offerMs() {
  return serverDayMs();
}
function offerMerchants(colonyId) {
  return db.prepare("SELECT COALESCE(SUM(merchants), 0) AS n FROM market_offers WHERE colony_id = ?").get(colonyId).n;
}
function resOnly(r, n) {
  const g = { wood: 0, stone: 0, metal: 0, food: 0 };
  g[r] = n;
  return g;
}
// Give the goods of an offer back to its colony (storage permitting)
function offerReturn(o, now) {
  db.prepare("DELETE FROM market_offers WHERE id = ?").run(o.id);
  const row = db.prepare("SELECT id FROM colonies WHERE id = ?").get(o.colony_id);
  if (!row) return;
  const c = loadColony(o.colony_id);
  update(c.state, tribeOf(c.tribe), now);
  refund(c.state, resOnly(o.give_res, o.give_amt));
  saveColony(c.id, c.state);
}
function offerSweep(now) {
  for (const o of db.prepare("SELECT * FROM market_offers WHERE expires_at <= ?").all(now)) offerReturn(o, now);
}
setInterval(() => { try { offerSweep(Date.now()); } catch (e) { console.error(e); } }, 60000);

function offerRow(o, colony, userId, now) {
  const c = db.prepare("SELECT colonies.name, colonies.x, colonies.y, users.username FROM colonies JOIN users ON users.id = colonies.user_id WHERE colonies.id = ?").get(o.colony_id);
  if (!c) return null;
  const dist = distance(colony.x, colony.y, c.x, c.y);
  return {
    id: o.id, mine: o.user_id === userId, give: o.give_res, giveAmt: o.give_amt, want: o.want_res, wantAmt: o.want_amt,
    allyOnly: !!o.ally_only, owner: c.username, colony: c.name, x: c.x, y: c.y,
    dist: Math.round(dist * 10) / 10, tripMs: merchantTrip(colony, c.x, c.y, now), endsAt: o.expires_at,
  };
}

function offersView(colony, userId, now) {
  const ally = allianceOf(userId);
  const mine = db.prepare("SELECT * FROM market_offers WHERE user_id = ? ORDER BY id").all(userId).map((o) => offerRow(o, colony, userId, now)).filter(Boolean);
  const open = db.prepare("SELECT * FROM market_offers WHERE user_id != ? AND expires_at > ?").all(userId, now)
    .filter((o) => !o.ally_only || (ally && areAllies(userId, o.user_id)))
    .filter((o) => !accountsLinked(userId, o.user_id))
    .map((o) => offerRow(o, colony, userId, now)).filter(Boolean)
    .sort((a, b) => a.dist - b.dist).slice(0, OFFER_LIST);
  return { mine, open, max: OFFER_MAX, min: OFFER_MIN, ratioMin: OFFER_RATIO_MIN, ratioMax: OFFER_RATIO_MAX, lastsMs: offerMs() };
}

app.get("/api/market/offers", requireLogin, (req, res) => {
  const now = Date.now();
  offerSweep(now);
  const c = db.prepare("SELECT id, x, y, user_id FROM colonies WHERE id = ?").get(req.colonyId);
  res.json(offersView({ x: c.x, y: c.y, userId: c.user_id }, req.user.id, now));
});

app.post("/api/market/offer", requireLogin, (req, res) => {
  const now = Date.now();
  offerSweep(now);
  withColony(req, res, (s, tribe, colony) => {
    const b = req.body || {};
    if (levelOf(s, "market") === 0) return "You need a marketplace first";
    const give = String(b.give || ""), want = String(b.want || "");
    const ga = Math.floor(Number(b.giveAmt)), wa = Math.floor(Number(b.wantAmt));
    if (!RESOURCES.includes(give) || !RESOURCES.includes(want) || give === want) return "Pick two different resources";
    if (!(ga >= OFFER_MIN) || !(wa >= OFFER_MIN)) return "At least " + OFFER_MIN + " on both sides";
    const ratio = wa / ga;
    if (ratio < OFFER_RATIO_MIN - 1e-9 || ratio > OFFER_RATIO_MAX + 1e-9) return "Fair trades only: ask for " + OFFER_RATIO_MIN + "× to " + OFFER_RATIO_MAX + "× of what you give";
    if (db.prepare("SELECT COUNT(*) AS n FROM market_offers WHERE user_id = ?").get(req.user.id).n >= OFFER_MAX) return "You have " + OFFER_MAX + " open offers already";
    if (ga > Math.floor(s.res[give])) return "You don't have that much " + give;
    const need = Math.ceil(ga / merchantCarry(s));
    const free = merchantsFree(s, colony.id);
    if (need > free) return "You need " + need + " merchants but only " + free + " are free";
    pay(s, resOnly(give, ga));
    db.prepare("INSERT INTO market_offers (user_id, colony_id, give_res, give_amt, want_res, want_amt, merchants, ally_only, created_at, expires_at) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)")
      .run(req.user.id, colony.id, give, ga, want, wa, need, b.allyOnly ? 1 : 0, now, now + offerMs());
    return null;
  });
});

app.post("/api/market/cancel", requireLogin, (req, res) => {
  const o = db.prepare("SELECT * FROM market_offers WHERE id = ? AND user_id = ?").get(Number((req.body || {}).id), req.user.id);
  if (!o) return res.status(400).json({ error: "That offer is gone" });
  offerReturn(o, Date.now());
  withColony(req, res, null);
});

app.post("/api/market/accept", requireLogin, (req, res) => {
  const now = Date.now();
  offerSweep(now);
  withColony(req, res, (s, tribe, colony) => {
    const o = db.prepare("SELECT * FROM market_offers WHERE id = ?").get(Number((req.body || {}).id));
    if (!o) return "Someone was faster - that offer is gone";
    if (o.user_id === req.user.id) return "That's your own offer";
    if (levelOf(s, "market") === 0) return "You need a marketplace first";
    if (accountsLinked(o.user_id, req.user.id)) return LINKED_MSG;
    if (o.ally_only && !areAllies(o.user_id, req.user.id)) return "This offer is for their alliance only";
    if (o.want_amt > Math.floor(s.res[o.want_res])) return "You need " + o.want_amt + " " + o.want_res;
    const need = Math.ceil(o.want_amt / merchantCarry(s));
    const free = merchantsFree(s, colony.id);
    if (need > free) return "You need " + need + " merchants but only " + free + " are free";
    const pc = db.prepare("SELECT id, x, y, user_id, name FROM colonies WHERE id = ?").get(o.colony_id);
    if (!pc || pc.user_id !== o.user_id) { db.prepare("DELETE FROM market_offers WHERE id = ?").run(o.id); return "That offer is gone"; }
    db.prepare("DELETE FROM market_offers WHERE id = ?").run(o.id);
    // my merchants carry what they asked for ...
    sendMerchants(s, colony, pc.id, resOnly(o.want_res, o.want_amt), now);
    // ... and theirs, already loaded, leave at the same moment
    const trip = merchantTrip({ x: pc.x, y: pc.y, userId: pc.user_id }, colony.x, colony.y, now);
    db.prepare(
      `INSERT INTO movements (attacker_id, target_id, mission, troops, depart_at, arrive_at, return_at, phase, next_at,
                              target_kind, target_x, target_y, loot, merchants, route)
       VALUES (?, ?, 'trade', '{}', ?, ?, ?, 'out', ?, 'colony', ?, ?, ?, ?, 0)`
    ).run(pc.id, colony.id, now, now + trip, now + 2 * trip, now + trip, colony.x, colony.y, JSON.stringify(resOnly(o.give_res, o.give_amt)), o.merchants);
    addReport(o.user_id, now, "🤝", tt("Offer taken: {0}", shortColonyName(req.user.username)), {
      mission: "offer", giveRes: o.give_res, giveAmt: o.give_amt, wantRes: o.want_res, wantAmt: o.want_amt, by: req.user.username, from: colony.name,
    });
    return null;
  });
});

// =====================================================================
//  v95 - ALLIANCE ROLES
//  👑 leader: everything, incl. diplomacy, roles and handing over the lead
//  ⭐ officer: invite, remove plain members, edit the description,
//              pay from the bank, remove joint attack plans
//  member: everything else (board, bank deposits, projects, plans, help)
// =====================================================================
const ALLY_OFFICERS_MAX = 4;
function allyStaff(me) {
  return !!me && (me.role === "leader" || me.role === "officer");
}
app.post("/api/alliance/role", requireLogin, (req, res) => {
  allianceAction(req, res, (b) => {
    const me = allianceOf(req.user.id);
    if (!me || me.role !== "leader") return "Only the leader can change roles";
    const target = db.prepare("SELECT id, username FROM users WHERE username = ?").get(String(b.name || ""));
    const t = target && allianceOf(target.id);
    if (!t || t.id !== me.id || target.id === req.user.id) return "Pick another member";
    const role = b.role === "officer" ? "officer" : "member";
    if (role === "officer" && t.role !== "officer") {
      const n = db.prepare("SELECT COUNT(*) AS n FROM alliance_members WHERE alliance_id = ? AND role = 'officer'").get(me.id).n;
      if (n >= ALLY_OFFICERS_MAX) return "An alliance can have " + ALLY_OFFICERS_MAX + " officers";
    }
    db.prepare("UPDATE alliance_members SET role = ? WHERE user_id = ?").run(role, target.id);
    db.prepare("INSERT INTO alliance_posts (alliance_id, user_id, at, body) VALUES (?, ?, ?, ?)").run(me.id, target.id, Date.now(), role === "officer" ? "⭐ is now an officer" : "is a member again");
    return null;
  });
});

// =====================================================================
//  v95 - SHARED REPORTS
//  A copy of a report goes to the alliance page. The newest ones stay,
//  older ones fall off. Only members can read them.
// =====================================================================
const SHARED_MAX = 30;
db.exec(`
  CREATE TABLE IF NOT EXISTS shared_reports (
    id          INTEGER PRIMARY KEY AUTOINCREMENT,
    alliance_id INTEGER NOT NULL,
    by_id       INTEGER NOT NULL,
    report_id   INTEGER NOT NULL,
    at          INTEGER NOT NULL,
    created_at  INTEGER NOT NULL,
    title       TEXT NOT NULL,
    icon        TEXT NOT NULL,
    data        TEXT NOT NULL,
    note        TEXT NOT NULL DEFAULT ''
  );
  CREATE INDEX IF NOT EXISTS shared_reports_ally ON shared_reports (alliance_id, id);
`);

function sharedList(allianceId) {
  return db.prepare("SELECT shared_reports.id, shared_reports.at, shared_reports.created_at, shared_reports.title, shared_reports.icon, shared_reports.note, shared_reports.by_id, users.username FROM shared_reports LEFT JOIN users ON users.id = shared_reports.by_id WHERE alliance_id = ? ORDER BY shared_reports.id DESC LIMIT ?")
    .all(allianceId, SHARED_MAX)
    .map((r) => ({ id: r.id, at: r.at, happened: r.created_at, title: r.title, icon: r.icon, note: r.note, by: r.username || "Deleted player", byId: r.by_id }));
}

app.post("/api/reports/share", requireLogin, (req, res) => {
  const me = allianceOf(req.user.id);
  if (!me) return res.status(400).json({ error: "Join an alliance to share reports" });
  const r = db.prepare("SELECT * FROM reports WHERE id = ? AND user_id = ?").get(Number((req.body || {}).id), req.user.id);
  if (!r) return res.status(400).json({ error: "That report is gone" });
  if (db.prepare("SELECT 1 FROM shared_reports WHERE alliance_id = ? AND report_id = ? AND by_id = ?").get(me.id, r.id, req.user.id)) return res.status(400).json({ error: "Already shared" });
  const note = String((req.body || {}).note || "").trim().slice(0, 120);
  db.prepare("INSERT INTO shared_reports (alliance_id, by_id, report_id, at, created_at, title, icon, data, note) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)").run(me.id, req.user.id, r.id, Date.now(), r.created_at, r.title, r.icon, r.data, note);
  db.prepare("DELETE FROM shared_reports WHERE alliance_id = ? AND id NOT IN (SELECT id FROM shared_reports WHERE alliance_id = ? ORDER BY id DESC LIMIT ?)").run(me.id, me.id, SHARED_MAX);
  res.json({ ok: true });
});

app.get("/api/alliance/shared", requireLogin, (req, res) => {
  const me = allianceOf(req.user.id);
  const r = me && db.prepare("SELECT * FROM shared_reports WHERE id = ? AND alliance_id = ?").get(Number(req.query.id), me.id);
  if (!r) return res.status(404).json({ error: "That report is gone" });
  res.json({ id: r.id, at: r.created_at, title: r.title, icon: r.icon, data: JSON.parse(r.data) });
});

app.post("/api/alliance/shared/remove", requireLogin, (req, res) => {
  const me = allianceOf(req.user.id);
  const r = me && db.prepare("SELECT * FROM shared_reports WHERE id = ? AND alliance_id = ?").get(Number((req.body || {}).id), me.id);
  if (!r) return res.status(400).json({ error: "That report is gone" });
  if (r.by_id !== req.user.id && !allyStaff(me)) return res.status(400).json({ error: "Only who shared it, an officer or the leader can remove it" });
  db.prepare("DELETE FROM shared_reports WHERE id = ?").run(r.id);
  res.json({ ok: true });
});

// =====================================================================
//  v95 - 🧭 ADVENTURES for the commander
//  From its colony the commander goes on a short, a normal or a long
//  trip. It comes back with experience (a share of what the next level
//  needs, so it stays useful at every level), resources for the bounty
//  stash and sometimes gear. It never falls on an adventure. While it is
//  away it does not defend, lead or produce.
// =====================================================================
// xp: the base amount, +12% per commander level above 1, so early levels go
// quickly and later on battles matter most. hp: health it costs (min, max)
const ADVENTURES = {
  short: { icon: "🥾", name: "Scouting trip", min: 8, xp: 12, hp: [3, 6], res: 40, gear: 0.05 },
  normal: { icon: "🧭", name: "Expedition", min: 25, xp: 32, hp: [8, 14], res: 120, gear: 0.14 },
  long: { icon: "🏔️", name: "Deep journey", min: 60, xp: 80, hp: [15, 25], res: 350, gear: 0.3 },
};
const ADV_XP_LVL = 0.12;
function advXp(kind, level) {
  return Math.round(ADVENTURES[kind].xp * (1 + ADV_XP_LVL * (level - 1)));
}
// 🧭 adventure board: a new adventure turns up every ADV_SPAWN_H server hours
// (what kind is luck), the board holds ADV_BOARD of them, the first two are
// there from the start. One that is taken makes room for the next to spawn.
const ADV_BOARD = 4;
const ADV_SPAWN_H = 2;
const ADV_START = 2;
const ADV_WEIGHTS = { short: 50, normal: 35, long: 15 };
function advSpawnMs() {
  return Math.round((serverDayMs() / 24) * ADV_SPAWN_H);
}
function advRollKind() {
  let r = Math.random() * 100;
  for (const k in ADV_WEIGHTS) if ((r -= ADV_WEIGHTS[k]) < 0) return k;
  return "short";
}
function advOffer(at) {
  return { id: crypto.randomBytes(3).toString("hex"), kind: advRollKind(), at };
}
// Bring the board up to date (called from heroOf)
function advBoardMax(h) {
  return ADV_BOARD + (heroRule(h, "explorer", 50) ? 2 : 0);
}
function advSync(h, now) {
  const before = JSON.stringify([h.advBoard, h.advSpawnAt]);
  if (!Array.isArray(h.advBoard)) {
    h.advBoard = [];
    for (let i = 0; i < ADV_START; i++) h.advBoard.push(advOffer(now));
    h.advSpawnAt = now + advSpawnMs();
  }
  if (h.advBoard.length >= advBoardMax(h)) {
    h.advSpawnAt = 0; // the clock only runs while there is room
  } else {
    if (!h.advSpawnAt) h.advSpawnAt = now + advSpawnMs();
    while (h.advSpawnAt <= now && h.advBoard.length < advBoardMax(h)) {
      h.advBoard.push(advOffer(h.advSpawnAt));
      h.advSpawnAt += advSpawnMs();
    }
    if (h.advBoard.length >= advBoardMax(h)) h.advSpawnAt = 0;
  }
  return before !== JSON.stringify([h.advBoard, h.advSpawnAt]);
}

// The way out and the way back each take ADV_WALK_MIN (the places are far away),
// in between it is on site for the trip's own time.
const ADV_WALK_MIN = { short: 2, normal: 5, long: 10 };
function advLegs(kind, h) {
  // 🧭 boots and bonus stats make the trip shorter, a faster server too
  const k = (1 - (h ? Math.min(HERO_CAPS.trip, heroGearStats(h).trip + (h.arch === "explorer" ? (h.pts.pathf || 0) * HERO_SKILLS.pathf.per : 0)) : 0) / 100) / MOVE_SPEED;
  return {
    out: Math.round(ADV_WALK_MIN[kind] * 60000 * k),
    site: Math.round(ADVENTURES[kind].min * 60000 * k),
    back: Math.round(ADV_WALK_MIN[kind] * 60000 * k),
  };
}
function advMs(kind, h) {
  const l = advLegs(kind, h);
  return l.out + l.site + l.back;
}
// where is the commander on its adventure: walking out, on site or walking back
function advPhase(a, now) {
  if (a.cancelled || (a.leaveAt && now >= a.leaveAt)) return "back";
  if (a.arriveAt && now < a.arriveAt) return "out";
  return "site";
}
function advView(h, now) {
  return {
    on: h.adv ? { kind: h.adv.kind, icon: ADVENTURES[h.adv.kind].icon, name: ADVENTURES[h.adv.kind].name, left: Math.max(0, h.adv.until - now), phase: advPhase(h.adv, now), cancelled: !!h.adv.cancelled } : null,
    board: h.advBoard.map((o) => ({ id: o.id, key: o.kind, icon: ADVENTURES[o.kind].icon, name: ADVENTURES[o.kind].name, ms: advMs(o.kind, h), xp: Math.round(advXp(o.kind, h.level) * (1 + heroGearStats(h).xp / 100)), hp: ADVENTURES[o.kind].hp, gear: Math.round(ADVENTURES[o.kind].gear * 100) })),
    max: advBoardMax(h),
    nextMs: h.advBoard.length >= advBoardMax(h) || !h.advSpawnAt ? 0 : Math.max(0, h.advSpawnAt - now),
    kinds: Object.keys(ADVENTURES).map((k) => ({ key: k, icon: ADVENTURES[k].icon, name: ADVENTURES[k].name, ms: advMs(k, h), xp: Math.round(advXp(k, h.level) * (1 + heroGearStats(h).xp / 100)), hp: ADVENTURES[k].hp, gear: Math.round(ADVENTURES[k].gear * 100) })),
    last: h.advLast || null,
  };
}

// Back home: what did it bring? (called lazily from heroOf)
function advFinish(userId, h) {
  const a = h.adv;
  const A = ADVENTURES[a.kind];
  h.adv = null;
  if (!A || a.cancelled) return; // called back: no reward
  const roll = 0.75 + Math.random() * 0.5; // a lucky or an unlucky trip
  const risk=a.route==="danger"&&!heroRule(h,"explorer",25)?1.6:.7;
  const xp = h.level >= HERO_MAX_LEVEL ? 0 : Math.round(advXp(a.kind, h.level) * roll * (a.route==="danger"?1.5:1));
  const dmg = (A.hp[0] + Math.random() * (A.hp[1] - A.hp[0])) * risk;
  const bounty = {};
  for (const r of RESOURCES) bounty[r] = Math.round((A.res * (1+Math.min(100,h.level)*.04) * (a.route==="danger"?1.5:1) * (0.5 + Math.random())) * roll);
  const note = heroAfterFight(userId, h, { xp, bounty, dmg, safe: true, at: a.until });
  h.stats.adv++;
  h.cosmetics=h.cosmetics||[];
  if(a.kind==='long'&&Math.random()<.02&&!h.cosmetics.includes('Olympus Trailblazer'))h.cosmetics.push('Olympus Trailblazer');
  if(a.route==='danger'&&Math.random()<.01)h.starMetal=(h.starMetal||0)+1;
  let found = null;
  if (Math.random() < A.gear) {
    found = heroItem(null, heroRollTier(HERO_DROPS.adv[a.kind]));
    if (h.bag.length < HERO_BAG) h.bag.push(found);
    else note.bagFull = found;
  }
  if (!h.advEvent) h.advEvent = { id: ADV_EVENTS[Math.floor(Math.random() * ADV_EVENTS.length)].id, kind: a.kind, at: a.until };
  const consumable=heroConsumableDrop(h,a.kind,a.route);
  h.advLast = { consumable, kind: a.kind, at: a.until, xp: note.xp, levelUp: note.levelUp || 0, res: note.stash || null, hp: note.hpLost || 0, found: found && !note.bagFull ? { icon: found.icon, name: found.name, tier: found.tier } : null };
  heroSave(userId, h);
  addReport(userId, a.until, A.icon, tt("{0} is back", shortColonyName(h.name)), Object.assign({ mission: "adventure", flavor: roll > 1.15 ? "A lucky trip!" : roll < 0.8 ? "Not much out there this time." : "A good trip." }, h.advLast, { name: h.name, bagFull: note.bagFull ? { icon: note.bagFull.icon, name: note.bagFull.name } : null }));
}

// 🐐 every adventure ends with a little event: two choices, the odds are shown
const ADV_EVENTS = [
  { id: "goat", icon: "🐐", text: "A space goat offers you a map.",
    a: { label: "Pay 200 food", cost: { food: 200 }, out: [{ p: 100, gear: 1 }] },
    b: { label: "Chase it", out: [{ p: 50, gear: 1 }, { p: 50, hp: 15 }] } },
  { id: "rover", icon: "🤖", text: "An old rover blinks HELLO and asks for a battery.",
    a: { label: "Give 150 metal", cost: { metal: 150 }, out: [{ p: 100, xp: 0.6 }] },
    b: { label: "Take it apart", out: [{ p: 60, res: { metal: 300 } }, { p: 40, hp: 10 }] } },
  { id: "dune", icon: "🎶", text: "A singing dune blocks the way home.",
    a: { label: "Sing along", out: [{ p: 70, xp: 0.4 }, { p: 30 }] },
    b: { label: "Dig through", out: [{ p: 50, res: { wood: 120, stone: 120, metal: 120, food: 120 } }, { p: 50, hp: 8 }] } },
  { id: "potato", icon: "🥔", text: "A lost potato farmer wants an escort home.",
    a: { label: "Escort him", out: [{ p: 100, res: { food: 350 } }] },
    b: { label: "Wish him luck", out: [{ p: 100, xp: 0.25 }] } },
  { id: "cave", icon: "🕳️", text: "A cave glitters. Something inside snores.",
    a: { label: "Tiptoe in", out: [{ p: 50, gear: 1 }, { p: 50, hp: 20 }] },
    b: { label: "Leave quietly", out: [{ p: 100, xp: 0.2 }] } },
  { id: "sock", icon: "🧦", text: "A single sock lies in the dust. It looks important.",
    a: { label: "Keep it", out: [{ p: 20, gear: 1 }, { p: 80, xp: 0.15 }] },
    b: { label: "Sell it to a trader", out: [{ p: 100, res: { wood: 90, stone: 90, metal: 90, food: 90 } }] } },
];
function advEventScaled(o) {
  return Object.assign({}, o || {});
}
function advEventView(h) {
  const E = h.advEvent && ADV_EVENTS.find((x) => x.id === h.advEvent.id);
  if (!E) return null;
  const opt = (O) => ({ label: O.label, cost: O.cost ? advEventScaled(O.cost) : null, out: O.out.map((x) => ({ p: x.p, gear: !!x.gear, hp: x.hp || 0, xp: x.xp ? Math.round(advXp(h.advEvent.kind, h.level) * x.xp) : 0, res: x.res ? advEventScaled(x.res) : null })) });
  return { icon: E.icon, text: E.text, a: opt(E.a), b: opt(E.b) };
}
function advEventPick(userId, h, s, which, now) {
  const E = h.advEvent && ADV_EVENTS.find((x) => x.id === h.advEvent.id);
  if (!E) return { error: "Nothing is waiting" };
  const O = which === "b" ? E.b : E.a;
  const cost = O.cost ? Object.assign({ wood: 0, stone: 0, metal: 0, food: 0 }, advEventScaled(O.cost)) : null;
  if (cost && !canAfford(s, cost)) return { error: "Not enough resources in this colony" };
  if (cost) pay(s, cost);
  let r = Math.random() * 100, pick = O.out[O.out.length - 1];
  for (const x of O.out) { if ((r -= x.p) < 0) { pick = x; break; } }
  const kind = h.advEvent.kind;
  h.advEvent = null;
  const said = [];
  if (pick.gear) {
    const item = heroItem(null, heroRollTier(HERO_DROPS.adv[kind] || HERO_DROPS.adv.short));
    if (h.bag.length < HERO_BAG) { h.bag.push(item); said.push(item.icon + " " + item.name); } else said.push("gear, but the bag was full");
  }
  if (pick.res) {
    const add = advEventScaled(pick.res);
    heroAfterFight(userId, h, { xp: 0, bounty: Object.assign({ wood: 0, stone: 0, metal: 0, food: 0 }, add), at: now, safe: true });
    said.push("+" + lootTotal(add) + " resources in the stash");
  }
  if (pick.xp) {
    const note = heroAfterFight(userId, h, { xp: advXp(kind, h.level) * pick.xp, at: now, safe: true });
    said.push("+" + note.xp + " xp" + (note.levelUp ? " · level " + note.levelUp : ""));
  }
  if (pick.hp) {
    heroSetHp(h, Math.max(1, heroHp(h, now) - pick.hp), now);
    said.push("−" + pick.hp + " health");
  }
  if (!said.length) said.push("nothing happened");
  heroSave(userId, h);
  return { text: E.icon + " " + O.label + ": " + said.join(", ") };
}

app.post("/api/adventure", requireLogin, (req, res) => {
  withColony(req, res, (s, tribe, colony) => {
    const now = Date.now();
    const b = req.body || {};
    const h = heroOf(req.user.id, now);
    if (!h) return "You have no commander";
    if (b.cancel) {
      if (!h.adv) return "Your commander is not on an adventure";
      // turns around and walks home empty-handed
      if (h.adv.cancelled) return "Your commander is already on its way home";
      const l = advLegs(h.adv.kind, h);
      const walked = Math.max(0, Math.min(l.back, now - h.adv.start));
      const back = h.adv.leaveAt && now >= h.adv.leaveAt ? Math.max(0, h.adv.until - now) : walked;
      h.adv.cancelled = true;
      h.adv.arriveAt = Math.min(h.adv.arriveAt || now, now);
      h.adv.leaveAt = now;
      h.adv.until = now + Math.max(1000, back);
      heroSave(req.user.id, h);
      return null;
    }
    const offer = h.advBoard.find((o) => o.id === String(b.id || ""));
    if (!offer) return "That adventure is gone";
    const kind = offer.kind;
    if (h.adv) return "Your commander is already on an adventure";
    if (h.hurtUntil > now) return "Your commander is still recovering";
    if (h.away || h.move) return "Your commander is busy";
    if (heroHp(h, now) <= ADVENTURES[kind].hp[1]*(b.route==="danger"&&!heroRule(h,"explorer",25)?1.6:.7)) return "Your commander needs more than " + ADVENTURES[kind].hp[1] + " health for this trip";
    heroSettle(h.home, now); // its Foreman production stops while it is away
    if (h.advBoard.length >= advBoardMax(h)) h.advSpawnAt = now + advSpawnMs(); // the next one starts spawning now
    h.advBoard = h.advBoard.filter((o) => o !== offer);
    const legs = advLegs(kind, h);
    h.adv = { kind, route:b.route==="danger"?"danger":"safe", start: now, arriveAt: now + legs.out, leaveAt: now + legs.out + legs.site, until: now + legs.out + legs.site + legs.back };
    heroSave(req.user.id, h);
    return null;
  });
});

function wikiAdventures() {
  return { board: ADV_BOARD, startN: ADV_START, spawnMs: advSpawnMs(), weights: ADV_WEIGHTS, xpLvl: Math.round(ADV_XP_LVL * 100), kinds: Object.keys(ADVENTURES).map((k) => ({ icon: ADVENTURES[k].icon, name: ADVENTURES[k].name, ms: advMs(k), walk: Math.round((ADV_WALK_MIN[k] * 60000) / MOVE_SPEED), xp: ADVENTURES[k].xp, xp10: advXp(k, 10), hp: ADVENTURES[k].hp, gear: Math.round(ADVENTURES[k].gear * 100), drops: HERO_DROPS.adv[k] })) };
}

// =====================================================================
//  v95 - player name suggestions (invite, sitters, messages ...)
// =====================================================================
app.get("/api/players/suggest", requireLogin, (req, res) => {
  const q = String(req.query.q || "").trim().slice(0, 20);
  if (!q) return res.json({ names: [] });
  const like = q.replace(/[\\%_]/g, (c) => "\\" + c) + "%";
  const names = db.prepare("SELECT username FROM users WHERE username LIKE ? ESCAPE '\\' AND banned = 0 ORDER BY LENGTH(username), username LIMIT 8").all(like).map((r) => r.username);
  res.json({ names });
});

// =====================================================================
//  v95 - 🪤 TRAPS, 💥 BOMBARDS and 🎩 TAKING OVER COLONIES
//
//  Traps: every level of the trap building holds TRAP_PER_LEVEL attacking
//  ground troops. They are caught before the fight and stay as prisoners
//  (their owner still feeds them) until the trapper lets them go or the
//  owner wins an attack on this colony, which frees them.
//
//  Bombards: like rams for the wall, the bombards that survive a won
//  attack knock levels off buildings and fields (the kind they aimed at
//  first, leftovers spill over). A level L needs BOMBARD_PER_LEVEL x L of
//  them. At 0 points a colony (never a main one) is wiped off the map.
//
//  Envoys: every envoy that survives a won attack lowers the colony's
//  loyalty by 20 to 30. At 0 the colony changes hands, if the attacker
//  has enough terra for one more colony. Loyalty grows back by itself.
//  A ⭐ main colony can never be taken.
// =====================================================================
const TRAP_PER_LEVEL = 10;
const BOMBARD_PER_LEVEL = 2;
const LOYALTY_MAX = 100;
const LOYALTY_HIT = [20, 30]; // per envoy
const LOYALTY_PER_DAY = 40; // per server day, a bit more with a higher HQ
const LOYALTY_AFTER = 25; // a fresh conquest starts here

addColumn("movements", "aim", "TEXT");
addColumn("movements", "orders", "TEXT");

// 📌 "first spotted": a defender can note the moment they noticed an incoming
// army. Only by hand, and only "now" - it's a memo for reading the pace, not
// a hint. depart_at is part of the key so a reused movement id never inherits
// an old note.
db.exec(`
  CREATE TABLE IF NOT EXISTS spotted (
    user_id INTEGER NOT NULL,
    move_id INTEGER NOT NULL,
    depart_at INTEGER NOT NULL,
    at INTEGER NOT NULL,
    PRIMARY KEY (user_id, move_id, depart_at)
  );
`);
function spottedAt(userId, m) {
  const r = db.prepare("SELECT at FROM spotted WHERE user_id = ? AND move_id = ? AND depart_at = ?").get(userId, m.id, m.depart_at);
  return r ? r.at : null;
}
app.post("/api/spot", requireLogin, (req, res) => {
  const id = parseInt((req.body || {}).id, 10);
  const now = Date.now();
  // only hostile armies that are really on their way to you
  const seen = movementsFor(req.user.id, now).find((x) => x.id === id && x.dir === "in" && x.pace);
  if (!seen) return res.status(400).json({ error: "That army isn't on its way to you" });
  const m = db.prepare("SELECT id, depart_at FROM movements WHERE id = ?").get(id);
  db.prepare("INSERT OR IGNORE INTO spotted (user_id, move_id, depart_at, at) VALUES (?, ?, ?, ?)").run(req.user.id, m.id, m.depart_at, now);
  // tidy up notes of armies that have long landed
  db.prepare("DELETE FROM spotted WHERE at < ?").run(now - 14 * 86400000);
  res.json({ ok: true });
});

// ---------- loyalty ----------
function loyaltyNow(s, now) {
  if (s.loyalty === undefined || s.loyalty === null) return LOYALTY_MAX;
  const grow = ((now - (s.loyaltyAt || now)) / serverDayMs()) * LOYALTY_PER_DAY * (1 + levelOf(s, "hq") / 20);
  return Math.min(LOYALTY_MAX, s.loyalty + Math.max(0, grow));
}
function setLoyalty(s, v, now) {
  if (v >= LOYALTY_MAX) {
    delete s.loyalty;
    delete s.loyaltyAt;
    return;
  }
  s.loyalty = Math.max(0, v);
  s.loyaltyAt = now;
}

// ---------- traps ----------
// Catches ground troops before the fight, per level - scaled like storage
// and carry capacity, so a trap building still holds a meaningful bite of
// an attacking army on a faster server, not just its original x1 handful.
function trapCap(s) {
  return Math.round(TRAP_PER_LEVEL * levelOf(s, "trap") * speedScale());
}
function trapUsed(s) {
  return (s.prisoners || []).reduce((n, p) => n + countUnits(p.t), 0);
}
// Before a fight: catch what fits. Changes "troops" and "survivors", not the owner's "away"
function trapArmy(def, att, troops, survivors, atkTribe, T) {
  if (def.userId === att.userId) return null;
  let free = trapCap(def.state) - trapUsed(def.state);
  if (free <= 0) return null;
  const keys = Object.keys(troops).filter((k) => troops[k] > 0 && atkTribe.units[k] && atkTribe.units[k].type === "ground");
  const ground = keys.reduce((n, k) => n + troops[k], 0);
  if (!ground) return null;
  const take = Math.min(free, ground);
  const caught = {};
  let got = 0;
  const rest = [];
  for (const k of keys) {
    const exact = (troops[k] * take) / ground;
    caught[k] = Math.floor(exact);
    got += caught[k];
    rest.push([k, exact - caught[k]]);
  }
  rest.sort((a, b) => b[1] - a[1]);
  for (let i = 0; got < take && i < rest.length; i++) {
    if (caught[rest[i][0]] < troops[rest[i][0]]) { caught[rest[i][0]]++; got++; }
  }
  for (const k of Object.keys(caught)) if (!caught[k]) delete caught[k];
  if (!got) return null;
  subtractTroops(troops, caught);
  subtractTroops(survivors, caught);
  def.state.prisoners = def.state.prisoners || [];
  let p = def.state.prisoners.find((x) => x.c === att.id);
  if (!p) {
    p = { u: att.userId, c: att.id, tribe: att.tribe, t: {}, at: T };
    def.state.prisoners.push(p);
  }
  addTroops(p.t, caught);
  return caught;
}
// Prisoners walk home to the colony they came from
function prisonersHome(def, p, T) {
  const home = db.prepare("SELECT id, x, y, user_id FROM colonies WHERE id = ?").get(p.c);
  if (!home || home.user_id !== p.u || !countUnits(p.t)) return false;
  const trip = travelMs(distance(home.x, home.y, def.x, def.y), slowestOf(p.t, tribeOf(p.tribe)));
  db.prepare(
    `INSERT INTO movements (attacker_id, target_id, mission, troops, depart_at, arrive_at, return_at, phase, next_at, target_kind, target_x, target_y)
     VALUES (?, ?, 'raid', ?, ?, ?, ?, 'back', ?, 'colony', ?, ?)`
  ).run(home.id, def.id, JSON.stringify(p.t), T - trip, T, T + trip, T + trip, def.x, def.y);
  return true;
}
// The owner won an attack here: all their prisoners are free
function freePrisoners(def, userId, T) {
  const mine = (def.state.prisoners || []).filter((p) => p.u === userId);
  if (!mine.length) return null;
  const freed = {};
  for (const p of mine) {
    if (prisonersHome(def, p, T)) addTroops(freed, p.t);
  }
  def.state.prisoners = def.state.prisoners.filter((p) => p.u !== userId);
  return countUnits(freed) ? freed : null;
}

function trapView(s, now) {
  const cap = trapCap(s);
  if (!cap && !(s.prisoners || []).length) return null;
  return {
    cap,
    used: trapUsed(s),
    prisoners: (s.prisoners || []).map((p, i) => {
      const c = db.prepare("SELECT name, x, y FROM colonies WHERE id = ?").get(p.c);
      return { i, owner: usernameOf(p.u) || "???", colony: c ? c.name : "???", x: c ? c.x : null, y: c ? c.y : null, at: p.at, units: unitList(p.t, tribeOf(p.tribe), null) };
    }),
  };
}

app.post("/api/traps/release", requireLogin, (req, res) => {
  withColony(req, res, (s, tribe, colony) => {
    const list = s.prisoners || [];
    const i = Number((req.body || {}).i);
    const pick = (req.body || {}).all ? list.slice() : list[i] ? [list[i]] : [];
    if (!pick.length) return "Nobody to let go";
    const now = Date.now();
    const def = { id: colony.id, x: colony.x, y: colony.y, state: s };
    for (const p of pick) prisonersHome(def, p, now);
    s.prisoners = list.filter((p) => pick.indexOf(p) < 0);
    return null;
  });
});

// ---------- bombards ----------
function bombardPower(troops, tribe, upgrades) {
  let p = 0;
  for (const k in troops) {
    const u = tribe.units[k];
    if (u && isBombard(u)) p += troops[k] * bonusOf(upgrades, k, tribe);
  }
  return p;
}
// Knock levels off buildings and fields. aim = a building or field type, or
// nothing for random targets. The aimed kind goes first (highest level
// first); bombards left over after a target is flattened move on to the next
// one, the aimed kind first, then at random. The HQ falls like any other
// building (without it nothing can be built until it is rebuilt).
// A colony that ends at 0 points is wiped off the map (see razeColony).
// 🏰 the Bastion only guards the ⭐ main colony it stands in
function bastionBonus(s) {
  return s && s.main ? Math.min(BASTION_MAX, levelOf(s, "bastion")) * BASTION_PER_LEVEL : 0;
}
function bombardHit(s, defTribe, power, aim, tough) {
  if (power <= 0) return null;
  const per = BOMBARD_PER_LEVEL * (1 + (tough || 0)); // bombards per level step
  const standing = () => {
    const list = [];
    s.buildings.forEach((b, i) => { if (b.type && b.level > 0) list.push({ kind: "building", i, type: b.type, level: b.level }); });
    s.fields.forEach((f, i) => { if (f.level > 0) list.push({ kind: "field", i, type: f.type, level: f.level }); });
    return list;
  };
  const first = standing();
  if (!first.length) return null;
  const missed = !!aim && !first.some((x) => x.type === aim);
  const hits = [];
  let left = power;
  for (let guard = 0; guard < 400 && left > 0; guard++) {
    const list = standing();
    const open = list; // the HQ falls like any other building
    if (!open.length) break;
    const aimed = aim ? open.filter((x) => x.type === aim).sort((a, b) => b.level - a.level) : [];
    const pick = aimed.length ? aimed[0] : open[Math.floor(Math.random() * open.length)];
    const floor = 0;
    if (left < per * pick.level) {
      // not enough for even one level here: the volley ends on this target
      if (!hits.length) hits.push({ pick, from: pick.level, to: pick.level });
      break;
    }
    const from = pick.level;
    let L = from;
    while (L > floor && left >= per * L) {
      left -= per * L;
      L -= 1;
    }
    if (pick.kind === "field") s.fields[pick.i].level = L;
    else {
      s.buildings[pick.i].level = L;
      if (L === 0 && !jobsOf(s).some((q) => q.kind === "building" && q.slot === pick.i)) s.buildings[pick.i] = { type: null, level: 0 };
    }
    hits.push({ pick, from, to: L });
    if (L > floor) break; // ran out partway down
  }
  if (!hits.length) return null;
  const view = hits.map((h) => {
    const n = defTribe.names[h.pick.type] || [h.pick.type, "🏠"];
    return { type: h.pick.type, name: n[0], icon: n[1], from: h.from, to: h.to };
  });
  // the first target stays on top (older reports only know that one)
  return Object.assign({}, view[0], { missed, hits: view, tough: Math.round((tough || 0) * 100) });
}

// 💥 A colony bombed down to 0 points is gone: off the map, for good. Its own
// armies have no home anymore, guests and anyone still on the way turn back,
// prisoners there walk free. A ⭐ main colony can fall too: the oldest colony
// left becomes the main one; with none left the player has to respawn.
function razeColony(colonyId, skipMoveId, T) {
  const c = loadColony(colonyId);
  if (!c) return false;
  const wasMain = !!c.state.main;
  const s = c.state;
  const def = { id: c.id, x: c.x, y: c.y, state: s };
  for (const p of s.prisoners || []) prisonersHome(def, p, T);
  // guests stationed here walk home the way they came
  db.prepare("UPDATE movements SET phase = 'back', return_at = ? + (arrive_at - depart_at), next_at = ? + (arrive_at - depart_at) WHERE target_id = ? AND target_kind = 'colony' AND phase = 'stay' AND id != ?").run(T, T, c.id, skipMoveId || 0);
  // anyone still on the way (attacks, help, merchants) turns around
  db.prepare("UPDATE movements SET phase = 'back', arrive_at = ?, return_at = 2 * ? - depart_at, next_at = 2 * ? - depart_at WHERE target_id = ? AND target_kind = 'colony' AND phase = 'out' AND id != ? AND attacker_id != ?").run(T, T, T, c.id, skipMoveId || 0, c.id);
  // this colony's own armies have no home anymore
  db.prepare("DELETE FROM movements WHERE attacker_id = ?").run(c.id);
  const z = zoneRow();
  if (z.holder_id === c.id) db.prepare("UPDATE zone SET holder_id = NULL, since = NULL, robots = ? WHERE id = 1").run(zoneRobots());
  for (const l of LANDMARKS) {
    const r = landmarkRow(l);
    if (r.holder_id === c.id) loseLandmark(l, null);
  }
  for (const t of ["market_offers", "build_asks", "build_hands", "crew_busy"]) {
    try { db.prepare("DELETE FROM " + t + " WHERE colony_id = ?").run(c.id); } catch (e) {}
  }
  db.prepare("DELETE FROM colonies WHERE id = ?").run(c.id);
  // ⭐ the main colony is gone: the oldest colony left takes over the role.
  // Nothing left at all: a fake player disappears, a real one has to respawn.
  const rest = coloniesOf(c.userId);
  if (wasMain && rest.length) {
    const next = rest[0];
    next.state.main = true;
    saveColony(next.id, next.state);
  }
  if (!rest.length && BOT_IDS.has(c.userId)) deleteUserCompletely(c.userId);
  return true;
}

// ---------- envoys ----------
function envoyHit(att, def, survivors, atkTribe, T) {
  const keys = Object.keys(survivors).filter((k) => atkTribe.units[k] && isEnvoy(atkTribe.units[k]) && survivors[k] > 0);
  const n = keys.reduce((x, k) => x + survivors[k], 0);
  if (!n) return null;
  if (att.userId === def.userId) return null; // your own colony is already yours
  if (def.state.main) return { main: true };
  const from = Math.round(loyaltyNow(def.state, T));
  let drop = 0;
  for (let i = 0; i < n; i++) drop += LOYALTY_HIT[0] + Math.floor(Math.random() * (LOYALTY_HIT[1] - LOYALTY_HIT[0] + 1));
  const to = Math.max(0, from - drop);
  const out = { from, to, envoys: n };
  if (to > 0) {
    setLoyalty(def.state, to, T);
    return out;
  }
  const count = coloniesOf(att.userId).length;
  const need = terraNeededFor(count);
  const terra = terraOf(att.userId, T);
  if (need === null || terra < need) {
    setLoyalty(def.state, 0, T);
    out.why = need === null ? "You already rule the most colonies a commander can handle." : "You need " + need + " terra to rule colony #" + (count + 1) + " (you have " + terra + ").";
    return out;
  }
  // the envoys stay and take charge
  const used = {};
  for (const k of keys) used[k] = survivors[k];
  subtractTroops(survivors, used);
  subtractTroops(att.state.away, used);
  out.took = true;
  return out;
}

// After the reports: the colony really changes hands
function takeOver(colonyId, newUserId, oldUserId, T) {
  const c = loadColony(colonyId);
  if (!c) return;
  const s = c.state;
  s.troops = {};
  s.away = {};
  for (const b in s.training) s.training[b] = [];
  s.queue = [];
  s.crewJob = null;
  s.labJob = null;
  s.smithJob = null;
  s.healJob = null;
  s.terraJob = null;
  s.wounded = {};
  s.hunger = 0;
  s.routes = [];
  delete s.main;
  // the new owner's own prisoners here are free right away
  if (s.prisoners) {
    const def = { id: c.id, x: c.x, y: c.y, state: s };
    for (const p of s.prisoners.filter((p) => p.u === newUserId)) prisonersHome(def, p, T);
    s.prisoners = s.prisoners.filter((p) => p.u !== newUserId);
  }
  setLoyalty(s, LOYALTY_AFTER, T);
  s.lastUpdate = T;
  saveColony(c.id, s);
  db.prepare("UPDATE colonies SET user_id = ? WHERE id = ?").run(newUserId, c.id);
  // the old owner's armies from here have no home anymore
  db.prepare("DELETE FROM movements WHERE attacker_id = ?").run(c.id);
  // guests and helpers on their way walk home
  db.prepare("UPDATE movements SET phase = 'back', return_at = ? + (arrive_at - depart_at), next_at = ? + (arrive_at - depart_at) WHERE target_id = ? AND target_kind = 'colony' AND phase = 'stay'").run(T, T, c.id);
  db.prepare("UPDATE movements SET phase = 'back', return_at = 2 * ? - depart_at, next_at = 2 * ? - depart_at WHERE target_id = ? AND target_kind = 'colony' AND phase = 'out' AND mission = 'reinforce'").run(T, T, c.id);
  for (const t of ["market_offers", "build_asks", "build_hands", "crew_busy"]) db.prepare("DELETE FROM " + t + " WHERE colony_id = ?").run(c.id);
  addNews("🎩 " + usernameOf(newUserId) + " took over " + c.name + " from " + (usernameOf(oldUserId) || "???") + "!", T, "zone");
}

function loyaltyView(s, now) {
  const v = Math.round(loyaltyNow(s, now));
  return { now: v, max: LOYALTY_MAX, main: !!s.main };
}

function wikiConquest() {
  return { trapPer: Math.round(TRAP_PER_LEVEL * speedScale()), bombardPer: BOMBARD_PER_LEVEL, bastionPer: BASTION_PER_LEVEL, bastionMax: BASTION_MAX, loyaltyHit: LOYALTY_HIT, loyaltyPerDay: LOYALTY_PER_DAY, loyaltyAfter: LOYALTY_AFTER, dayMs: serverDayMs() };
}

// =====================================================================
//  v96 - 🛬 THE LANDING (onboarding for new players, about 12-15 min)
//  One step at a time, every step is a real action in the game:
//  fields -> name -> storage -> more fields -> HQ -> barracks -> troops
//  -> map -> raid the wrecked lander -> alliance -> protection, goal,
//  terra -> the hand-over with three clear next goals.
//  Small rewards after every action. While the landing runs, short jobs
//  that keep the next step waiting can be finished for free.
//  Progress lives in users.firstday (JSON) as { onb: { i, off, done }, lander }.
// =====================================================================
// Free finishing scales from 3 minutes on ×1 to 1 minute on ×10.
const ONB_FREE_BASE_MS = 3 * 60000;
function freeFinishMs() {
  return onbFreeMs();
}
function onbFreeMs() {
  const sp = Math.max(1, BUILD_SPEED || 1);
  return Math.round(Math.min(ONB_FREE_BASE_MS, ONB_FREE_BASE_MS / Math.pow(sp, Math.log10(3))));
}
const LANDER_TRIP_MS = 30000; // the wreck lies right next door
const LANDER_LOOT = 250; // of every resource, always (the first raid is a sure win)
const ONB_SQUAD = 5; // the squad the guide hands over on a normal server
// the landing party: a few troops, as many as the speed of the server calls for
function onbSquadSize() {
  return Math.max(1, Math.round(ONB_SQUAD * speedScale()));
}
const ONB_KIT = 2000; // the parting gift: resources or troops worth that much

// What each step needs. done(s, ctx) = the player did it (a started job counts).
function onbFieldsUp(s) {
  return s.fields.filter((f, i) => f.level >= 1 || jobsOf(s).some((q) => q.kind === "field" && q.slot === i)).length;
}
function onbBuilt(s, type) {
  return levelOf(s, type) >= 1 || jobsOf(s).some((q) => q.kind === "building" && (q.type === type || (s.buildings[q.slot] && s.buildings[q.slot].type === type)));
}
function onbHqNeed(tribeKey) {
  const r = tribeBuilding(tribeKey, "barracks").requires || {};
  return r.hq || 0;
}
function onbHqPlanned(s) {
  let lv = levelOf(s, "hq");
  for (const q of jobsOf(s)) if (q.kind === "building" && s.buildings[q.slot] && s.buildings[q.slot].type === "hq") lv = Math.max(lv, q.targetLevel || lv);
  return lv;
}
// The landing: everything that needs no army comes first (short jobs, the map,
// the raid on the wrecked lander with the squad that survived the crash). The
// army - HQ 3, barracks, training - waits until the end, where a real build
// time no longer blocks the guide.
const ONB_STEPS = [
  { key: "welcome", info: true },
  { key: "field", reward: 80, done: (s) => onbFieldsUp(s) >= 1 },
  { key: "res", info: true },
  { key: "name", reward: 60, done: (s, c) => !/^New Colony$/.test(c.name) },
  { key: "store", reward: 100, done: (s) => onbBuilt(s, "warehouse") },
  { key: "fields3", reward: 120, done: (s) => onbFieldsUp(s) >= 3 },
  { key: "cap", info: true },
  { key: "squad", info: true, squad: true },
  { key: "map", info: true },
  { key: "raid", done: (s, c, t, f) => !!(f.lander && f.lander.sent) },
  { key: "loot", done: (s, c, t, f) => !!(f.lander && f.lander.done) },
  { key: "scorp", done: (s, c, t, f) => !!(f.scorp && f.scorp.won) },
  { key: "ally", reward: 200, skip: true, done: (s, c) => !!allianceOf(c.userId) },
  { key: "protect", info: true },
  { key: "goal", info: true },
  { key: "terra", info: true },
  { key: "hq", reward: 150, done: (s, c) => onbHqPlanned(s) >= onbHqNeed(c.tribeKey) },
  { key: "barracks", reward: 150, done: (s) => onbBuilt(s, "barracks") },
  // the only step that cannot be done by queueing it: "Later" ends the landing without it
  { key: "train", reward: 150, skip: true, done: (s) => (s.training.barracks || []).length > 0 },
  { key: "end", final: true },
];

function onbState(userId) {
  const st = firstDayState(userId);
  if (!st) return null;
  st.f.onb = st.f.onb || null;
  return st;
}
function onbSave(userId, f) {
  db.prepare("UPDATE users SET firstday = ? WHERE id = ?").run(JSON.stringify(f), userId);
}
// Does this player get the landing? New accounts yes; veterans who finished the old tour no.
function onbActive(userId, st) {
  if (!st) return false;
  const f = st.f;
  if (f.onb) return !f.onb.off && !f.onb.done;
  if (f.path || f.hidden) return false;
  const u = db.prepare("SELECT tutorial, created_at FROM users WHERE id = ?").get(userId);
  if (!u || u.tutorial) return false;
  return Date.now() - u.created_at < 7 * 86400000;
}
// The wrecked lander: one free, flat tile right next to the first colony
function onbLander(userId, f, colony) {
  if (f.lander) return f.lander;
  for (let r = 1; r <= 4; r++) {
    const spots = [];
    for (let dx = -r; dx <= r; dx++) for (let dy = -r; dy <= r; dy++) {
      if (Math.max(Math.abs(dx), Math.abs(dy)) !== r) continue;
      const x = colony.x + dx, y = colony.y + dy;
      if (!canSettle(x, y) || landmarkAtXY(x, y) || meteorAt(x, y, Date.now())) continue;
      spots.push({ x, y });
    }
    if (spots.length) {
      f.lander = Object.assign(spots[Math.floor(Math.random() * spots.length)], { sent: 0, done: 0 });
      return f.lander;
    }
  }
  return null;
}
function landerOf(userId) {
  const st = firstDayState(userId);
  return st && st.f.lander && !st.f.lander.sent ? st.f.lander : null;
}

// The job the current step is waiting for, so the guide can show its timer
function onbJobType(s, q) {
  if (!q || q.kind !== "building") return "";
  return q.type || (s.buildings[q.slot] && s.buildings[q.slot].type) || "";
}
// Only the two steps that really are gated by a building: everything else is
// done the moment the player queues it, so a timer there would be noise.
const ONB_WAIT_BUILD = { barracks: ["hq", "barracks"], train: ["hq", "barracks"] };
function onbWaitJob(s, key, now, f) {
  const want = ONB_WAIT_BUILD[key];
  if (want) {
    // the queue and the commander's crew both count
    const live = (s.crewJob ? [s.queue[0], s.crewJob] : [s.queue[0]]).filter((q) => q && q.finishAt);
    const job = live.find((q) => want.includes(onbJobType(s, q)));
    if (job) return { kind: "build", left: Math.max(0, job.finishAt - now) };
  }
  if (key === "train") {
    const o = (s.training.barracks || [])[0];
    if (o) return { kind: "train", left: Math.max(0, (o.nextAt || now) - now) + Math.max(0, o.remaining - 1) * o.eachMs };
  }
  return null;
}

function onboardingView(user, colony, now) {
  const st = onbState(user.id);
  if (!onbActive(user.id, st)) return null;
  const f = st.f;
  // only in the first colony
  const first = db.prepare("SELECT id FROM colonies WHERE user_id = ? ORDER BY id LIMIT 1").get(user.id);
  if (!first || first.id !== colony.id) return null;
  const i = f.onb ? f.onb.i : 0;
  const step = ONB_STEPS[Math.min(i, ONB_STEPS.length - 1)];
  const s = colony.state;
  const tribe = tribeOf(colony.tribe);
  const ctx = { name: colony.name, userId: user.id, tribeKey: colony.tribe };
  const out = { i, n: ONB_STEPS.length, key: step.key, info: !!step.info, final: !!step.final, skip: !!step.skip, reward: (step.reward || 0) };
  out.done = step.done ? !!step.done(s, ctx, tribe, f) : false;
  // 🎁 what the rest of the landing still pays (of every resource), plus the gift at the end
  out.left = Math.round(ONB_STEPS.slice(i).reduce((n, x) => n + (x.reward || 0), 0));
  out.wait = onbWaitJob(s, step.key, now, f);
  out.hqNeed = onbHqNeed(colony.tribe);
  out.squad = onbSquadSize();
  if (["map", "raid", "loot"].includes(step.key)) {
    const L = f.lander;
    if (L) {
      out.lander = { x: L.x, y: L.y, sent: !!L.sent, done: !!L.done, loot: LANDER_LOOT };
      if (L.sent && !L.done) {
        const m = db.prepare("SELECT arrive_at FROM movements WHERE attacker_id = ? AND target_kind = 'lander' AND phase = 'out'").get(colony.id);
        out.lander.arriveAt = m ? m.arrive_at : 0;
      }
      if (L.report) out.lander.report = L.report;
    }
  }
  if (step.key === "scorp" && f.scorp) out.scorp = { at: f.scorp.at, won: !!f.scorp.won, report: f.scorp.report || 0, n: f.scorp.n };
  const unit = firstDayUnit(tribe);
  if (unit) out.unit = { key: unit.key, icon: unit.icon, name: unit.name };
  if (step.final) {
    const per = Math.round(ONB_KIT / 4);
    out.summary = {
      name: colony.name,
      fields: onbFieldsUp(s),
      buildings: s.buildings.filter((b) => b.type && b.level > 0).length,
      troops: countUnits(s.troops) + countUnits(s.away),
      raided: !!(f.lander && f.lander.done),
      alliance: !!allianceOf(user.id),
      builder: { wood: per, stone: per, metal: per, food: per },
      raider: unit ? { icon: unit.icon, name: unit.name, count: unit.count } : null,
    };
  }
  return out;
}

app.post("/api/onboard", requireLogin, (req, res) => {
  withColony(req, res, (s, tribe, colony) => {
    const b = req.body || {};
    const now = Date.now();
    const st = onbState(req.user.id);
    if (!onbActive(req.user.id, st)) return "The landing is over";
    const f = st.f;
    f.onb = f.onb || { i: 0, at: now };
    const step = ONB_STEPS[f.onb.i];
    const ctx = { name: colony.name, userId: req.user.id, tribeKey: colony.tribe };
    const act = String(b.do || "");
    if (act === "off") {
      // skip the whole landing (veterans)
      f.onb.off = now;
      db.prepare("UPDATE users SET tutorial = 1 WHERE id = ?").run(req.user.id);
    } else if (act === "next" || act === "skip") {
      if (step.final) return "Pick your gift first";
      if (act === "skip" && !step.skip) return "This step can't be skipped";
      if (act === "next" && !step.info && !(step.done && step.done(s, ctx, tribe, f))) return "Not done yet";
      if (act === "next" && step.reward) {
        const r = step.reward;
        if (!questInventoryReward(req.user.id, { wood: r, stone: r, metal: r, food: r })) return "Commander inventory unavailable. Try again.";
        req.extra = { onbReward: r };
      }
      f.onb.i++;
      // steps that are already done (an HQ that is high enough, ...) are passed right away, without reward
      while (f.onb.i < ONB_STEPS.length - 1) {
        const nx = ONB_STEPS[f.onb.i];
        if (nx.key === "hq" && levelOf(s, "hq") >= onbHqNeed(colony.tribe)) { f.onb.i++; continue; }
        break;
      }
      const now2 = ONB_STEPS[f.onb.i];
      if (["map", "raid"].includes(now2.key)) onbLander(req.user.id, f, colony);
      if (now2.key === "scorp" && !f.scorp) scorpSchedule(f, colony, now);
      // 🪖 the landing party: the troops that walked out of the wreck, there the
      // moment the guide says so - enough for the first raid, never a whole army
      if (now2.squad && !f.squadGiven) {
        const unit = firstDayUnit(tribe);
        if (unit) {
          const n = onbSquadSize();
          s.troops[unit.key] = (s.troops[unit.key] || 0) + n;
          f.squadGiven = now;
          req.extra = Object.assign(req.extra || {}, { onbSquad: n });
          update(s, tribe, now);
        }
      }
    } else if (act === "finish") {
      if (!step.final) return "Not yet";
      const per = Math.round(ONB_KIT / 4);
      const unit = firstDayUnit(tribe);
      if (b.kit === "raider" && unit) s.troops[unit.key] = (s.troops[unit.key] || 0) + unit.count;
      else refund(s, { wood: per, stone: per, metal: per, food: per });
      f.onb.done = now;
      f.path = b.kit === "raider" ? "raider" : "builder"; // the old first-day card stays away too
      db.prepare("UPDATE users SET tutorial = 1 WHERE id = ?").run(req.user.id);
    } else return "Unknown step";
    onbSave(req.user.id, f);
    return null;
  });
});

// ---------- 🦂 the first defense ----------
// Right after the first raid a small pack of Dust Scorpions comes for the
// snacks. It is scripted to lose against anything the colony has, so the
// new player reads their first defense report while nothing is at stake.
const SCORP_MS = 90000; // they arrive 90 seconds after the guide says so
const SCORP_PACK = 4;
function scorpSchedule(f, colony, now) {
  let from = null;
  for (let r = 3; r <= 6 && !from; r++) {
    const ang = Math.random() * Math.PI * 2;
    from = { x: Math.round(colony.x + Math.cos(ang) * r), y: Math.round(colony.y + Math.sin(ang) * r) };
  }
  f.scorp = { at: now + SCORP_MS, start: now, colony: colony.id, x: from.x, y: from.y, n: SCORP_PACK };
  f.scorpPending = 1;
}
function scorpIncoming(userId, now) {
  const st = firstDayState(userId);
  const S = st && st.f.scorp;
  if (!S || S.won) return null;
  const c = db.prepare("SELECT name FROM colonies WHERE id = ?").get(S.colony);
  return {
    id: "scorp", dir: "in", type: "raid", mission: "raid", name: "Dust Scorpions", owner: "Wild monsters",
    x: S.x, y: S.y, to: c ? c.name : "", toId: S.colony, units: null, merchants: 0, loot: null,
    startAt: S.start, endAt: S.at, pace: null, cloaked: false, spottedAt: null, canRecall: false, monsters: true,
  };
}
function scorpTick(now) {
  for (const u of db.prepare("SELECT id FROM users WHERE firstday LIKE '%\"scorpPending\":1%'").all()) {
    const st = firstDayState(u.id);
    const S = st && st.f.scorp;
    if (!S || S.won) continue;
    if (S.at > now) continue;
    const colony = loadColony(S.colony);
    if (!colony) { delete st.f.scorpPending; S.won = now; db.prepare("UPDATE users SET firstday = ? WHERE id = ?").run(JSON.stringify(st.f), u.id); continue; }
    const tribe = tribeOf(colony.tribe);
    update(colony.state, tribe, S.at);
    const home = Object.assign({}, colony.state.troops);
    const d = defenseOf(home, tribe, colony.state.upgrades);
    addDefense(d, militiaOf(colony.state));
    // scripted: the pack always hits far below the defense
    const A = Math.max(1, Math.round(Math.min(d.g, S.n * 10) * 0.3));
    const pack = { scorpion: S.n };
    const rid = addReport(u.id, S.at, "🛡️", "Scorpions fought off", {
      mission: "raid",
      side: "defender",
      attackerWins: false,
      attack: A, defense: Math.round(d.g), luck: 0, groundAtk: A, airAtk: 0, defG: Math.round(d.g), defA: Math.round(d.a), airShare: 0, combo: 0,
      wall: 0,
      loot: null,
      attacker: { name: "Dust Scorpions", owner: "Wild monsters", x: S.x, y: S.y, units: monsterList(pack, pack) },
      defender: Object.assign({}, colonyInfo(colony), { units: unitList(home, tribe, {}) }),
      support: [],
      flavor: "They came for the snacks. They left with sore tails. Nobody on your side got a scratch.",
      first: true,
    });
    saveColony(colony.id, colony.state);
    S.won = now;
    if (rid) S.report = rid;
    delete st.f.scorpPending;
    db.prepare("UPDATE users SET firstday = ? WHERE id = ?").run(JSON.stringify(st.f), u.id);
  }
}
setInterval(() => { try { scorpTick(Date.now()); } catch (e) { console.error("scorp", e); } }, 2000);
setInterval(() => { try { forecastTick(Date.now()); } catch (e) { console.error("forecast", e); } }, 5000);

// ---------- the lander on the map, the raid and its report ----------
function landerTile(userId, x0, x1, y0, y1) {
  const L = landerOf(userId);
  if (!L || L.x < x0 || L.x > x1 || L.y < y0 || L.y > y1) return null;
  const res = { wood: LANDER_LOOT, stone: LANDER_LOOT, metal: LANDER_LOOT, food: LANDER_LOOT };
  return { x: L.x, y: L.y, res, total: LANDER_LOOT * 4, until: Date.now() + 30 * 86400000, lander: true };
}
function landerSent(userId) {
  const st = firstDayState(userId);
  if (!st || !st.f.lander) return;
  st.f.lander.sent = Date.now();
  db.prepare("UPDATE users SET firstday = ? WHERE id = ?").run(JSON.stringify(st.f), userId);
}
function resolveLander(m) {
  const T = m.arrive_at;
  const cache = colonyCache(T);
  const att = cache.get(m.attacker_id);
  if (!att) { db.prepare("DELETE FROM movements WHERE id = ?").run(m.id); return; }
  const tribe = tribeOf(att.tribe);
  const troops = JSON.parse(m.troops);
  const loot = { wood: LANDER_LOOT, stone: LANDER_LOOT, metal: LANDER_LOOT, food: LANDER_LOOT };
  addStats(att.userId, { loot: lootTotal(loot) });
  const rid = addReport(att.userId, T, "🛸", "Lander raided: cargo yours!", {
    mission: "lander",
    side: "attacker",
    attacker: Object.assign({}, colonyInfo(att), { units: unitList(troops, tribe, null) }),
    defender: { name: "Wrecked lander", x: m.target_x, y: m.target_y },
    loot,
    flavor: "Inside: four crates, one confused robot vacuum and a note saying “Do not open”. Your troops opened it.",
  });
  const st = firstDayState(att.userId);
  if (st && st.f.lander) {
    st.f.lander.done = T;
    if (rid) st.f.lander.report = rid;
    db.prepare("UPDATE users SET firstday = ? WHERE id = ?").run(JSON.stringify(st.f), att.userId);
  }
  cache.saveAll();
  finishArrival(m, troops, loot);
}

