function costChips(cost, res, timeMs) {
  var h = '<div class="costs">';
  var canUseInventory = false;
  var missing = {};
  RES.forEach(function (k) { missing[k] = Math.max(0, Math.ceil((cost[k] || 0) - ((res && res[k]) || 0))); });
  var missingData = RES.filter(function (k) { return missing[k] > 0; }).map(function (k) { return k + ":" + missing[k]; }).join(",");
  RES.forEach(function (k) {
    if (cost[k] > 0) {
      var lack = res && res[k] < cost[k];
      var HS = lack && data && data.hero && data.hero.stash ? data.hero.stash : null;
      var can = HS && HS[k] > 0 ? Math.min(Math.ceil(cost[k] - res[k]), HS[k], data.hero.stashRoom ? data.hero.stashRoom[k] : HS[k]) : 0;
      if (can > 0) canUseInventory = true;
      if (can > 0) h += '<button type="button" class="chip lack stashfill" data-stash-add="' + missingData + '" title="Add missing resources from your commander’s inventory">' + ico(k, "sm") + " " + cost[k] + " <i>📦+" + shortNum(can) + "</i></button>";
      else h += '<span class="chip' + (lack ? " lack" : "") + '" title="' + RES_NAME[k] + '">' + ico(k, "sm") + " " + cost[k] + "</span>";
    }
  });
  if (timeMs !== undefined) h += '<span class="chip time">' + ico("hourglass", "sm") + " " + fmt(timeMs) + "</span>";
  h += "</div>";
  if (canUseInventory && data && data.onboarding) {
    h += '<p class="hint">Short on resources? Tap <b>📦+</b> above to open your commander inventory. Review the prefilled amount and select <b>Transfer selected</b>, then start the build.</p>';
  }
  return h;
}

// ---------- the fun bits in the header ----------
(function () {
  var sky = document.getElementById("sky");
  for (var i = 0; i < 14; i++) {
    var d = document.createElement("div");
    d.className = "dust";
    d.style.top = Math.round(35 + Math.random() * 60) + "%";
    d.style.animationDuration = Math.round(8 + Math.random() * 14) + "s";
    d.style.animationDelay = "-" + Math.round(Math.random() * 20) + "s";
    sky.appendChild(d);
  }
  var tag = document.getElementById("tag");
  var n = Math.floor(Math.random() * TAGLINES.length);
  function nextTag() {
    tag.textContent = trStr(TAGLINES[n % TAGLINES.length]);
    n++;
    tag.classList.remove("pop");
    void tag.offsetWidth; // restart the pop animation
    tag.classList.add("pop");
  }
  nextTag();
  setInterval(nextTag, 7000);
  tag.addEventListener("click", nextTag);
})();

var JOKES = NEWS.slice().sort(function () { return Math.random() - 0.5; });
var newsKey = "";

var pulseNow = null; // 🌍 how busy Mars is (from /api/colony)
var gazetteNow = []; // 📰 real headlines of the day
function newsTicker(live) {
  var h = '<div class="news"><span class="label">📰 ' + trStr("News") + '</span><div class="scroll">';
  var now = serverNow();
  if (pulseNow) {
    var P = pulseNow;
    if (curLang() === "en") h += '<span class="live pulse">🌍 ' + P.online + (P.online === 1 ? " colonist" : " colonists") + " online · ⚔️ " + P.fights + (P.fights === 1 ? " fight" : " fights") + " in the last hour" + (P.settled ? " · 🏳️ " + P.settled + " new " + (P.settled === 1 ? "colony" : "colonies") + " today" : "") + "</span>";
    else h += '<span class="live pulse">🌍 ' + trStr("Colonists online: " + P.online) + " · ⚔️ " + trStr("Fights in the last hour: " + P.fights) + (P.settled ? " · 🏳️ " + trStr("New colonies today: " + P.settled) : "") + "</span>";
  }
  (live || []).forEach(function (n) {
    var info = trf("{0} ago", shortTime(now - n.at)) + (n.until ? " · " + trf("{0} left", shortTime(n.until - now)) : "");
    h += '<span class="live">🔴 ' + esc(trStr(n.text)) + " <small>(" + info + ")</small></span>";
  });
  // 📰 the Gazette: real headlines first, a few jokes in between
  gazetteNow.forEach(function (g) { h += '<span class="gz">' + g.icon + " " + esc(trStr(g.text)) + "</span>"; });
  (gazetteNow.length >= 3 ? JOKES.slice(0, 3) : JOKES).forEach(function (n) { h += "<span>✦ " + esc(trStr(n)) + "</span>"; });
  h += '</div><span class="nclock" title="Server time: the same for every player"><i>SERVER<br>TIME</i><b id="clock">--:--:--</b></span>';
  return h + "</div>";
}
document.getElementById("newsbar").innerHTML = newsTicker([]);
setTimeout(function () { if (typeof tickerPace === "function") tickerPace(); }, 300);

// Real events (like a new ruler of the Landing Zone) go to the front
function updateNews(list) {
  // redraw when the news change - and once a minute for the times
  var key = gazetteNow.map(function (g) { return g.text; }).join("|") + (list || []).map(function (n) { return n.id + ":" + n.until; }).join(",") + "@" + Math.floor(serverNow() / 60000) + (pulseNow ? "|" + pulseNow.online + "," + pulseNow.fights + "," + pulseNow.settled : "");
  if (key === newsKey) return;
  newsKey = key;
  document.getElementById("newsbar").innerHTML = newsTicker(list);
  tickerPace();
  lastClock = "";
}
// a steady, readable speed whatever the length of the news (about 45 px per second)
function tickerPace() {
  var sc = document.querySelector("#newsbar .scroll");
  if (!sc) return;
  var w = sc.scrollWidth || 0;
  if (w > 0) sc.style.animationDuration = Math.max(40, Math.round(w / 45)) + "s";
}

