  ['warehouse','granary'].forEach(function(type){var resource=type==='granary'?'food':'wood';if(d.res[resource]>(d.capacity&&d.capacity[resource]||Infinity)*.85){var b=d.buildings.find(function(b){return b.type===type;});if(b)choices.push({label:'Storage almost full: '+b.name,go:'lot:'+b.slot});}});
  var nx=d.retention&&d.retention.next;
