    cards.push(wkCard("relic", "🏆", "Relic Hunt", wkP("The first team (alliance or lone player) holding <b>" + W.relic.count + " landmarks</b> at the same time for <b>" + W.relic.hours + " h</b> in a row wins a permanent badge.")));
