function wkDur(ms) {
  var s = Math.round(ms / 1000);
  if (s < 90) return s + " s";
  if (s < 5400) return Math.round(s / 60) + " min";
  var hrs = s / 3600;
  return (hrs < 10 ? Math.round(hrs * 10) / 10 : Math.round(hrs)) + " h";
}
