// ---------- 🏗️ buildings: overview, a tap opens all levels ----------
function wikiBuildings(W) {
  var cards = [];
  if (!wiki.bopen || !wkBT(W)[wiki.bopen]) wiki.bopen = "hq";
  var key = wiki.bopen;
  var b = W.buildings.filter(function (x) { return x.key === key; })[0];
  // every tribe builds a little differently
  var tr = wkTribe(W, wiki.tribe);
  var h = '<div class="wk-tribes">' + W.tribes.map(function (x) { return '<button class="' + (x.key === tr.key ? "on" : "") + '" data-wiki-tribe="' + x.key + '">' + x.icon + " " + x.name + "</button>"; }).join("") + "</div>";
  // every building as a chip: one tap shows its table
  h += '<div class="wk-pick">' + W.buildings.map(function (x) {
    var n = wkTribe(W, wiki.tribe).names[x.key];
    return '<button class="' + (x.key === key ? "on" : "") + '" data-wiki-b="' + x.key + '"><span>' + (n ? n.icon : "🏗️") + "</span>" + esc(n ? n.name : x.key) + "</button>";
  }).join("") + "</div>";
  // phones: one quick dropdown instead of the big grid
  h += '<select class="wk-in wk-bsel" data-wiki-bsel="1">' + W.buildings.map(function (x) { return '<option value="' + x.key + '"' + (x.key === key ? " selected" : "") + ">" + wkBName(W, x.key) + "</option>"; }).join("") + "</select>";
  h += '<div class="wk-bhead"><h5>' + wkBName(W, key) + "</h5>";
  h += '<div class="wk-facts"><span>🔓 Needs: ' + wkNeeds(W, wkBD(W, b).requires) + "</span><span>⬆️ Max level " + b.max + "</span>" + (b.multi ? "<span>➕ You can build more than one</span>" : "") + "</div></div>";
  h += wkP(esc(wkBD(W, b).info)) + perkChips(tr.bperks ? tr.bperks[key] : null) + wkLevelTable(W, key);
  var c = wkCard("b-detail", "🏗️", "Buildings", h);
  cards.push(c);
  var list = W.buildings.map(function (x) { var r1 = wkBT(W)[x.key][0]; return { key: x.key, name: wkBName(W, x.key), needs: wkNeedsShort(W, wkBD(W, x).requires), max: x.max, cost: wkSum(r1.cost), time: r1.ms / 1000, multi: x.multi }; });
  var sel = -1;
  list.forEach(function (x, i) { if (x.key === key) sel = i; });
  cards.push(wkCard("ball", "🔓", "What unlocks what", kt({
    head: ["Building", "Needs", "Max", "Σ Lv 1", "⏱️ Lv 1"],
    left: 2,
    rows: list.map(function (x) { return ["<b>" + x.name + "</b>" + (x.multi ? " ➕" : ""), x.needs, x.max, wkN(x.cost), fmt(x.time * 1000)]; }),
    rowAttr: function (i) { return 'data-wiki-b="' + list[i].key + '"'; },
    sel: sel,
    click: true,
  }) + wkNote("Tap a row to show its levels above. ➕ = you can build more than one. Resource fields: 🌾 Economy.")));
  cards.push(wkFormulas(W, "building"));
  return cards;
}
// The level table of one building or field: every level with cost, time and effect
function wkLevelTable(W, key) {
  var F = W.formulas;
  var L = wkt.lv;
  var field = key.indexOf("field-") === 0;
  var rows = field ? W.tables.fields[key.slice(6)] : wkBT(W)[key];
  var speed = wkSpeedAt(F.hq, L.hq) / (1 + L.builders * F.ally.builders);
  var h = '<div class="wk-lvopts"><label>HQ ' + wkSel("lv.hq", wkLevels(20, 1), L.hq) + "</label><label>🏗️ Guild " + wkSel("lv.builders", wkLevels(W.alliance.maxLevel), L.builders) + '</label><button class="wk-tg' + (wiki.cum ? " on" : "") + '" data-wiki-cum="1">Σ so far</button></div>';
  var tot = { wood: 0, stone: 0, metal: 0, food: 0 };
  var tms = 0;
  var body = rows.map(function (r) {
    RES.forEach(function (k) { tot[k] += r.cost[k]; });
    tms += r.ms * speed;
    var c = wiki.cum ? tot : r.cost;
    var t = wiki.cum ? tms : r.ms * speed;
    var lv = r.level + (field && r.level > W.fields.max ? " ⭐" : "");
    var prev = r.level > 1 ? rows[r.level - 2].prod : 0;
    // the most looked-up things first: effect, total, time - the single resources after
    var main = ["<b>" + wkN(wkSum(c)) + "</b>", fmt(t)];
    if (field) return [lv, "<b>" + wkN(r.prod) + "</b>", r.level > 1 ? "+" + wkN(r.prod - prev) : "–"].concat(main, resCells(c), [(r.level > 1 ? (Math.round((wkSum(r.cost) / Math.max(1, r.prod - prev)) * 10) / 10) + " h" : "–")]);
    return [lv, esc(r.effect)].concat(main, resCells(c));
  });
  var sumRow = ["<b>" + wkN(wkSum(tot)) + "</b>", fmt(tms)].concat(resCells(tot));
  h += kt({
    head: field ? ["Lv", "/h", "+/h", "Σ", "⏱️"].concat(RES_HEAD, ["Pays back"]) : ["Lv", "Effect", "Σ", "⏱️"].concat(RES_HEAD),
    left: field ? 1 : 2,
    rows: body,
    cls: "lv full",
    foot: field ? ["Σ", "", ""].concat(sumRow, [""]) : ["Σ", ""].concat(sumRow),
  });
  h += wkNote((wiki.cum ? "Σ so far: what all levels up to this one cost together. " : "") + "Times with HQ " + L.hq + (L.builders ? " and Builders’ Guild " + L.builders : "") + "." + (field ? " ⭐ = main colony only. Pays back = hours of the extra production until the upgrade has paid for itself." : ""));
  return h;
}

// ---------- ⚔️ troops: one table per tribe, three views, sortable ----------
var WK_VIEWS = [["stats", "📊 Stats"], ["costs", "💰 Costs"], ["value", "⚖️ Value"]];
function wikiTroops(W) {
  var t = wkTribe(W, wiki.tribe);
  var h = '<div class="wk-tribes">' + W.tribes.map(function (x) { return '<button class="' + (x.key === t.key ? "on" : "") + '" data-wiki-tribe="' + x.key + '">' + x.icon + " " + x.name + "</button>"; }).join("") + "</div>";
  h += '<div class="wk-tribes wk-views">' + WK_VIEWS.map(function (v) { return '<button class="' + (wiki.view === v[0] ? "on" : "") + '" data-wiki-view="' + v[0] + '">' + v[1] + "</button>"; }).join("") + "</div>";
  var per = function (u, v) { return Math.round((v / Math.max(1, wkSum(u.cost))) * 1000); };
  var cols;
  if (wiki.view === "costs") {
    cols = [
      ["🪵", function (u) { return u.cost.wood; }, "w"], ["🪨", function (u) { return u.cost.stone; }, "s"], ["🔩", function (u) { return u.cost.metal; }, "m"], ["🥔", function (u) { return u.cost.food; }, "f"],
      ["Σ", function (u) { return wkSum(u.cost); }, "sum"], ["⏱️", function (u) { return u.time; }, "time", function (v) { return fmt(v * 1000); }],
      ["🏗️", function (u) { return u.level; }, "blv"], ["🔬", function (u) { return u.lab; }, "lab"],
    ];
  } else if (wiki.view === "value") {
    cols = [
      ["⚔️/1k", function (u) { return per(u, u.atk); }, "va"], ["🛡️/1k", function (u) { return per(u, u.defG); }, "vg"], ["🎯/1k", function (u) { return per(u, u.defA); }, "vd"],
      ["🎒/1k", function (u) { return per(u, u.carry); }, "vc"], ["⚔️/🥔", function (u) { return Math.round(u.atk / Math.max(1, u.upkeep)); }, "vf"],
    ];
  } else {
    cols = [
      ["⚔️", function (u) { return u.atk; }, "atk"], ["🛡️", function (u) { return u.defG; }, "defG"], ["🎯", function (u) { return u.defA; }, "defA"],
      ["💨", function (u) { return u.speed; }, "speed"], ["🎒", function (u) { return u.carry; }, "carry"], ["🥔", function (u) { return u.upkeep; }, "upkeep", function (v) { return eatTxt(v, true); }],
    ];
  }
  var list = t.units.slice();
  var sc = cols.filter(function (c) { return c[2] === wiki.sort; })[0];
  if (sc) list.sort(function (a, b) { return wiki.desc ? sc[1](b) - sc[1](a) : sc[1](a) - sc[1](b); });
  var rows = [];
  var sel = -1;
  list.forEach(function (u) {
    var key = t.key + ":" + u.key;
    if (wiki.open === key) sel = rows.length;
    rows.push(['<span class=\\"kt-u\\">' + u.icon + " <b>" + esc(trStr(u.name)) + "</b><small>" + wkKind(u) + "</small>" + (u.trait ? "<small>" + u.trait.icon + " " + esc(trStr(u.trait.name)) + ": " + esc(trStr(u.trait.text)) + "</small>" : "") + "</span>"].concat(cols.map(function (c) { var v = c[1](u); return c[3] ? c[3](v) : wkN(v); })));
    rows[rows.length - 1].key = key;
    if (wiki.open === key) rows.push({ full: wikiUnit(W, t, u) });
  });
  h += kt({
    head: ["Unit"].concat(cols.map(function (c) { return c[0]; })),
    sortable: [null].concat(cols.map(function (c) { return c[2]; })),
    rows: rows,
    sel: sel,
    cls: "troops",
    click: true,
    rowAttr: function (i) { return 'data-wiki-unit="' + rows[i].key + '"'; },
  });
  var legend = wiki.view === "costs" ? "Price, training time (training building level 1), 🏗️ building level and 🔬 lab level needed." : wiki.view === "value" ? "What 1000 resources of this unit give you. ⚔️/🥔 = attack per food per hour." : "⚔️ attack · 🛡️ Infantry defense · 🎯 Air defense · 💨 tiles/h · 🎒 loot · 🥔 food eaten per hour.";
  h += wkNote(legend + " Tap a header to sort, a unit for research and upgrades.");
  h += wkNote(esc(trStr(t.desc)) + " " + trStr("Tribe advantages: 🚀 Basics → The three tribes."));
  return h;
}
function wikiUnit(W, t, u) {
  var F = W.formulas;
  var b = t.names[u.building];
  var lab = t.names.lab;
  var wp = t.names.weaponry;
  var h = '<div class="wk-ud"><p class="wk-q">“' + esc(u.quote || "") + "”</p>";
  if (u.trait) h += '<p class="wk-trait"><span class="tchip">' + u.trait.icon + " " + esc(u.trait.name) + "</span> " + esc(u.trait.text) + "</p>";
  h += '<div class="wk-facts"><span>' + wkKind(u) + "</span><span>🏗️ " + (b ? b.icon + " " + b.name : u.building) + " " + u.level + "</span>" + (u.lab ? "<span>🔬 " + lab.icon + " " + lab.name + " " + u.lab + "</span>" : "<span>🔬 No research needed</span>") + "</div>";
  if (!u.settler) {
    var rows = [];
    if (u.lab) {
      var rc = {};
      RES.forEach(function (k) { rc[k] = u.cost[k] * W.combat.research; });
      rows.push(["🔬 Research", "", "", "", "<b>" + wkN(wkSum(rc)) + "</b>", fmt(u.time * F.researchTime * 1000 * (t.perk.research || 1) * Math.pow(F.lab, Math.max(0, u.lab - 1)))].concat(resCells(rc)));
    }
    for (var l = 1; l <= W.combat.upgradeMax; l++) {
      var f = F.upCost * Math.pow(F.upCostGrowth, l - 1);
      var c = {};
      RES.forEach(function (k) { c[k] = Math.round(u.cost[k] * f); });
      var bonus = 1 + l * W.combat.upgrade * (t.perk.upgradeBonus || 1) / 100;
      var ms = u.time * F.upTime * Math.pow(F.upTimeGrowth, l - 1) * 1000 * Math.pow(F.weaponry, l - 1);
      rows.push(["⚒️ " + l, Math.round(u.atk * bonus), Math.round(u.defG * bonus), Math.round(u.defA * bonus), "<b>" + wkN(wkSum(c)) + "</b>", fmt(ms)].concat(resCells(c)));
    }
    h += kt({ head: ["", "⚔️", "🛡️", "🎯", "Σ", "⏱️"].concat(RES_HEAD), rows: rows, cls: "lv" });
    h += wkNote("⚒️ = upgrade in the " + (wp ? wp.icon + " " + wp.name : "armory") + " (needs that level). Times at the lowest possible building level.");
  }
  return h + "</div>";
}

// ---------- the sheet ----------
function wikiSheet() {
  var W = wiki.data;
  var h = '<div class="sheet-head"><span class="hi">📖</span><div><h3>' + trStr("Mars Guide") + '</h3><b>' + trStr("How everything works, with this server’s numbers") + '</b></div></div>';
  h += '<div class="wk-top"><input type="search" class="wk-search" data-wiki-q="1" placeholder="' + trStr("Search: e.g. wall, raid, terra, Jet…") + '" value="' + esc(wiki.q) + '">';
  h += '<div class="wk-tabs">' + WIKI_TABS.map(function (t) { return '<button class="' + (!wiki.q && wiki.tab === t[0] ? "on" : "") + '" data-wiki-tab="' + t[0] + '">' + t[1] + " " + trStr(t[2]) + "</button>"; }).join("") + "</div></div>";
  var cards;
  if (wiki.q) {
    var q = wiki.q.toLowerCase();
    cards = [];
    WIKI_TABS.forEach(function (t) {
      if (t[0] === "troops" || t[0] === "buildings") return;
      wikiChapter(W, t[0]).forEach(function (c) {
        if (c.tool && c.id !== "f-battle" && c.id !== "f-terra") return;
        var text = (c.title + " " + c.body.replace(/<[^>]*>/g, " ")).toLowerCase();
        if (wkMatch(text, q)) { c.where = t[1] + " " + t[2]; cards.push(c); }
      });
    });
    // buildings and troops by name
    W.buildings.forEach(function (b) {
      if (!wkMatch((wkBName(W, b.key) + " " + b.key + " " + wkBD(W, b).info).toLowerCase(), q)) return;
      var c = wkCard("s-" + b.key, "", wkBName(W, b.key), wkP(esc(wkBD(W, b).info)) + '<button class="wk-more" data-wiki-goto-b="' + b.key + '">📈 All levels</button>');
      c.where = "🏗️ Buildings";
      cards.push(c);
    });
    W.tribes.forEach(function (t) {
      t.units.forEach(function (u) {
        if (!wkMatch((u.name + " " + u.role + " " + (u.type === "air" ? "air" : "infantry") + " " + t.name).toLowerCase(), q)) return;
        var c = wkCard("u-" + t.key + u.key, u.icon, u.name, kt({ head: ["Tribe", "⚔️", "🛡️", "🎯", "💨", "🎒", "🥔"], rows: [[t.icon + " " + t.name, u.atk, u.defG, u.defA, u.speed, u.carry, eatTxt(u.upkeep, true)]] }) + wikiUnit(W, t, u));
        c.where = "⚔️ Troops";
        cards.push(c);
      });
    });
    if (!cards.length) return h + '<p class="empty">Nothing found for “' + esc(wiki.q) + '”. Try another word.</p>';
  } else {
    cards = wikiChapter(W, wiki.tab);
  }
  // quick jump to every section of this chapter
  var folded = function (c) {
    if (wiki.q) return false;
    if (wiki.fold[c.id] !== undefined) return wiki.fold[c.id];
    return !!(c.tool && /^f-/.test(c.id)); // formulas start closed
  };
  if (!wiki.q && cards.length > 2) {
    var anyOpen = cards.some(function (c) { return !folded(c); });
    h += '<div class="wk-jump">' + cards.map(function (c) { return '<button data-wiki-jump="wk-' + c.id + '">' + (c.icon ? c.icon + " " : "") + c.title.replace(/<[^>]*>/g, "") + "</button>"; }).join("");
    h += '<button class="wk-all" data-wiki-foldall="' + (anyOpen ? 1 : 0) + '">' + (anyOpen ? "▴ Collapse all" : "▾ Expand all") + "</button></div>";
  }
  h += '<div class="wk-cards">';
  cards.forEach(function (c) {
    var head = (c.icon ? '<span class="wk-i">' + c.icon + "</span>" : "") + c.title + (c.where ? '<small class="wk-where">' + c.where + "</small>" : "");
    if (wiki.q) { h += '<article class="wk-card" id="wk-' + c.id + '"><h4>' + head + "</h4>" + c.body + "</article>"; return; }
    var fo = folded(c);
    h += '<article class="wk-card' + (fo ? " folded" : "") + '" id="wk-' + c.id + '"><h4><button class="wk-h" data-wiki-fold="' + c.id + '">' + head + '<span class="wk-chev">' + (fo ? "▸ show" : "▾") + "</span></button></h4>" + (fo ? "" : c.body) + "</article>";
  });
  return h + "</div>";
}

// ---------- 🧪 Tools: travel times, army calculator, formulas ----------
var wkt = {
  tool: "travel",
  lv: { hq: 1, builders: 0 },
  tr: { fx: null, fy: null, tx: "", ty: "", tribe: null, caravan: 0 },
  ar: { tribe: null, n: {}, up: 0, drums: 0, shield: 0, wall: 0, dist: 10, trainLv: 1 },
};

function wkNum(v, min, max) {
  var n = parseFloat(v);
  if (isNaN(n)) n = 0;
  return Math.max(min, Math.min(max, n));
}
function wkIn(path, value, attrs) {
  return '<input class="wk-in" type="number" data-wkt="' + path + '" value="' + esc(value) + '" ' + (attrs || "") + ">";
}
function wkSel(path, options, value) {
  return '<select class="wk-in" data-wkt="' + path + '">' + options.map(function (o) { return '<option value="' + o[0] + '"' + (String(o[0]) === String(value) ? " selected" : "") + ">" + o[1] + "</option>"; }).join("") + "</select>";
}
// the same speed-up rule as the server: above level 10 every level helps half as much
function wkSpeedAt(per, level) {
  var steps = Math.max(0, level - 1);
  if (steps <= 9) return Math.pow(per, steps);
  return Math.pow(per, 9) * Math.pow(1 - (1 - per) * 0.5, steps - 9);
}
function wkLevels(max, from) {
  var a = [];
  for (var i = from || 0; i <= max; i++) a.push([i, String(i)]);
  return a;
}


// ⏱️ how long does it take from A to B?
function wkToolTravel(W) {
  var T = wkt.tr;
  if (T.fx === null && data) { T.fx = data.x; T.fy = data.y; }
  if (!T.tribe) T.tribe = wiki.tribe;
  var h = '<div class="wk-form"><label>From X' + wkIn("tr.fx", T.fx) + "</label><label>From Y" + wkIn("tr.fy", T.fy) + "</label>";
  h += "<label>To X" + wkIn("tr.tx", T.tx, 'placeholder="0"') + "</label><label>To Y" + wkIn("tr.ty", T.ty, 'placeholder="0"') + "</label>";
  h += "<label>Tribe" + wkSel("tr.tribe", W.tribes.map(function (t) { return [t.key, t.icon + " " + t.name]; }), T.tribe) + "</label>";
  h += "<label>🐪 Caravans" + wkSel("tr.caravan", wkLevels(W.alliance.maxLevel), T.caravan) + "</label></div>";
  var dist = Math.hypot(wkNum(T.tx, -99, 99) - wkNum(T.fx, -99, 99), wkNum(T.ty, -99, 99) - wkNum(T.fy, -99, 99));
  var now = serverNow();
  var t = wkTribe(W, T.tribe);
  var trip = function (speed) { return Math.max(1000, (dist / speed) * 3600000); };
  var list = t.units.slice().sort(function (a, b) { return b.speed - a.speed; });
  var rows = list.map(function (u) {
    var ms = trip(u.speed);
    return [u.icon + " " + esc(u.name), u.speed, fmt(ms), clockText(now + ms).slice(0, 5), fmt(2 * ms)];
  });
  var mSpeed = W.market.speed * (1 + T.caravan * W.formulas.ally.caravan);
  var mms = trip(mSpeed);
  rows.unshift(["🐪 Merchants", Math.round(mSpeed), fmt(mms), clockText(now + mms).slice(0, 5), fmt(2 * mms)]);
  h += wkNote("Distance: <b>" + (Math.round(dist * 10) / 10) + " tiles</b> (straight line). A group moves at the speed of its slowest unit.");
  h += kt({ head: ["", "💨/h", "One way", "Lands", "Back home"], rows: rows });
  h += wkNote("🪶 Low Gravity: merchants and troops on their way home " + Math.round(W.formulas.gravity * 100) + "% faster. Times start now (server time).");
  return h;
}

// 🪖 what can this army do?
function wkToolArmy(W) {
  var A = wkt.ar;
  if (!A.tribe) A.tribe = wiki.tribe;
  var t = wkTribe(W, A.tribe);
  var F = W.formulas;
  var h = '<div class="wk-form"><label>Tribe' + wkSel("ar.tribe", W.tribes.map(function (x) { return [x.key, x.icon + " " + x.name]; }), A.tribe) + "</label>";
  h += "<label>⚒️ Upgrades" + wkSel("ar.up", wkLevels(W.combat.upgradeMax), A.up) + "</label>";
  h += "<label>🥁 Drums" + wkSel("ar.drums", wkLevels(W.alliance.maxLevel), A.drums) + "</label>";
  h += "<label>🛡️ Shield" + wkSel("ar.shield", wkLevels(W.alliance.maxLevel), A.shield) + "</label>";
  h += "<label>🧱 Wall" + wkSel("ar.wall", wkLevels(10), A.wall) + "</label>";
  h += "<label>🏗️ Barracks / hangar" + wkSel("ar.trainLv", wkLevels(20, 1), A.trainLv) + "</label>";
  h += "<label>📏 Farm distance" + wkIn("ar.dist", A.dist, 'min="1"') + "</label></div>";
  h += '<div class="wk-army">';
  t.units.forEach(function (u) {
    h += '<label class="wk-au"><span>' + u.icon + "</span><small>" + esc(u.name) + "</small>" + wkIn("ar.n." + u.key, A.n[u.key] || "", 'min="0" placeholder="0"') + "</label>";
  });
  h += "</div>";
  var up = 1 + A.up * W.combat.upgrade * (t.perk.upgradeBonus || 1) / 100;
  var s = { ag: 0, aa: 0, dg: 0, da: 0, carry: 0, food: 0, cost: { wood: 0, stone: 0, metal: 0, food: 0 }, ms: 0, slow: 0, n: 0 };
  t.units.forEach(function (u) {
    var n = wkNum(A.n[u.key], 0, 1e6);
    if (!n) return;
    s.n += n;
    if (u.type === "air") s.aa += n * u.atk * up; else s.ag += n * u.atk * up;
    s.dg += n * u.defG * up;
    s.da += n * u.defA * up;
    s.carry += n * u.carry;
    s.food += n * u.upkeep;
    RES.forEach(function (k) { s.cost[k] += n * u.cost[k]; });
    var per = u.building === "hangar" ? F.hangar : u.building === "workshop" ? F.workshop : F.barracks;
    s.ms += n * u.time * 1000 * wkSpeedAt(per, A.trainLv);
    if (!s.slow || u.speed < s.slow) s.slow = u.speed;
  });
  if (!s.n) return h + '<p class="empty">Type how many of each unit you have or plan.</p>';
  var atk = (s.ag + s.aa) * (1 + A.drums * F.ally.drums);
  var air = atk ? s.aa / (s.ag + s.aa) : 0;
  var combo = air >= W.combat.comboShare / 100 && 1 - air >= W.combat.comboShare / 100;
  if (combo) atk *= 1 + W.combat.combo / 100;
  var defMul = 1 + A.wall * (t.perk ? t.perk.wall : W.combat.wall) / 100 + A.shield * F.ally.shield;
  var round = 2 * (A.dist / s.slow) * 3600000;
  h += kt({
    head: ["", ""],
    rows: [
      ["⚔️ Attack", wkN(atk) + (air ? " <small>(" + Math.round(air * 100) + "% ✈️" + (combo ? ", +" + W.combat.combo + "% mixed" : "") + ")</small>" : "")],
      ["🛡️ Infantry defense", wkN(s.dg * defMul)],
      ["🎯 Air defense", wkN(s.da * defMul)],
      ["🎒 Carries", wkN(s.carry)],
      ["🥔 Eats", eatTxt(s.food, true)],
      ["💰 Price", RES.map(function (k) { return RES_ICON[k] + " " + shortNum(s.cost[k]); }).join(" ") + " = <b>" + shortNum(wkSum(s.cost)) + "</b>"],
      ["⏱️ Training", fmt(s.ms)],
      ["💨 Speed", s.slow + " tiles/h"],
      ["🔁 Round trip " + A.dist + " tiles", fmt(round)],
      ["💰 Loot per hour (max)", wkN(s.carry / (round / 3600000))],
    ],
    cls: "kv",
  });
  h += wkNote("Defense includes the wall and Shield Wall you picked.");
  return h;
}

// 📐 the rules behind it all
function wkFormulas(W, part) {
  var F = W.formulas;
  var C = W.combat;
  var pct = function (f) { return "+" + Math.round((f - 1) * 100) + "%"; };
  var less = function (f) { return "−" + Math.round((1 - f) * 100) + "%"; };
  var parts = {};
  parts.building = [
    ["Cost of level L", "level-1 cost × " + F.costGrowth + "<sup>L−1</sup> (" + pct(F.costGrowth) + " per level), boosters × " + F.boostCostGrowth],
    ["Build time", "level-1 time × " + F.timeGrowth + "<sup>L−1</sup> · " + less(F.hq) + " per HQ level · ÷ (1 + Builders’ Guild)"],
    ["Fields above " + W.fields.max, "cost " + pct(F.fieldCostHigh) + ", time " + pct(F.fieldTimeHigh) + " per level"],
    ["Production", W.fields.prod[0] + "/h on level 1, " + pct(F.prodGrowth) + " per level"],
    ["Storage", pct(F.capGrowth) + " per level"],
    ["Points", "sum of all field and building levels"],
  ];
  parts.battle = [
    ["A", "attack × (1 ± " + C.luck + "% luck) × (1 + " + C.combo + "% if mixed)"],
    ["D", "(🛡️ × infantry share + 🎯 × air share) × (1 + wall + bonuses)"],
    ["x", "(weaker ÷ stronger)<sup>1.5</sup>"],
    ["⚔️ Attack losses", "winner x, loser 100%"],
    ["💰 Raid losses", "winner x ÷ (1 + x), loser 1 ÷ (1 + x)"],
  ];
  parts.troops = [
    ["Upgrade level L", "price × " + F.upCost + " × " + F.upCostGrowth + "<sup>L−1</sup>, time × " + F.upTime + " × " + F.upTimeGrowth + "<sup>L−1</sup>, +" + C.upgrade + "% attack & defense per level"],
    ["Research", "price × " + C.research + ", time × " + F.researchTime + ", " + "−" + Math.round((1 - F.lab) * 100) + "% per lab level"],
    ["Training", less(F.barracks) + " per training-building level"],
    ["Upgrades", less(F.weaponry) + " per armory level"],
    ["Speed bonuses", "divide the time: +25% faster = time ÷ 1.25"],
  ];
  parts.travel = [
    ["Distance", "√(Δx² + Δy²) — a straight line"],
    ["Travel time", "distance ÷ speed of the slowest unit"],
    ["🪶 Low Gravity", "merchants and troops on their way home +" + Math.round(F.gravity * 100) + "%"],
  ];
  parts.terra = [
    ["Per real hour", "points × " + F.terraPerPoint + " × " + W.speeds.production + " × (1 + hub + zone + others)"],
    ["Hub bonus", Math.round(F.terraHubBase * 100) + "% × level<sup>" + F.terraHubCurve + "</sup>; Landing Zone +" + Math.round(F.terraZone * 100) + "%"],
    ["Colony N+1", F.terraBase + " × N<sup>" + F.terraExp + "</sup> terra"],
  ];
  var c = wkCard("f-" + part, "📐", "Formulas", kt({ head: ["", "Formula"], rows: parts[part], left: 2, cls: "kv" }));
  c.tool = true;
  return c;
}

// ---------- 🌌 Project Aurora ----------
var pyForm = { key: "" };
RES.forEach(function (k) { pyForm[k] = ""; });

function pylonAt(x, y) {
  if (!map.chunk || !map.chunk.pylons) return null;
  for (var i = 0; i < map.chunk.pylons.length; i++) {
    var p = map.chunk.pylons[i];
    if (p.x === x && p.y === y) return p;
  }
  return null;
}
function pylonPct(p) {
  return p.need ? Math.min(100, Math.floor((p.amount / p.need) * 100)) : 0;
}
function pylonTile(p) {
  var cls = "pylon" + (p.active ? " on" : "") + (p.locked ? " full" : "") + (p.ignited ? " ignited" : "") + (p.targeted ? " target mv-" + p.targeted : "");
  var bar = p.active && p.mine ? '<i class="pyl-bar"><b style="width:' + pylonPct(p) + '%"></b></i>' : "";
  var pa = mapArt("map-pylon-" + (p.locked || p.ignited ? "on" : "off"));
  if (pa) cls += " clay";
  return '<span class="' + cls + '" title="' + esc(p.name) + '">' + (pa || "🗼") + bar + moveMark(p.targeted) + "</span>";
}
function pylonTileInfo(p, dist) {
  var h = tipHead("🗼", esc(p.name), (p.active ? "🌌 Project Aurora" : "💤 Asleep") + " · " + where(p.x, p.y, dist));
  if (!p.active) {
    return h + '<p class="tip-note">An ancient tower of the first settlers. It wakes up on the day Project Aurora begins (see the clock at the top): then alliances charge the four pylons, link them to the Landing Zone and light the sky.</p>';
  }
  var facts = [];
  var remaining = Math.max(0, p.need - p.amount - (p.incoming || 0));
  if (p.mine) {
    facts.push(fact(p.locked ? "⚡ Full &amp; locked" : "⚡ " + pylonPct(p) + "%", p.locked ? "ok" : "", p.amount + " / " + p.need + " charged by your alliance"));
    facts.push(p.linked ? fact("🔗 Linked", "ok", "Your colonies connect this pylon to the Landing Zone") : fact("⛓️ " + p.gap + " tiles missing", "warn", "Your ley line from the Landing Zone ends " + p.gap + " tiles too early. Settle colonies at most " + p.link + " tiles apart to reach it."));
  }
  (p.others || []).forEach(function (o) { facts.push(fact("👥 " + esc(o.name) + " " + (o.locked ? "⚡ full" : o.pct + "%"), o.locked ? "" : "gold", "Another alliance charging here")); });
  h += tipFacts(facts);
  if (!p.mine) {
    h += '<p class="tip-note">Only alliances can charge the pylons. Join or found one to take part.</p>';
  } else if (!p.locked) {
    h += '<div class="pybar"><i style="width:' + pylonPct(p) + '%"></i></div>';
    h += '<div class="pylon-ledger"><span>Delivered <b>' + p.amount.toLocaleString() + '</b></span><span>En route <b>' + (p.incoming || 0).toLocaleString() + '</b></span><span>Still needed <b>' + remaining.toLocaleString() + '</b></span><span>Protected <b>' + (p.secured || 0).toLocaleString() + '</b></span></div>';
    h += '<p class="tip-note">Fixed target: ' + p.need.toLocaleString() + ' total resources. Any mix works. Milestones at 25%, 50% and 75% protect your charge from raids.</p>';
    var m = data && data.market;
    var tot = RES.reduce(function (n, k) { return n + (pyForm.key === p.key ? Number(pyForm[k] || 0) : 0); }, 0);
    h += '<div class="pyform"><div class="abrow">';
    RES.forEach(function (k) { h += "<label>" + RES_ICON[k] + '<input type="number" min="0" inputmode="numeric" aria-label="' + RES_NAME[k] + '" data-pyl="' + p.key + ":" + k + '" value="' + (pyForm.key === p.key ? esc(pyForm[k]) : "") + '" placeholder="0"></label>'; });
    h += "</div><small>" + (!m || !m.level ? "You need a marketplace to send merchants" : !m.free ? "🐪 All merchants of this colony are on the road · " + remaining.toLocaleString() + " still missing" : "🐪 " + Math.ceil(tot / m.carry) + " of " + m.free + " free merchants · " + remaining.toLocaleString() + " still missing") + "</small>";
    h += "</div>";
    h += tipActions('<button class="btn" data-pyl-go="' + p.key + '"' + (m && m.free && tot > 0 && tot <= remaining && tot <= m.free * m.carry && RES.every(function (k) { var n = Number(pyForm[k] || 0); return Number.isSafeInteger(n) && n >= 0 && n <= Math.floor(data.res[k]); }) ? "" : " disabled") + ">⚡ Charge with merchants</button>", [tipBtn('data-pyl-fill="' + p.key + '"', "🧺", "Fill · keep 20%")]);
  }
  var drain = (p.others || []).some(function (o) { return o.drainable; });
  if (drain) h += tipActions("", [tipBtn('data-send="' + p.x + "," + p.y + '"', "🔌", "Drain (raid)")]);
  return h;
}

function auroraBar(se) {
  var now = serverNow();
  if (!se.active) {
    if (se.winner && now - se.winner.at < 3 * 86400000) {
      return '<div class="seasonbar aurora won"><b>🌌 ' + esc(se.winner.name) + " lit the Aurora and won the server!</b>" + (se.winner.key === se.myKey ? "<small>That’s your alliance. The sky glows for you!</small>" : "") + "</div>";
    }
    return "";
  }
  var h = '<div class="seasonbar aurora"><div class="sb-top"><b>🌌 Project Aurora</b><small>Charge all 4 🗼 pylons, link them to the 🚩 with colonies max ' + se.link + " tiles apart, then hold the flag for " + se.hours + "h</small></div>";
  if (se.ignition) {
    var mine = se.ignition.key === se.myKey;
    h += '<p class="au-ig' + (mine ? "" : " foe") + '">⚡ <b>' + esc(se.ignition.name) + "</b> " + (se.ignition.paused ? "paused · " + Math.floor(se.ignition.progressMs / (se.hours * 3600000) * 100) + "% retained" + (se.ignition.graceUntil > now ? " · recovery window " + fmt(se.ignition.graceUntil - now) : " · progress decaying") : "ignites in <b>" + fmt(Math.max(0, se.ignition.winsAt - now)) + "</b>") + (mine ? " · keep the flag and every ley line!" : " · take the 🚩 or cut a ley line!") + "</p>";
  }
  if (se.inAlliance) {
    var chargedN = se.pylons.filter(function (p) { return p.locked; }).length;
    var linkedN = se.pylons.filter(function (p) { return p.linked; }).length;
    h += '<div class="aurora-steps"><span>1 · Charge <b>' + chargedN + '/4</b></span><span>2 · Connect <b>' + linkedN + '/4</b></span><span>3 · Hold flag <b>' + (se.zoneMine ? 'Yes' : 'No') + '</b></span></div>';
    h += '<p class="au-next">Next: ' + (chargedN < 4 ? 'open a pylon below and send resources; en-route cargo is counted.' : linkedN < 4 ? 'extend colony chains with gaps no larger than ' + se.link + ' tiles.' : !se.zoneMine ? 'capture the Landing Zone and defend your links.' : 'defend the flag and links while ignition completes.') + '</p>';
    h += '<div class="au-pyl">';
    se.pylons.forEach(function (p) {
      var pct = p.locked ? 100 : p.need ? Math.floor((p.amount / p.need) * 100) : 0;
      h += '<button class="' + (p.locked ? "full " : "") + (p.linked ? "ok" : "") + '" data-goto="' + p.x + "," + p.y + '" title="' + esc(p.name) + (p.linked ? " · linked" : " · " + p.gap + " tiles missing in the ley line") + '">🗼' + p.name.split(" ")[0] + " ⚡" + pct + "% " + (p.linked ? "🔗" : "⛓️" + p.gap) + "</button>";
    });
    h += '<span class="zone' + (se.zoneMine ? " ok" : "") + '">🚩 ' + (se.zoneMine ? "ours" : "not ours") + "</span></div>";
  } else {
    h += '<p class="sb-streak">Join an alliance to take part.</p>';
  }
  if (se.standings.length) {
    h += '<div class="sb-teams">';
    se.standings.forEach(function (t) {
      h += '<span class="' + (t.key === se.myKey ? "me" : "") + '">' + esc(t.name) + " ⚡" + t.charged + "/4 🔗" + t.linked + "/4" + (t.zone ? " 🚩" : "") + "</span>";
    });
    h += "</div>";
  }
  return h + "</div>";
}

// ---------- landmarks on the map ----------
function landmarkTileInfo(l, dist) {
  var H = l.holder;
  var h = tipHead(l.icon, l.name, "✨ " + l.bonus + " · " + where(l.x, l.y, dist));
  if(H&&H.mine)h+=shareTextButton('MarsL · '+H.player+' '+(H.claimEnds?'is claiming ':'holds ')+l.name+' ('+l.x+'|'+l.y+') · '+location.origin);
  var facts = [];
  if (H) facts.push(fact("👤 " + playerLink(H.player, H.tag), H.mine ? "ok" : H.ally ? "ok" : "gold", "Held by " + H.player + " (" + H.colony + ")"));
  if (H && H.mine && H.guards !== undefined) facts.push(fact("🛡️ " + H.guards + " guards"));
  if (H && H.claimEnds) facts.push(fact("⏳ claiming · " + fmt(Math.max(0, H.claimEnds - serverNow())), "gold", "The bonus only starts when the claim is over. Until then the place can be taken from them."));
  if (!H) {
    facts.push(fact(LM_GUARD + " " + l.guards + " guardians"));
    facts.push(fact("🛡️ " + l.guardDefG, "", "Infantry defense"));
    facts.push(fact("🎯 " + l.guardDefA, "", "Air defense"));
  }
  var ex = (data && data.expedition) || { range: 0, name: "Expedition Base", icon: "🧭" };
  var near = ex.range > 0 && parseFloat(dist) <= ex.range;
  var heldHere = data && data.relic;
  if (!l.open) facts.push(fact("🔒 Sealed", "warn", "They open on a fixed server day - see the clock at the top"));
  else if (!(H && (H.mine || H.ally))) {
    if (!ex.range) facts.push(fact("❌ needs " + ex.icon + " " + esc(ex.name), "warn", "Build the " + ex.name + " in this colony to claim landmarks"));
    else facts.push(fact(near ? "✅ in range" : "❌ max " + ex.range + " tiles", near ? "ok" : "warn", "Your " + ex.name + " reaches landmarks up to " + ex.range + " tiles away"));
  }
  h += tipFacts(facts);
  if (!l.open) return h + '<p class="tip-note">' + esc(l.info) + "</p>";
  var main = "";
  if (H && H.mine) main = '<button class="btn" data-send-support="' + l.x + "," + l.y + '">🛡️ Add guards</button>';
  else if (!(H && H.ally)) main = '<button class="btn danger" data-send-lm="' + l.x + "," + l.y + '"' + (near && !heldHere ? ">⚔️ Claim" : ' title="You can fight here, but this colony can’t keep it">⚔️ Attack') + "</button>";
  var more = [];
  if (!(H && (H.mine || H.ally))) more.push(tipBtn('data-send-spy="' + l.x + "," + l.y + '"', "🔍", "Spy"), tipBtn('data-sim-at="' + l.x + "," + l.y + '"', "🧮", "Simulate"));
  h += tipActions(main, more);
  h += '<p class="tip-note">' + (heldHere && !(H && H.mine) ? "This colony already holds " + data.relic.icon + ". " : "") + (!near || heldHere ? "This colony can still attack it: troops fight as usual, but walk home after a win. " : "") + "One landmark per colony · win the fight, then hold it for " + l.claimHours + "h before the bonus starts · guards defend +" + l.defBonus + "% · lose all guards, lose the bonus.</p>";
  return h;
}
var LM_GUARD = "🗿";

// ---------- dragging, momentum, wheel and keys ----------
function setupMapInput() {
  var v = document.getElementById("mapview");
  var drag = null;

  // two fingers: pinch to zoom
  var touches = {};
  var pinch = null;
  function fingerGap() {
    var p = Object.keys(touches).map(function (k) { return touches[k]; });
    return p.length >= 2 ? Math.hypot(p[0].x - p[1].x, p[0].y - p[1].y) : 0;
  }
  v.addEventListener("pointerdown", function (e) {
    touches[e.pointerId] = { x: e.clientX, y: e.clientY };
    if (Object.keys(touches).length === 2) {
      drag = null; // a pinch is no drag and no tap
      pinch = { gap: fingerGap() };
    }
  });
  v.addEventListener("pointermove", function (e) {
    if (!touches[e.pointerId]) return;
    touches[e.pointerId] = { x: e.clientX, y: e.clientY };
    if (!pinch || !pinch.gap) return;
    var g = fingerGap();
    if (g > pinch.gap * 1.3) { setZoom(1); pinch.gap = g; }
    else if (g < pinch.gap / 1.3) { setZoom(-1); pinch.gap = g; }
  });
  function lift(e) {
    delete touches[e.pointerId];
    if (Object.keys(touches).length < 2) pinch = null;
  }
  v.addEventListener("pointerup", lift);
  v.addEventListener("pointercancel", lift);

  v.addEventListener("pointerdown", function (e) {
    if (e.target.closest(".pan") || pinch) return;
    stopAnim();
    v.setPointerCapture(e.pointerId);
    drag = { x: e.clientX, y: e.clientY, cx: map.cam.x, cy: map.cam.y, moved: false, hist: [] };
  });

  v.addEventListener("pointermove", function (e) {
    if (!drag) return;
    var dx = e.clientX - drag.x;
    var dy = e.clientY - drag.y;
    if (!drag.moved && Math.hypot(dx, dy) > 6) {
      drag.moved = true;
      v.classList.add("grabbing");
    }
    if (!drag.moved) return;
    var t = T();
    map.cam.x = drag.cx - dx / t;
    map.cam.y = drag.cy + dy / t;
    clampCam();
    positionWorld();
    drag.hist.push({ t: performance.now(), x: map.cam.x, y: map.cam.y });
    if (drag.hist.length > 6) drag.hist.shift();
  });

  function end(e) {
    if (!drag) return;
    v.classList.remove("grabbing");
    if (!drag.moved) {
      // a tap: which tile was it?
      var r = v.getBoundingClientRect();
      var t = T();
      var x = Math.round(map.cam.x + (e.clientX - r.left - r.width / 2) / t);
      var y = Math.round(map.cam.y - (e.clientY - r.top - r.height / 2) / t);
      selectTile(x, y);
    } else {
      // keep sliding a bit, like a real map app
      var h = drag.hist;
      if (h.length >= 2) {
        var a = h[0];
        var b = h[h.length - 1];
        var dt = Math.max(1, b.t - a.t);
        momentum((b.x - a.x) / dt, (b.y - a.y) / dt);
      } else {
        loadChunk(false);
      }
    }
    drag = null;
  }
  v.addEventListener("pointerup", end);
  v.addEventListener("pointercancel", function () { drag = null; v.classList.remove("grabbing"); });

  v.addEventListener("wheel", function (e) {
    e.preventDefault();
    setZoom(e.deltaY < 0 ? 1 : -1);
  }, { passive: false });

  var mini = document.getElementById("minimap");
  mini.addEventListener("click", function (e) {
    if (!map.mini) return;
    var r = mini.getBoundingClientRect();
    var R = map.mini.mapRadius;
    var size = 2 * R + 1;
    var x = Math.floor(((e.clientX - r.left) / r.width) * size) - R;
    var y = R - Math.floor(((e.clientY - r.top) / r.height) * size);
    selectTile(x, y);
    glideTo(x, y, 450);
  });
}

function momentum(vx, vy) {
  stopAnim();
  var last = performance.now();
  function step(now) {
    var dt = now - last;
    last = now;
    map.cam.x += vx * dt;
    map.cam.y += vy * dt;
    vx *= Math.pow(0.9, dt / 16);
    vy *= Math.pow(0.9, dt / 16);
    clampCam();
    positionWorld();
    if (Math.abs(vx) + Math.abs(vy) > 0.0005) map.anim = requestAnimationFrame(step);
    else { map.anim = null; loadChunk(false); }
  }
  map.anim = requestAnimationFrame(step);
}

document.addEventListener("keydown", function (e) {
  if (e.key === "Escape") { closeSheet(); toggleSide(false); return; }
  if (view !== "map" || sheet) return;
  var a = document.activeElement;
  if (a && a.tagName === "INPUT") return;
  var moves = { ArrowUp: [0, 1], ArrowDown: [0, -1], ArrowLeft: [-1, 0], ArrowRight: [1, 0], w: [0, 1], s: [0, -1], a: [-1, 0], d: [1, 0] };
  var mv = moves[e.key];
  if (mv) {
    e.preventDefault();
    glideTo(Math.round(map.cam.x) + mv[0], Math.round(map.cam.y) + mv[1], 160);
  } else if (e.key === "+" || e.key === "=") setZoom(1);
  else if (e.key === "-") setZoom(-1);
});

window.addEventListener("resize", function () { if (view === "map") positionWorld(); });

// Open the "send troops" popup for a colony on the map
// "Send" from a joint attack: switch to that colony, load the target, fill in the troops
var jpSend = null; // the joint attack the send window was opened for
function planSend(x, y, colonyId, pre) {
  sendTarget = null;
  var go = function () {
    fetch("/api/map?x=" + x + "&y=" + y).then(function (r) { return r.json(); }).then(function (j) {
      map.chunk = j;
      openSend(x, y, "attack", pre);
      if (!sendTarget || sendTarget.x !== x || sendTarget.y !== y) toast("There is nothing to attack at (" + x + "|" + y + ") right now");
    });
  };
  if (data && data.colonyId !== colonyId) post("/api/switch", { id: colonyId }, go);
  else go();
}

var armyPending=null;
function openSend(x, y, mission, prefill) {
  if(!prefill&&armyPending){prefill=armyPending;armyPending=null;}
  var c = colonyAt(x, y);
  if (!c && x === 0 && y === 0 && map.chunk && map.chunk.zone) {
    c = { zone: true, x: 0, y: 0, name: "Landing Zone", info: map.chunk.zone };
  } else if (!c && mission === "settle") {
    c = { settle: true, x: x, y: y, name: "Free land" };
  } else if (!c && meteorAt(x, y)) {
    var mt = meteorAt(x, y);
    c = { meteor: true, x: x, y: y, name: mt.lander ? "Wrecked lander" : "Meteor crate", info: mt };
    mission = "raid";
  } else if (!c && landmarkAt(x, y)) {
    var lm = landmarkAt(x, y);
    c = { landmark: true, x: x, y: y, name: lm.name, info: lm };
    var lmMine = lm.holder && lm.holder.mine;
    if (mission === "raid" || (mission === "attack" && lmMine)) mission = lmMine ? "reinforce" : "attack";
  } else if (!c) {
    var cp = campAt(x, y);
    if (!cp) return;
    c = Object.assign({ camp: true }, cp);
    if (mission === "raid") mission = "attack";
  } else if (c.mine && mission !== "attack" && mission !== "raid") {
    mission = "reinforce";
  }
  sendTarget = c;
  sendMission = mission;
  sendCount = prefill ? Object.assign({}, prefill) : {};
  if (!prefill) jpSend = null;
  // fetch fresh troop numbers first
  return (startup ? startupFetch("/api/colony", 3) : fetch("/api/colony")).then(function (r) {
    if (!r.ok && r.status !== 401) throw new Error("Refresh failed");
    if (handle401(r)) return;
    return r.json().then(function (d) {
      data = d;
      openSheet("send", null);
    });
  }).catch(function () { toast("Could not load your troops. Please try again."); });
}

var sendAim = "";
document.addEventListener("change", function(e){
  if(e.target.matches('[data-profile-flag]')){
    var preview=e.target.parentElement.querySelector('.flag-preview');
    if(preview)preview.innerHTML=countryFlag(e.target.value);
  }
});
document.addEventListener("change", function (e) {
  if (e.target && e.target.getAttribute && e.target.getAttribute("data-send-aim")) sendAim = e.target.value;
  var wva = e.target && e.target.getAttribute && e.target.getAttribute("data-wv-aim");
  if (wva !== null && wva !== undefined && waves) waves.list[Number(wva)].aim = e.target.value;
});
function sendTroops() {
  var troops = {};
  data.units.forEach(function (u) {
    var n = parseInt(sendCount[u.key], 10) || 0;
    if (n > 0 && sendable(u)) troops[u.key] = n;
  });
  post("/api/send", { x: sendTarget.x, y: sendTarget.y, mission: sendMission, troops: troops, hero: sendHero && heroCanGo(data, sendTarget), orders: sendHero && heroCanGo(data, sendTarget) ? sendOrder : "", aim: sendMission === "attack" ? sendAim : "", power: sendPower && !!warCanGo(data, sendTarget) }, function () {
    sendHero = false; sendOrder = "";
    sendPower = false;
    var msg = { settle: "🏳️ The settlers packed their tents. Off they go!", scout: "🔍 Spies are on their way. Sneaky!", reinforce: "🛡️ Help is on the way!", raid: "💰 Your raiders marched off. Bring snacks back!", attack: "⚔️ Your troops marched off. Good luck!" };
    toast(msg[sendMission], true);
    sfx("march");
    closeSheet();
    if (view === "map") loadChunk(true);
  });
}

// =====================================================================
//  Talking to the server
// =====================================================================
function handle401(r) {
  if (r.status === 401) {
    playFlag(false);
    if (loggedIn || !document.getElementById("authform")) renderAuth();
    loggedIn = false;
    return true;
  }
  return false;
}

// auto = true for the automatic refresh. It pauses while you press a
// button or type, so nothing jumps around under your finger.
var colonyLoading = false;
var colonyRequest = 0;
function loadColony(auto, startup) {
  if (auto && (colonyLoading || (typeof pendingPosts !== "undefined" && pendingPosts.size))) return;
  if (auto && hopState) return; // the tribe screen of a respawn stays put
  if (auto) {
    var a = document.activeElement;
    if (pressing || (a && (a.tagName === "INPUT" || a.tagName === "TEXTAREA" || a.tagName === "SELECT"))) return;
  }
  colonyLoading = true;
  var request = ++colonyRequest;
  var epoch = actionEpoch || 0;
  var sentAt = Date.now();
  return fetch("/api/colony").then(function (r) {
    if (request !== colonyRequest || epoch !== actionEpoch) return;
    if (!r.ok && r.status !== 401 && r.status !== 409) throw new Error("Refresh failed");
    if (handle401(r)) return;
    if (r.status === 409) {
      // 💥 every colony was wiped off the map: straight to the respawn screen
      return r.json().then(function (d) {
        if (request !== colonyRequest || epoch !== actionEpoch || !d.wiped || hopState) return;
        if (sheet) closeSheet();
        hopState = { t: "", name: d.name || "", respawn: true, wiped: true };
        renderAuth();
      });
    }
    return r.json().then(function (d) {
      if (request !== colonyRequest || epoch !== actionEpoch) return;
      syncClock(d.serverNow, d.serverTz, sentAt);
      var first = !loggedIn;
      loggedIn = true;
      if (first && view === "map") openMap();
      if (startup) startupStage = "game screen";
      renderColony(d);
      if (first && !d.tutorial && !d.onboarding && tut.step < 0) setTimeout(startTutorial, 600);
    });
  }).catch(function (err) { if (startup) throw err; if (!auto) toast('Could not refresh. Check your connection and try again.'); }).finally(function () { if (request === colonyRequest) colonyLoading = false; });
}

var reportsRequest = 0;
function loadReports(markSeen) {
  var request = ++reportsRequest, epoch = actionEpoch;
  // send what we have: the server answers "same" when nothing changed, so the list is not rebuilt every few seconds
  var known = reports && reports.v ? "?v=" + encodeURIComponent(reports.v) : "";
  return fetch("/api/reports" + known).then(function (r) {
    if (request !== reportsRequest) return;
    if (handle401(r)) return;
    if (!r.ok) throw new Error("Reports unavailable");
    return r.json().then(function (d) {
      if (request !== reportsRequest || epoch !== actionEpoch) return;
      if (d.same && reports) { reports.now = serverNow(); return; }
      reports = d;
      // a report only counts as read once it was opened (or "mark all as read")
      if (view === "reports" && data) {
        try { renderColony(data); } catch (e) { console.error("Reports could not be drawn", e); toast(trStr("Some reports could not be shown.")); }
      }
    });
  }).catch(function () { if (!markSeen) toast(trStr("Could not load reports. Try again.")); });
}

var pendingPosts = new Set();
var pendingAlliancePosts = new Set();
var actionEpoch = 0;
function post(url, body, after) {
  var key = url + JSON.stringify(body || {});
  if (pendingPosts.has(key)) return;
  pendingPosts.add(key); actionEpoch++;
  var button = document.activeElement;
  var wasDisabled = button && button.disabled;
  if (button && button.tagName === 'BUTTON') { button.disabled = true; button.setAttribute('aria-busy', 'true'); }
  return fetch(url, { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify(body || {}) })
    .then(function (r) { return r.json().then(function (d) {
      if (r.status === 401) { loggedIn = false; renderAuth(); return; }
      if (!r.ok) { toast(d.error || 'The action could not be completed.'); sfx('error'); return; }
      actionEpoch++; sfx('pop'); if (after) after(d);
      if (d.ok) loadColony(false); else renderColony(d);
    }); })
    .catch(function () { toast('Connection interrupted. Refresh to check whether the action completed before trying again.'); })
    .finally(function () { pendingPosts.delete(key); if (button && button.tagName === 'BUTTON') { button.disabled = !!wasDisabled; button.removeAttribute('aria-busy'); } });
}

// Look at another one of my colonies
function switchColony(id) {
  post("/api/switch", { id: id }, function (d) {
    prevQueue = null; // don't celebrate the other colony's buildings
    prevTrain = null;
    trainCount = {};
    toast("🏠 Welcome to " + d.colony + "!", true);
    if (view === "map") {
      map.pending = { x: d.x, y: d.y };
      openMap();
    }
  });
}

// reports read during this visit to the Reports tab: they keep their NEW tag
// until you leave, so it doesn't vanish under your finger
var justRead = {};
var VIEWS = { resources: 1, buildings: 1, troops: 1, map: 1, ranking: 1, reports: 1, messages: 1 };
function switchView(v, target) {
  if (!VIEWS[v]) v = "resources";
  if (v !== view) {
    questsOpen = false;
    document.body.classList.remove("qopen");
  }
  if (v !== "reports") justRead = {};
  closeSheet();
  toggleSide(false);
  view = v;
  window.scrollTo(0, 0);
  if (v === "map") {
    map.pending = target || null;
    openMap();
    return;
  }
  if (v === "reports") loadReports(true);
  if (v === "ranking") { loadRanking(); loadAlliance(); loadMyProfile(); }
  if (v === "messages") loadMessages();
  if (data) renderColony(data);
  loadColony(false);
}

// =====================================================================
//  Clicks, typing and forms
// =====================================================================
// ⠿ drag a colony tile to a new place in the list (and into another group)
var colDrag = null;
document.addEventListener("pointerdown", function (e) {
  var hd = e.target.closest && e.target.closest("[data-col-drag]");
  if (!hd) return;
  e.preventDefault();
  var tile = hd.closest(".mycol");
  colDrag = { tile: tile, list: tile.parentNode, moved: false };
  tile.classList.add("dragging");
});
document.addEventListener("pointermove", function (e) {
  if (!colDrag) return;
  e.preventDefault();
  var under = document.elementFromPoint(e.clientX, e.clientY);
  var other = under && under.closest && under.closest(".mycol, .grp-head");
  if (!other || other === colDrag.tile || other.parentNode !== colDrag.list) return;
  var r = other.getBoundingClientRect();
  var below = e.clientY > r.top + r.height / 2;
  if (other.classList.contains("grp-head")) below = true; // a group header: drop right under it
  colDrag.list.insertBefore(colDrag.tile, below ? other.nextSibling : other);
  colDrag.moved = true;
}, { passive: false });
function colDragEnd() {
  if (!colDrag) return;
  var d = colDrag;
  colDrag = null;
  d.tile.classList.remove("dragging");
  if (!d.moved || !data) return;
  var g = data.colGroups || { groups: [], map: {} };
  var order = [], map = {}, gid = "";
  [].forEach.call(d.list.children, function (el) {
    if (el.classList.contains("grp-head")) gid = el.getAttribute("data-gid") || "";
    var cid = el.getAttribute("data-cid");
    if (!cid) return;
    order.push(Number(cid));
    if (gid) map[cid] = gid;
  });
  if (!g.groups.length) map = g.map;
  post("/api/colgroups", { groups: g.groups, map: map, order: order }, function (r) { if (r && r.colGroups) data.colGroups = r.colGroups; });
}
document.addEventListener("pointerup", colDragEnd);
document.addEventListener("pointercancel", colDragEnd);
document.addEventListener("pointerdown", function () { pressing = true; });
document.addEventListener("pointerup", function () { setTimeout(function () { pressing = false; }, 80); });
document.addEventListener("pointercancel", function () { pressing = false; });

// sign-up: is the name still free? (a little rocket when it is)
var nameT = 0;
function nameCheck(v) {
  var el = document.getElementById("uok");
  if (!el) return;
  fetch("/api/name-free?name=" + encodeURIComponent(v)).then(function (r) { return r.json(); }).then(function (a) {
    var e2 = document.getElementById("uok");
    if (!e2 || document.getElementById("u").value !== v) return;
    e2.className = "uok " + (a.ok ? "ok" : "no");
    e2.textContent = a.ok ? "🚀 free" : "✖ " + a.why;
  });
}
document.addEventListener("input", function(e){
  var key=e.target.getAttribute && e.target.getAttribute("data-heal-count");
  if(!key || !data || !data.hospital)return;
  var u=data.hospital.wounded.find(function(x){return x.key===key});if(!u)return;
  healSelection[key]=Math.min(u.count,Math.max(0,Math.floor(Number(e.target.value)||0)));
  renderColony(data);renderSheet();
});
document.addEventListener("input", function (e) {
  if (!e.target || !e.target.getAttribute || !e.target.getAttribute("data-namecheck")) return;
  clearTimeout(nameT);
  var v = e.target.value.trim();
  var el = document.getElementById("uok");
  if (el) { el.textContent = ""; el.className = "uok"; }
  if (v.length >= 3) nameT = setTimeout(function () { nameCheck(v); }, 350);
});

// typed notes survive the automatic refresh
var jpNotes = {};
document.addEventListener("input", function (e) {
  var t = e.target;
  if (!t || !t.id) return;
  if (t.id === "lfaNote") lfaForm = t.value;
  else if (t.id === "amarkNote" && amarkEdit) amarkEdit.note = t.value;
  else if (t.id.indexOf("jpnote-") === 0) jpNotes[t.id.slice(7)] = t.value;
});

// 🐫 trader slider
document.addEventListener("input", function (e) {
  var t = e.target;
  if (!t || !t.getAttribute || !t.getAttribute("data-npc-range") || !map.sel) return;
  npcPick[t.getAttribute("data-npc-range")] = +t.value;
  var tr = traderAt(map.sel.x, map.sel.y), out = document.getElementById("npcAmtOut");
  if (tr && out) out.textContent = RES_ICON[tr.want] + " " + shortNum(+t.value) + " → " + RES_ICON[tr.give] + " " + shortNum(+t.value);
});

// player names: suggestions after the first letters (one shared list for every name field)
var plsugT = 0, plsugQ = "";
document.addEventListener("input", function (e) {
  var t = e.target;
  if (!t || !t.getAttribute || !t.getAttribute("data-plsug")) return;
  var v = t.value.trim();
  clearTimeout(plsugT);
  if (!v || v === plsugQ) return;
  plsugT = setTimeout(function () {
    plsugQ = v;
    fetch("/api/players/suggest?q=" + encodeURIComponent(v)).then(function (r) { return r.json(); }).then(function (a) {
      var dl = document.getElementById("plsug");
      if (!dl) { dl = document.createElement("datalist"); dl.id = "plsug"; document.body.appendChild(dl); }
      dl.innerHTML = (a.names || []).map(function (n) { return '<option value="' + esc(n) + '">'; }).join("");
    });
  }, 180);
});
document.addEventListener("input", function (e) {
  var t = e.target;
  if (!t.getAttribute) return;
  var key = t.getAttribute("data-count");
  if (key) trainCount[key] = t.value;
  var cmp = t.getAttribute("data-cmp");
  if (cmp) compose[cmp] = t.value;
  var simAll = t.getAttribute("data-sim-allup");
  if (simAll && sim && t.value !== "") {
    var side = sim[simAll];
    var tr = sim.setup.tribes[side.tribe];
    side.ups = {};
    tr.units.forEach(function (u) { side.ups[u.key] = parseInt(t.value, 10) || 0; });
    renderSheet();
    runSim();
    return;
  }
  var simKey = t.getAttribute("data-sim");
  if (simKey && sim) {
    if (simKey.indexOf(".ups.") > 0) t.classList.toggle("on", (parseInt(t.value, 10) || 0) > 0);
    if (simKey.indexOf(".troops.") > 0 && t.parentNode) t.parentNode.classList.toggle("has", (parseInt(t.value, 10) || 0) > 0);
    var text = simKey === "atk.tribe" || simKey === "def.tribe" || simKey === "def.kind";
    simSet(simKey, text ? t.value : parseInt(t.value, 10) || 0);
    if (simKey === "luck") {
      var ll = document.getElementById("simluck");
      if (ll) ll.textContent = (sim.luck > 0 ? "+" : "") + sim.luck + "%";
    }
    if (t.hasAttribute("data-sim-redraw")) {
      if (simKey === "atk.tribe") sim.atk.troops = {};
      if (simKey === "def.tribe") sim.def.troops = {};
      sim.spiedAt = null;
      renderSheet();
    }
    runSim();
  }
  var presetInput=t.getAttribute('data-farm-default');
  if(presetInput){var parts=presetInput.split(':'),list=farmList(parts[0]);if(list){if(!list.defaults)list.defaults=farmDefaultTroops(list);list.defaults[parts[1]]=Math.min(10000000,Math.max(0,parseInt(t.value,10)||0));farmSave();}}
  var addCount=t.getAttribute('data-farm-addcount');
  if(addCount&&farmPick)farmPick.troops[addCount]=Math.min(10000000,Math.max(0,parseInt(t.value,10)||0));
  var ft = t.getAttribute("data-farm-troop");
  if (ft) {
    var fp = ft.split(":");
    var fL = farmList(fp[0]);
    var fE = fL && farmEntry(fL, fp[1]);
    if (fE) { fE.troops[fp[2]] = Math.max(0, parseInt(t.value, 10) || 0); farmSave(); }
  }
  var fn = t.getAttribute("data-farm-name");
  if (fn && farmList(fn)) { farmList(fn).name = t.value.slice(0, 30) || "Farm list"; farmSave(); }
  var wktPath = t.getAttribute("data-wkt");
  if (wktPath) {
    var wp = wktPath.split(".");
    var obj = wkt[wp[0]];
    for (var wi = 1; wi < wp.length - 1; wi++) obj = obj[wp[wi]];
    var last = wp[wp.length - 1];
    var raw = t.value;
    obj[last] = t.tagName === "SELECT" && !/^[0-9]+$/.test(raw) ? raw : raw === "" ? "" : t.tagName === "SELECT" ? parseInt(raw, 10) : raw;
    if (wktPath === "lv.what") obj[last] = raw;
    renderSheet();
  }
  if (t.getAttribute("data-wiki-q")) {
    wiki.q = t.value.trim();
    renderSheet();
  }
  if (t.getAttribute("data-wiki-bsel")) {
    wiki.bopen = t.value;
    renderSheet();
  }
  if (t.getAttribute("data-gname") && gedit) {
    var gnid = t.getAttribute("data-gname");
    gedit.groups.forEach(function (x) { if (x.id === gnid) x.name = t.value; });
  }
  if (t.getAttribute("data-mark-label")) mkf.label = t.value;
  var pyk = t.getAttribute("data-pyl");
  if (pyk) {
    var pyp = pyk.split(":");
    if (pyForm.key !== pyp[0]) { RES.forEach(function (k) { pyForm[k] = ""; }); pyForm.key = pyp[0]; }
    pyForm[pyp[1]] = t.value;
    renderTileInfo();
  }
  if (t.getAttribute("data-hero-name")) heroNameEdit = t.value;
  if (t.getAttribute("data-hero-take")) {
    var htk = t.getAttribute("data-hero-take");
    heroTake[htk] = Math.max(0, Math.floor(Number(t.value) || 0));
    if (sheet && sheet.kind === "stash-transfer") {
      heroTake[htk] = Math.min(Number(t.max) || 0, heroTake[htk]);
      t.value = heroTake[htk];
      var result = document.querySelector('[data-stash-result="' + htk + '"]');
      if (result) result.textContent = Math.floor(data.res[htk] + heroTake[htk]).toLocaleString();
      var shortage = document.querySelector('[data-stash-short="' + htk + '"]');
      if (shortage) { var left = Math.max(0, (heroNeed[htk] || 0) - heroTake[htk]); shortage.hidden = !left; shortage.textContent = left ? 'Still missing ' + shortNum(left) : ''; }
    }
    // keep the slider and the box of that resource together
    var twins = document.querySelectorAll('[data-hero-take="' + htk + '"]');
    for (var ti = 0; ti < twins.length; ti++) if (twins[ti] !== t) twins[ti].value = heroTake[htk];
  }
  var alk = t.getAttribute("data-ally");
  if (alk) {
    allyForm[alk] = t.value;
    // show/hide the save buttons without losing the cursor
    if ((alk === "about" || alk === "bio") && data) renderColony(data);
  }
  var rtKey = t.getAttribute("data-rt");
  if (rtKey) {
    rt[rtKey] = t.type === "checkbox" ? t.checked : t.value;
    if (rtKey === "allSurplus" && data) renderSheet();
  }
  var ndKey = t.getAttribute("data-nd") || t.getAttribute("data-ndr");
  if (ndKey && nd && data) {
    var ndv = Math.max(0, Math.min(ndCap(data, ndKey), parseInt(t.value, 10) || 0));
    nd.t[ndKey] = ndv;
    ndFix(data, ndKey);
    updateNpc(data);
  }
  var mkKey = t.getAttribute("data-mk");
  if (mkKey) {
    mk[mkKey] = t.value;
    updateMarketInfo();
  }
  var rk = t.getAttribute("data-recall-count");
  if (rk) recallCount[rk] = t.value;
  var rdKey = t.getAttribute("data-rd");
  if (rdKey) { rd[rdKey] = t.value; renderSheet(); }
  // 🔎 pace reader: "left at" and "travel time" fill each other in
  var pcId = t.getAttribute("data-pace") || t.getAttribute("data-pace-left");
  var pcm = pcId && data ? data.movements.filter(function (x) { return String(x.id) === pcId; })[0] : null;
  if (pcm) {
    var ps = paceState(pcm);
    var byLeft = t.hasAttribute("data-pace-left");
    if (byLeft) { ps.left = t.value; ps.trip = paceTripFromLeft(pcm, t.value); }
    else { ps.trip = t.value; ps.left = paceLeftFromTrip(pcm, t.value); }
    var other = document.querySelector(byLeft ? '[data-pace="' + pcId + '"]' : '[data-pace-left="' + pcId + '"]');
    if (other) other.value = byLeft ? ps.trip : ps.left;
    var pcEl = document.getElementById("pace-res-" + pcId);
    if (pcEl) pcEl.innerHTML = paceResult(pcm);
  }
  var wvn = t.getAttribute("data-wv-n");
  if (wvn && waves) {
    var wvp = wvn.split(":");
    waves.list[Number(wvp[0])].troops[wvp[1]] = Math.max(0, parseInt(t.value, 10) || 0);
    updateWaveInfo();
  }
  if (t.getAttribute("data-wv-landat") && waves) {
    waves.land = t.value;
    updateWaveInfo();
  }
  var presetCount=t.getAttribute('data-army-preset-count');if(presetCount)sendCount[presetCount]=Math.max(0,parseInt(t.value,10)||0);
  var sk = t.getAttribute("data-send-count");
  if (sk) {
    sendCount[sk] = t.value;
    updateSendInfo();
  }
});

document.addEventListener("submit", function (e) {
  e.preventDefault();
  if (e.target.id === "msgform") {
    post("/api/messages/send", { to: compose.to, subject: compose.subject, body: compose.body }, function () {
      toast("✉️ Message sent!", true);
      compose = { to: "", subject: "", body: "" };
      msgBox = "sent";
      loadMessages();
    });
    return;
  }
  if (e.target.id === "respform") {
    var respBtn = e.target.querySelector("button");
    if (Date.now() - delArm > 6000) { delArm = Date.now(); respBtn.textContent = "⚠️ Tap again to respawn"; sfx("click"); return; }
    delArm = 0;
    closeSheet();
    hopState = { t: "", name: accountInfo ? accountInfo.username : "", respawn: true };
    renderAuth();
    return;
  }
  if (e.target.id === "delform") {
    var delBtn = e.target.querySelector("button");
    if (Date.now() - delArm > 6000) { delArm = Date.now(); delBtn.textContent = "⚠️ Tap again to delete forever"; sfx("click"); return; }
    delArm = 0;
    apost("/api/acct/delete", { password: document.getElementById("del0").value }, function (d) {
      playFlag(false);
      acct = { ok: false };
      loggedIn = false;
      renderAuth();
      toast("Your account was deleted. Goodbye, colonist!" + (d.failed && d.failed.length ? " (Not reached: " + d.failed.join(", ") + ". Ask its owner to remove you.)" : ""));
    });
    return;
  }
  if (e.target.id === "pwform") {
    var p1 = document.getElementById("pw1").value;
    if (p1 !== document.getElementById("pw2").value) { toast("The two new passwords are not the same"); return; }
    apost("/api/acct/password", { old: document.getElementById("pw0").value, password: p1 }, function () {
      toast("🔐 Password changed! Other devices were logged out.", true);
      acctFold = false;
      renderAuth();
    });
  } else if (e.target.id === "renameform") {
    post("/api/rename", { name: document.getElementById("rn").value }, function () {
      toast("✏️ New name, new glory!", true);
      closeSheet();
    });
  } else if (e.target.id === "offerform") {
    var ofv = function (id) { var el = document.getElementById(id); return el ? (el.type === "checkbox" ? el.checked : el.value) : ""; };
    post("/api/market/offer", { give: ofv("of-give"), giveAmt: Number(ofv("of-ga")), want: ofv("of-want"), wantAmt: Number(ofv("of-wa")), allyOnly: ofv("of-ally") }, function () { mkOffers = null; toast("📋 Offer posted"); });
  } else if (e.target.id === "tradeform") {
    var goods = {};
    RES.forEach(function (k) { goods[k] = parseInt(mk[k], 10) || 0; });
    post("/api/trade", { x: parseInt(mk.x, 10), y: parseInt(mk.y, 10), res: goods }, function () {
      RES.forEach(function (k) { mk[k] = ""; });
      toast("🐪 The merchants are on their way!", true);
    });
  } else if (e.target.id === "routeform") {
    var sel = document.querySelector('[data-rt="to"]');
    var goodsR = {};
    RES.forEach(function (k) { goodsR[k] = parseInt(rt[k], 10) || 0; });
    var rtStart = rt.startAt ? new Date(rt.startAt).getTime() : NaN;
    var rtLand = rt.landAt ? new Date(rt.landAt).getTime() : NaN;
    var clockOffset = serverNow() - Date.now();
    if (!isNaN(rtStart)) rtStart += clockOffset;
    if (!isNaN(rtLand)) rtLand += clockOffset;
    post("/api/routes/add", { to: Number(sel ? sel.value : rt.to), res: goodsR, allSurplus: !!rt.allSurplus, every: Number(rt.every), keep: parseInt(rt.keep, 10) || 0, startAt: isNaN(rtStart) ? "" : rtStart, landAt: isNaN(rtLand) ? "" : rtLand }, function () {
      RES.forEach(function (k) { rt[k] = ""; });
      rt.allSurplus = false;
      rt.startAt = "";
      rt.landAt = "";
      toast("🔁 Automatic merchants hired!", true);
    });
  } else if (e.target.id === "swapform") {
    post("/api/swap", { give: mk.give, get: mk.get, amount: parseInt(mk.amount, 10) || 0 }, function () {
      mk.amount = "";
      toast("💱 Deal! Pleasure doing business.", true);
    });
  } else if (e.target.id === "authform") {
    submitAuth();
  } else if (e.target.id === "forgotform") {
    fetch("/api/forgot", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ email: document.getElementById("fe").value, lang: curLang() }) }).then(function (r) { return r.json(); }).then(function (d) {
      if (d.error) { toast(d.error); return; }
      toast("📧 If that address has an account, a link is on its way");
      authMode = "login";
      renderAuth();
    });
  } else if (e.target.id === "emailform") {
    apost("/api/email", { email: document.getElementById("em0").value, lang: curLang() }, function () { toast("📬 Check your inbox to confirm"); });
  } else if (e.target.id === "gotoform") {
    var gx = parseInt(document.getElementById("gx").value, 10);
    var gy = parseInt(document.getElementById("gy").value, 10);
    if (isNaN(gx) || isNaN(gy)) { toast("Enter two numbers, captain"); return; }
    document.activeElement.blur();
    selectTile(gx, gy);
    glideTo(gx, gy, 500);
  }
});

