// The pictures only get a new address when the art folder really changes, so a game update
// does not make every player download all pictures again.
const ART_VERSION = (() => {
  try {
    const dir = require("path").join(__dirname, "art"), h = require("crypto").createHash("sha1");
    for (const f of require("fs").readdirSync(dir).sort()) { const st = require("fs").statSync(require("path").join(dir, f)); h.update(f + ":" + st.size + ":" + Math.floor(st.mtimeMs) + ";"); }
    return h.digest("hex").slice(0, 10);
  } catch (e) { return GAME_VERSION; }
})();
function artJson() { return JSON.stringify({ v: ART_VERSION, t: FIELD_ART_META }); }
app.get("/art/:file", (req, res) => {
  const m = /^([a-z0-9-]+)\.webp$/.exec(req.params.file || "");
  if (!m || (!FIELD_ART_META[m[1]] && m[1] !== "hero")) return res.status(404).end();
  require("fs").readFile(require("path").join(__dirname, "art", m[1] + ".webp"), (err, buf) => {
    if (err) return res.status(404).end();
    res.setHeader("Content-Type", "image/webp");
    res.setHeader("Cache-Control", "public, max-age=31536000, immutable");
    res.send(buf);
  });
});
app.get("/shots/:file", (req, res) => {
  const m = /^([a-z]+)\.webp$/.exec(req.params.file || "");
  if (!m || !LANDING_SHOTS[m[1]]) return res.status(404).end();
  res.setHeader("Content-Type", "image/webp");
  res.setHeader("Cache-Control", "public, max-age=604800");
  res.send(Buffer.from(LANDING_SHOTS[m[1]], "base64"));
});
// =====================================================================
//  📲 WEB PUSH: alerts even when MarsL is closed (incoming attacks, finished
//  construction). Standard Web Push (VAPID + aes128gcm), no extra library.
// =====================================================================
const pushCrypto = require("crypto");
const pushHttps = require("https");
db.exec("CREATE TABLE IF NOT EXISTS push_subs (id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER NOT NULL, endpoint TEXT NOT NULL UNIQUE, p256dh TEXT NOT NULL, auth TEXT NOT NULL, created_at INTEGER NOT NULL)");
function b64u(buf) { return Buffer.from(buf).toString("base64").replace(/\+/g, "-").replace(/\//g, "_").replace(/=+$/, ""); }
function unb64u(s) { return Buffer.from(String(s).replace(/-/g, "+").replace(/_/g, "/"), "base64"); }
let vapidCache = null;
function vapidKeys() {
  if (vapidCache) return vapidCache;
  let jwk = null;
  try { jwk = JSON.parse(settingOf("vapid_jwk", "") || "null"); } catch (e) {}
  if (!jwk || !jwk.d) {
    const kp = pushCrypto.generateKeyPairSync("ec", { namedCurve: "prime256v1" });
    jwk = kp.privateKey.export({ format: "jwk" });
    setSetting("vapid_jwk", JSON.stringify(jwk));
  }
  const priv = pushCrypto.createPrivateKey({ key: jwk, format: "jwk" });
  const pub = Buffer.concat([Buffer.from([4]), unb64u(jwk.x), unb64u(jwk.y)]);
  vapidCache = { priv, pub, pubB64: b64u(pub) };
  return vapidCache;
}
function vapidAuth(endpoint) {
  const V = vapidKeys(), u = new URL(endpoint);
  const head = b64u(JSON.stringify({ typ: "JWT", alg: "ES256" }));
  const body = b64u(JSON.stringify({ aud: u.origin, exp: Math.floor(Date.now() / 1000) + 12 * 3600, sub: process.env.PUSH_CONTACT || "https://marsl-game.com" }));
  const sig = pushCrypto.sign("sha256", Buffer.from(head + "." + body), { key: V.priv, dsaEncoding: "ieee-p1363" });
  return "vapid t=" + head + "." + body + "." + b64u(sig) + ", k=" + V.pubB64;
}
function pushEncrypt(sub, payload) {
  const ua = unb64u(sub.p256dh), auth = unb64u(sub.auth);
  const ecdh = pushCrypto.createECDH("prime256v1");
  const asPub = ecdh.generateKeys();
  const shared = ecdh.computeSecret(ua);
  const ikm = Buffer.from(pushCrypto.hkdfSync("sha256", shared, auth, Buffer.concat([Buffer.from("WebPush: info\0"), ua, asPub]), 32));
  const salt = pushCrypto.randomBytes(16);
  const cek = Buffer.from(pushCrypto.hkdfSync("sha256", ikm, salt, Buffer.from("Content-Encoding: aes128gcm\0"), 16));
  const nonce = Buffer.from(pushCrypto.hkdfSync("sha256", ikm, salt, Buffer.from("Content-Encoding: nonce\0"), 12));
  const c = pushCrypto.createCipheriv("aes-128-gcm", cek, nonce);
  const enc = Buffer.concat([c.update(Buffer.concat([Buffer.from(payload), Buffer.from([2])])), c.final(), c.getAuthTag()]);
  const rs = Buffer.alloc(4); rs.writeUInt32BE(4096);
  return Buffer.concat([salt, rs, Buffer.from([asPub.length]), asPub, enc]);
}
function pushSend(sub, msg) {
  let body;
  try { body = pushEncrypt(sub, JSON.stringify(msg)); } catch (e) { return; }
  const u = new URL(sub.endpoint);
  const req = pushHttps.request({ method: "POST", hostname: u.hostname, port: u.port || 443, path: u.pathname + u.search, timeout: 10000,
    headers: { Authorization: vapidAuth(sub.endpoint), TTL: "3600", Urgency: msg.urgent ? "high" : "normal", "Content-Encoding": "aes128gcm", "Content-Type": "application/octet-stream", "Content-Length": body.length } }, (res) => {
    if (res.statusCode === 404 || res.statusCode === 410) db.prepare("DELETE FROM push_subs WHERE endpoint = ?").run(sub.endpoint);
    res.resume();
  });
  req.on("error", () => {});
  req.on("timeout", () => req.destroy());
  req.end(body);
}
function pushTo(userId, msg) {
  if (!userId || BOT_IDS.has(userId)) return;
  for (const sub of db.prepare("SELECT endpoint, p256dh, auth FROM push_subs WHERE user_id = ?").all(userId)) pushSend(sub, Object.assign({ server: thisServerName() }, msg));
}
app.get("/api/push/key", (req, res) => res.json({ key: vapidKeys().pubB64 }));
app.post("/api/push/subscribe", requireLogin, (req, res) => {
  const b = req.body || {}, k = b.keys || {};
  if (!/^https:\/\//.test(String(b.endpoint || "")) || !k.p256dh || !k.auth || String(b.endpoint).length > 1000) return res.status(400).json({ error: "This browser sent no usable push address" });
  db.prepare("INSERT INTO push_subs (user_id, endpoint, p256dh, auth, created_at) VALUES (?, ?, ?, ?, ?) ON CONFLICT (endpoint) DO UPDATE SET user_id = excluded.user_id, p256dh = excluded.p256dh, auth = excluded.auth").run(req.user.id, String(b.endpoint), String(k.p256dh), String(k.auth), Date.now());
  res.json({ ok: true });
});
app.post("/api/push/unsubscribe", requireLogin, (req, res) => {
  db.prepare("DELETE FROM push_subs WHERE user_id = ? AND endpoint = ?").run(req.user.id, String((req.body || {}).endpoint || ""));
  res.json({ ok: true });
});
// the service worker: shows the alert and opens the game on a tap
app.get("/sw.js", (req, res) => {
  res.setHeader("Content-Type", "application/javascript");
  res.setHeader("Cache-Control", "no-cache");
  res.end([
    "self.addEventListener('push', function (e) {",
    "  var d = {}; try { d = e.data ? e.data.json() : {}; } catch (x) {}",
    "  var body = d.body || '';",
    "  if (d.at) body += ' · ' + new Date(d.at).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });",
    "  e.waitUntil(self.registration.showNotification(d.title || 'MarsL', { body: body, tag: d.tag || 'marsl', icon: '/icon-192.png', badge: '/icon-192.png', renotify: !!d.urgent }));",
    "});",
    "self.addEventListener('notificationclick', function (e) {",
    "  e.notification.close();",
    "  e.waitUntil(clients.matchAll({ type: 'window' }).then(function (l) { for (var i = 0; i < l.length; i++) if ('focus' in l[i]) return l[i].focus(); return clients.openWindow('/'); }));",
    "});",
  ].join("\n"));
});
// finished construction while the player is away
let pushBuildSeen = Date.now();
setInterval(() => {
  try {
    const now = Date.now(), from = pushBuildSeen;
    pushBuildSeen = now;
    for (const u of db.prepare("SELECT DISTINCT push_subs.user_id AS id, users.last_seen FROM push_subs JOIN users ON users.id = push_subs.user_id").all()) {
      if (now - (u.last_seen || 0) < 120000) continue; // they are playing right now
      for (const c of db.prepare("SELECT id, name, tribe, state FROM colonies WHERE user_id = ?").all(u.id)) {
        let st; try { st = JSON.parse(c.state); } catch (e) { continue; }
        const names = tribeOf(c.tribe).names;
        for (const q of st.queue || []) {
          if (!q.finishAt || q.finishAt <= from || q.finishAt > now) continue;
          const type = q.kind === "field" ? (st.fields[q.slot] || {}).type : q.type || (st.buildings[q.slot] || {}).type;
          pushTo(u.id, { title: "🏗️ Construction done", body: (names[type] ? names[type][0] : "A building") + " level " + q.targetLevel + " in " + c.name, tag: "build" + c.id });
        }
      }
    }
  } catch (e) { console.error("push build", e); }
}, 60000);

app.get("/icon.svg", (req, res) => {
  res.setHeader("Content-Type", "image/svg+xml");
  res.setHeader("Cache-Control", "public, max-age=86400");
  res.end(ICON_SVG);
});
// ---------- app icon as PNG (phones want PNG), drawn pixel by pixel ----------
const zlibIcon = require("zlib");
function iconPng(size) {
  const ss = 3; // smoothing: 3x3 samples per pixel
  const px = Buffer.alloc(size * size * 4);
  const hex = (h) => [parseInt(h.slice(1, 3), 16), parseInt(h.slice(3, 5), 16), parseInt(h.slice(5, 7), 16)];
  const INK = hex("#2a1630"), PLANET = hex("#c4502e"), CRATER = hex("#8c2f1c"), GOLD = hex("#ffd23f");
  const TOP = hex("#ffb26b"), BOT = hex("#f2784b");
  const rot = (-18 * Math.PI) / 180;
  function colorAt(u, v) {
    // background: sunset gradient
    let c = TOP.map((t, i) => t + (BOT[i] - t) * v);
    // the ring around the planet (tilted ellipse)
    const rx = 0.4, ry = 0.1, cx = 0.5, cy = 0.56;
    const dx = u - cx, dy = v - cy;
    const ex = dx * Math.cos(rot) + dy * Math.sin(rot);
    const ey = -dx * Math.sin(rot) + dy * Math.cos(rot);
    const e = Math.sqrt((ex / rx) ** 2 + (ey / ry) ** 2);
    const onRing = Math.abs(e - 1) < 0.11;
    const onGold = Math.abs(e - 1) < 0.04;
    const ringColor = onGold ? GOLD : INK;
    // the planet
    const pr = Math.hypot(u - 0.5, v - 0.5);
    const R = 0.25;
    if (onRing && ey < 0) c = ringColor; // back half of the ring
    if (pr < R) {
      c = pr > R - 0.03 ? INK : PLANET;
      const craters = [[0.43, 0.43, 0.055], [0.58, 0.58, 0.04], [0.57, 0.4, 0.025]];
      for (const k of craters) if (pr < R - 0.03 && Math.hypot(u - k[0], v - k[1]) < k[2]) c = CRATER;
    }
    if (onRing && ey >= 0) c = ringColor; // front half of the ring
    return c;
  }
  for (let y = 0; y < size; y++) {
    for (let x = 0; x < size; x++) {
      const acc = [0, 0, 0];
      for (let sy = 0; sy < ss; sy++) for (let sx = 0; sx < ss; sx++) {
        const c = colorAt((x + (sx + 0.5) / ss) / size, (y + (sy + 0.5) / ss) / size);
        acc[0] += c[0]; acc[1] += c[1]; acc[2] += c[2];
      }
      const o = (y * size + x) * 4;
      px[o] = Math.round(acc[0] / (ss * ss));
      px[o + 1] = Math.round(acc[1] / (ss * ss));
      px[o + 2] = Math.round(acc[2] / (ss * ss));
      px[o + 3] = 255;
    }
  }
  // pack it into a PNG file
  const raw = Buffer.alloc((size * 4 + 1) * size);
  for (let y = 0; y < size; y++) {
    raw[y * (size * 4 + 1)] = 0;
    px.copy(raw, y * (size * 4 + 1) + 1, y * size * 4, (y + 1) * size * 4);
  }
  const crcTable = [];
  for (let n = 0; n < 256; n++) {
    let c = n;
    for (let k = 0; k < 8; k++) c = c & 1 ? 0xedb88320 ^ (c >>> 1) : c >>> 1;
    crcTable[n] = c >>> 0;
  }
  const crc = (buf) => {
    let c = 0xffffffff;
    for (const b of buf) c = crcTable[(c ^ b) & 0xff] ^ (c >>> 8);
    return (c ^ 0xffffffff) >>> 0;
  };
  const chunk = (type, data) => {
    const len = Buffer.alloc(4);
    len.writeUInt32BE(data.length);
    const td = Buffer.concat([Buffer.from(type), data]);
    const c = Buffer.alloc(4);
    c.writeUInt32BE(crc(td));
    return Buffer.concat([len, td, c]);
  };
  const ihdr = Buffer.alloc(13);
  ihdr.writeUInt32BE(size, 0);
  ihdr.writeUInt32BE(size, 4);
  ihdr[8] = 8; ihdr[9] = 6; ihdr[10] = 0; ihdr[11] = 0; ihdr[12] = 0;
  return Buffer.concat([
    Buffer.from([137, 80, 78, 71, 13, 10, 26, 10]),
    chunk("IHDR", ihdr),
    chunk("IDAT", zlibIcon.deflateSync(raw, { level: 9 })),
    chunk("IEND", Buffer.alloc(0)),
  ]);
}
const ICON_PNG = {}; // made once, on first request
function iconFor(size) {
  if (!ICON_PNG[size]) ICON_PNG[size] = iconPng(size);
  return ICON_PNG[size];
}
for (const size of [192, 512]) {
  app.get("/icon-" + size + ".png", (req, res) => {
    res.setHeader("Content-Type", "image/png");
    res.setHeader("Cache-Control", "public, max-age=86400");
    res.end(iconFor(size));
  });
}
app.get("/manifest.webmanifest", (req, res) => {
  res.setHeader("Content-Type", "application/manifest+json");
  res.end(
    JSON.stringify({
      name: "MarsL",
      short_name: "MarsL",
      start_url: "/",
      display: "standalone",
      orientation: "portrait",
      background_color: "#8c2f1c",
      theme_color: "#f2784b",
      icons: [
        { src: "/icon-192.png", sizes: "192x192", type: "image/png", purpose: "any" },
        { src: "/icon-512.png", sizes: "512x512", type: "image/png", purpose: "any" },
        { src: "/icon-512.png", sizes: "512x512", type: "image/png", purpose: "maskable" },
      ],
    })
  );
});

// Unknown addresses and broken requests get a short answer - never the
// inner details of the server (those could help an attacker).
app.use("/api", (req, res) => res.status(404).json({ error: "Unknown request" }));
app.use((err, req, res, next) => {
  if (err && err.type === "entity.too.large") return res.status(413).json({ error: "That request is too big" });
  if (err && err.type === "entity.parse.failed") return res.status(400).json({ error: "Broken request" });
  console.error(err);
  res.status(500).json({ error: "Oops, something went wrong on Mars" });
});

app.listen(PORT, HOST, () => {
  console.log("MarsL is running!");
  console.log("  On this computer:   http://localhost:" + PORT);
  // the addresses for phones and other computers in the same Wi-Fi
  const nets = require("os").networkInterfaces();
  for (const name in nets) {
    for (const n of nets[name]) {
      if (n.family !== "IPv4" || n.internal || (HOST && HOST !== n.address)) continue;
      const via = n.address.startsWith("100.") ? "  Through Tailscale:  " : "  In the same Wi-Fi:  ";
      console.log(via + "http://" + n.address + ":" + PORT);
    }
  }
  console.log(INVITE_CODE ? "  Invite code for new players:  " + INVITE_CODE : "  Anybody may register (no invite code).");
  console.log("  Admin page:         http://localhost:" + PORT + "/admin");
  console.log("  Owner code:         " + OWNER_CODE + "   (keep it secret! only needed once to become owner)");
});
